      "path": "plugin/index.js",
      "content": "/**\n * agent-clinic 的 DeepSeek Harness 插件入口\n *\n * 本文件让同一个仓库**既能当 Skill 装，也能当 Plugin 装**：\n *   - Skill  路径：把仓库目录拷到 ~/.agents/skills/agent-clinic/\n *   - Plugin 路径：dsh plugin --profile <p> add -w <repo>\n *\n * 插件契约（对照真实插件 @shengsheng/dsh-taskboard 逆向确认）：\n *   - 导出 `name`（短名，字符串）\n *   - 导出 `Config`（schemastery schema）\n *   - 导出 `apply(ctx, config)` 函数\n *   - package.json 声明 \"dsh\": { \"bundle\": { \"patch\": \"./cordis.patch.yml\" } }\n *\n * ⚠️ 本文件的对等依赖（@deepseek-ai/*）只在 DSH 运行环境内可解析，\n *    无法在本机独立验证。peer 一律用**动态导入 + 兜底**，保证：\n *      - 本地 `import()` 不报错（满足 DSH 的冒烟测试：name + apply）\n *      - DSH 内正常注册工具\n */\n\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { scanSessions, resolveSessionsRoot, limitSessions } from '../src/adapters/dsh.mjs';\nimport { summarize, topTools, num, pct } from '../src/summary.mjs';\nimport { hasZstdSupport } from '../src/adapters/zstd-frames.mjs';\nimport { renderEvidence } from '../src/evidence/index.mjs';\nimport { buildReport, analyze, analyzeLive } from '../src/report.mjs';\n// 决策 D4：K1/K2 的指纹采集同样要在**扫描前**开好（适配层在解析时算加盐哈希）。\n// 插件进程若写不了 ~/.agent-clinic（沙箱/权限），beginFingerprintRun 会如实返回不可用，\n// K1/K2 于是带 note 出现在\"未检测到异常\"里说明\"本次未采集指纹\"——不静默装成\"没问题\"。\nimport { beginFingerprintRun } from '../src/privacy/fingerprints.mjs';\n// M3.5 处方反馈闭环：面板路径也要应用\"记住的拒绝\"（否则 CLI 撤掉的处方会在面板里复活）\nimport { feedbackOptions } from '../src/prescriber/feedback.mjs';\n\n/**\n * 处方反馈 → analyze/buildReport 的选项。\n * 读坏了不崩（反馈是附加信息），但把错误带出去，让报告如实写进\"处方反馈没读到\"一节。\n */\nfunction feedbackOpts() {\n  const fb = feedbackOptions();\n  return {\n    rejected: fb.rejected,\n    interested: fb.interested,\n    feedback: fb.store,\n    feedbackError: fb.error,\n  };\n}\n\n/** 插件短名（cordis patch 里的 id / name 与之对应） */\nexport const name = 'agent-clinic';\n\n/**\n * API 版本号，随宿主响应回传。\n *\n * 客户端用同一个常量（plugin/client.js 的 CLIENT_VERSION）比对，识别\n * 「插件文件已更新到磁盘、但 Harness 进程仍跑旧代码」的情况。\n * 插件只在启动时装载，更新后必须重启才生效；若不显式提示，\n * 用户只会看到面板内容没变，无法判断该做什么。\n * 改动 /api/agent-clinic/report 的响应结构时，两边一起 +1。\n * v15（决策 D4）：response.data 增加可选的 `fingerprintNotice`（指纹快照不可用/写失败时提示）。\n */\nexport const API_VERSION = '15';\n\n/**\n * 面板「联网现搜」的预算上限（毫秒）。\n * 比 CLI 的默认值小：面板是交互式的，让用户等十几秒不如早点给结果。\n */\nconst LIVE_BUDGET_MS = 10000;\n\n// ---------------------------------------------------------------------------\n// Config：优先用 schemastery；本地无 peer 时退化为朴素描述，保证可导入\n// ---------------------------------------------------------------------------\nlet z = null;\ntry {\n  z = (await import('@deepseek-ai/schemastery')).default;\n} catch {\n  z = null; // 本地无 DSH peer —— 仅在 DSH 环境内需要真正的 schema\n}\n\nexport const Config = z\n  ? z.object({\n      dshHome: z.string(),\n      maxSessions: z.natural().min(1).default(500),\n      minRepeatCount: z.natural().min(2).default(3),\n      contextLines: z.natural().min(0).max(20).default(2),\n    })\n  : {\n      type: 'object',\n      properties: {\n        dshHome: { type: 'string' },\n        maxSessions: { type: 'number', default: 500 },\n        minRepeatCount: { type: 'number', default: 3 },\n        contextLines: { type: 'number', default: 2 },\n      },\n    };\n\n// ---------------------------------------------------------------------------\n// 业务逻辑（与 CLI 共用同一套 src/ 实现，避免两份真相）\n// ---------------------------------------------------------------------------\n\nfunction runScan(opts = {}) {\n  if (!hasZstdSupport()) {\n    return [\n      '运行环境不支持原生 zstd 解码，无法读取 DSH 会话文件。',\n      `当前 Node 版本：${process.version}（需要 >= 22.15.0）`,\n      '本工具不会静默跳过无法解码的数据。',\n    ].join('\\n');\n  }\n\n  const root = resolveSessionsRoot({ dshHome: opts.dshHome });\n  const scan = scanSessions({ dshHome: opts.dshHome });\n  const { global: g, perSession } = summarize(scan);\n\n  if (scan.fileCount === 0) {\n    return `未找到会话文件。\\n扫描目录：${root}`;\n  }\n\n  const lines = [];\n  lines.push(`扫描目录：${root}`);\n  lines.push(`会话文件：${scan.fileCount}`);\n  lines.push('');\n  for (const s of perSession) {\n    const id = String(s.sessionId).replace(/^session-/, '').slice(0, 12);\n    lines.push(\n      `  ${id}  帧=${s.frames} 行=${s.lines} 调用=${s.toolCalls} 错误=${s.errors}` +\n        ` in=${num(s.inputTokens)} out=${num(s.outputTokens)}${s.title ? `  ${s.title}` : ''}`,\n    );\n  }\n  lines.push('');\n  lines.push('===== 合计 =====');\n  lines.push(`会话=${g.sessions}  帧=${g.frames}  行=${g.lines}`);\n  lines.push(`工具调用=${g.toolCalls}  错误=${g.errors}  错误率=${pct(g.errorRate)}`);\n  lines.push(\n    `input=${num(g.inputTokens)}  output=${num(g.outputTokens)}  ` +\n      `cacheRead=${num(g.cacheReadTokens)}  cacheWrite=${num(g.cacheWriteTokens)}`,\n  );\n  lines.push(`cacheRead 占比=${pct(g.cacheReadShare)}`);\n  const tt = topTools(g, 8);\n  if (tt.length) lines.push(`TOP 工具：${tt.map(([k, v]) => `${k} ${v}`).join(' · ')}`);\n  if (g.badFrames || g.badLines) {\n    lines.push(`⚠ 数据完整性：坏帧 ${g.badFrames} / 坏行 ${g.badLines}`);\n  }\n  return lines.join('\\n');\n}\n\nfunction runShow(locator, context = 2) {\n  if (!locator) return '缺少参数：locator（形如 <file>#L<n>）';\n  try {\n    return renderEvidence(locator, { context });\n  } catch (e) {\n    return `无法展开证据：${e.message}`;\n  }\n}\n\n/**\n * 把插件 Config 里的旋钮翻译成诊断层的 opts。\n *\n * ⚠️ 第三轮验收（待优化报告 §3）：这三个旋钮此前**完全没接线** ——\n *    schema 声明了 `maxSessions` / `minRepeatCount`，用户在面板里改了、\n *    值也存下来了，但 `runAnalyze` 调 `analyze({scan, summary})` 时**没传 opts**，\n *    所以诊断层永远收到 undefined，改了不起任何作用、也没有任何提示。\n *    这恰恰是本工具的 C1 指标专门诊断的那类问题（\"旋钮改了没效果\"）。\n *\n * 这里的映射关系写明白，避免以后再断链：\n *   maxSessions     → 会话扫描上限（在 limitSessions 里生效）\n *   minRepeatCount  → E1/E5 的重复阈值（diagnostics 的 opts.minRepeatCount）\n *   contextLines    → 证据展开行数（CLI/插件两侧一致）\n */\nfunction analyzeOptsFromConfig(config = {}) {\n  const opts = {};\n  if (Number.isFinite(config.maxSessions) && config.maxSessions > 0) {\n    opts.maxSessions = config.maxSessions;\n  }\n  if (Number.isFinite(config.minRepeatCount) && config.minRepeatCount > 0) {\n    opts.minRepeatCount = config.minRepeatCount;\n  }\n  return opts;\n}\n\n/**\n * 指纹快照的一句话状态（决策 D4）：只在**有话要说**时返回（不可用 / 写失败）。\n * 写成功或本次没新观测都属于正常，不打扰用户。\n */\nfunction fingerprintNotice(out) {\n  if (!out) return null;\n  if (out.error) {\n    // phase='save'：写盘失败但本次**已判定**；phase='load'：没有盐，确实没判\n    if (out.phase === 'save') {\n      return `指纹快照写入失败：${out.error.message}（K1/K2 已按本次扫描判定；跨会话历史未累积）`;\n    }\n    return `指纹快照不可用：${out.error.message}（K1/K2 本次未判定）`;\n  }\n  return null;\n}\n\nfunction runReport(opts = {}, config = {}) {\n  if (!hasZstdSupport()) {\n    return `运行环境不支持原生 zstd 解码（需要 Node >= 22.15，当前 ${process.version}）。`;\n  }\n  const fp = beginFingerprintRun();\n  const scan = limitSessions(scanSessions({ dshHome: opts.dshHome }), config.maxSessions);\n  const summary = summarize(scan);\n  const text = buildReport(\n    { scan, summary },\n    { ...analyzeOptsFromConfig(config), ...fp.diagnosticOpts(scan), ...feedbackOpts() },\n  );\n  const notice = fingerprintNotice(fp.finish(scan));\n  return notice ? `${text}\\n\\n> ⚠ ${notice}\\n` : text;\n}\n\n/** 结构化体检结果（供客户端面板渲染卡片式 UI，避免解析 markdown 文本） */\nfunction runAnalyze(opts = {}, config = {}) {\n  if (!hasZstdSupport()) {\n    throw new Error(`运行环境不支持原生 zstd 解码（需要 Node >= 22.15，当前 ${process.version}）`);\n  }\n  const fp = beginFingerprintRun();\n  const scan = limitSessions(scanSessions({ dshHome: opts.dshHome }), config.maxSessions);\n  const summary = summarize(scan);\n  // opts 必须传下去：否则 maxSessions / minRepeatCount 就是\"改了没效果\"的旋钮\n  const data = analyze(\n    { scan, summary },\n    { ...analyzeOptsFromConfig(config), ...fp.diagnosticOpts(scan), ...feedbackOpts() },\n  );\n  const notice = fingerprintNotice(fp.finish(scan));\n  // 面板已经会渲染 notDetected 的 note；这里再单独挂一个字段，供将来显式提示\n  return notice ? { ...data, fingerprintNotice: notice } : data;\n}\n\n// ---------------------------------------------------------------------------\n// 实时监测：文件监听 + 轻量状态端点\n//\n// 现状：面板只有点「刷新」才重新扫描，用户在对话过程中看不到新出现的问题。\n//\n// 这里补上「准实时」：\n//   1. fs.watch 盯 ~/.dsh/sessions（根目录 + 各会话目录）\n//      —— DSH 每次工具调用都会追加写入会话文件，所以文件变化 ≈ 有新事件\n//   2. 命中后把缓存标记为脏；/watch 端点只在脏时才真正重扫\n//      （一次全量扫描约 130ms，不能每次轮询都跑）\n//   3. 客户端每 6 秒轮询一次 /watch，签名变化才拉全量报告\n//\n// 不用 DSH 内部的 session/event 流，是因为那套 API 属于内部契约、\n// 且 desktop profile 装不进去、本地无法验证；Node 的 fs API 足够且可测。\n// ---------------------------------------------------------------------------\n\nconst WATCH_DEBOUNCE_MS = 400;\n\nconst watchState = {\n  dshHome: null,\n  watchers: [],\n  dirty: true,\n  timer: null,\n  // 缓存最近一次体检结论的「签名」——用于判断是否真的发生了变化\n  signature: '',\n  count: 0,\n  ids: [],\n  generatedAt: null,\n};\n\nfunction signatureOf(data) {\n  return `${data.findings.length}|${data.findings\n    .map((f) => `${f.id}:${f.scope || ''}`)\n    .join(',')}|${data.header.sessions}|${data.header.toolCalls}`;\n}\n\nfunction refreshState(dshHome, config = {}) {\n  const data = runAnalyze({ dshHome }, config);\n  watchState.signature = signatureOf(data);\n  watchState.count = data.findings.length;\n  watchState.ids = data.findings.map((f) => f.id);\n  watchState.generatedAt = new Date().toISOString();\n  return data;\n}\n\n/** 轻量状态：签名变了客户端才去拉全量报告，所以要保证它足够便宜 */\nfunction currentState(dshHome, config = {}) {\n  if (watchState.dirty || watchState.signature === '') {\n    refreshState(dshHome, config);\n    watchState.dirty = false;\n  }\n  return {\n    ok: true,\n    version: API_VERSION,\n    count: watchState.count,\n    ids: watchState.ids,\n    signature: watchState.signature,\n    generatedAt: watchState.generatedAt,\n  };\n}\n\nfunction markDirty() {\n  watchState.dirty = true;\n  if (watchState.timer) return;\n  // 防抖：一次工具调用可能触发多个文件事件，短时间内的重复通知无意义\n  watchState.timer = setTimeout(() => {\n    watchState.timer = null;\n  }, WATCH_DEBOUNCE_MS);\n}\n\nfunction stopWatching() {\n  for (const w of watchState.watchers) {\n    try {\n      w.close();\n    } catch {\n      /* ignore */\n    }\n  }\n  watchState.watchers = [];\n  if (watchState.timer) {\n    clearTimeout(watchState.timer);\n    watchState.timer = null;\n  }\n}\n\n/** 监听会话目录。fs.watch 在 Windows 上对递归不可靠，因此逐目录监听。 */\nfunction startWatching(dshHome) {\n  stopWatching();\n  const root = resolveSessionsRoot({ dshHome });\n  if (!root) return;\n\n  const watchDir = (dir) => {\n    let w;\n    try {\n      w = fs.watch(dir, { persistent: false }, markDirty);\n    } catch {\n      return; // 目录不存在或无权限：跳过，不影响其他功能\n    }\n    w.on('error', () => {\n      try {\n        w.close();\n      } catch {\n        /* ignore */\n      }\n    });\n    watchState.watchers.push(w);\n  };\n\n  watchDir(root);\n  // 会话子目录（DSH 按 workspace-slug/<session-id>/ 组织）\n  try {\n    for (const entry of fs.readdirSync(root, { withFileTypes: true })) {\n      if (entry.isDirectory()) {\n        watchDir(joinPath(root, entry.name));\n        // 再下一层才是 session.v4.jsonl.zstd 所在\n        try {\n          for (const sub of fs.readdirSync(joinPath(root, entry.name), { withFileTypes: true })) {\n            if (sub.isDirectory()) watchDir(joinPath(root, entry.name, sub.name));\n          }\n        } catch {\n          /* ignore */\n        }\n      }\n    }\n  } catch {\n    /* ignore */\n  }\n}\n\n/**\n * 跨平台路径拼接。\n *\n * ⚠️ 第三轮修复：这里原来是 `parts.join('\\\\')` —— 在 macOS/Linux 上拼出来的\n * 路径全是错的，导致 fs.watch / readdirSync 全面失败，而失败又被下面的\n * try/catch 静默吞掉（面板退化成\"只有点刷新才有数据\"）。\n * 用 path.join 交给平台自己决定分隔符。\n */\nfunction joinPath(...parts) {\n  return path.join(...parts);\n}\n\n// ---------------------------------------------------------------------------\n// 插件主体\n// ---------------------------------------------------------------------------\n\n/**\n * 挂载 agent-clinic：向 Harness 注册两个模型可见工具。\n * @param {object} ctx    cordis 上下文\n * @param {object} config 由 Config schema 校验后的配置\n */\nexport function apply(ctx, config = {}) {\n  const log = (m) => {\n    try {\n      ctx?.logger?.info?.(`[agent-clinic] ${m}`);\n    } catch {\n      /* 日志失败不影响功能 */\n    }\n  };\n\n  // 应用户要求补上「准实时」：监听会话文件变化，面板轮询 /watch 即可发现新问题\n  watchState.dshHome = config.dshHome ?? null;\n  watchState.dirty = true;\n  try {\n    startWatching(config.dshHome);\n    log(`已开始监听会话目录：${resolveSessionsRoot({ dshHome: config.dshHome }) ?? '(未找到)'}`);\n  } catch (e) {\n    log(`监听启动失败（不影响其他功能）：${e?.message ?? e}`);\n  }\n\n  log('已加载');\n\n  ctx.inject(['tools'], (toolCtx) => {\n    let defineTool;\n    try {\n      // 动态取，避免本地无 peer 时模块导入失败\n      ({ defineTool } = toolCtx.tools?.defineTool ? toolCtx.tools : {});\n    } catch {\n      defineTool = undefined;\n    }\n\n    // 若 Harness 未在 ctx.tools 上暴露 defineTool，则退回静态导入路径\n    if (typeof defineTool !== 'function') {\n      log('ctx.tools.defineTool 不可用，跳过工具注册（请在 DSH 内核对 API）');\n      return;\n    }\n\n    const TEXT_OUTPUT = {\n      schema: { type: 'text' },\n      render: (_args, value) => [{ type: 'text', text: String(value) }],\n    };\n\n    toolCtx.tools.register(\n      defineTool({\n        name: 'agent_clinic_scan',\n        description:\n          '扫描本地 DSH 会话并输出使用概览（会话数、帧、行、工具调用、错误率、token）。只读，零外发。',\n        parameters: {\n          dsh_home: { type: 'string' },\n        },\n        output: TEXT_OUTPUT,\n        execute(args) {\n          return Promise.resolve(runScan({ dshHome: args?.dsh_home ?? config.dshHome }));\n        },\n      }),\n    );\n\n    toolCtx.tools.register(\n      defineTool({\n        name: 'agent_clinic_show',\n        description:\n          '展开一条证据定位（形如 <file>#L<n>），用于复核诊断结论。只读。',\n        parameters: {\n          locator: { type: 'string', required: true },\n        },\n        output: TEXT_OUTPUT,\n        execute(args) {\n          return Promise.resolve(\n            runShow(args?.locator, config.contextLines ?? 2),\n          );\n        },\n      }),\n    );\n\n    toolCtx.tools.register(\n      defineTool({\n        name: 'agent_clinic_report',\n        description:\n          '生成 Agent 使用体检报告：诊断体验问题（死循环、反复失败、冗余重复调用等），每个结论附可复核的证据定位。只读，零外发。',\n        parameters: {\n          dsh_home: { type: 'string' },\n        },\n        output: TEXT_OUTPUT,\n        execute(args) {\n          return Promise.resolve(runReport({ dshHome: args?.dsh_home ?? config.dshHome }, config));\n        },\n      }),\n    );\n\n    log('已注册工具：agent_clinic_scan、agent_clinic_show、agent_clinic_report');\n  });\n\n  // -------------------------------------------------------------------------\n  // 宿主 HTTP 路由 —— 供客户端面板取数\n  //\n  // 客户端「浏览器半」没有 fetch/setTimeout 等浏览器全局；但静态客户端模块\n  // （/plugins/<包名>/client.js）是普通浏览器模块，可用 fetch。因此这里注册\n  // 一个只读路由，面板通过它拿到报告文本。\n  //\n  // 路由 API 实测确认（@deepseek-ai/dsh-host-webserver）：\n  //   ctx.webServer.register({ kind: 'exact'|'prefix', path, handler }) → disposer\n  //   handler 拥有完整响应生命周期；重复 (kind,path) 会抛错。\n  // -------------------------------------------------------------------------\n  try {\n    ctx.inject(['webServer'], (wsCtx) => {\n      const ws = typeof wsCtx.get === 'function' ? wsCtx.get('webServer') : wsCtx.webServer;\n      if (!ws || typeof ws.register !== 'function') {\n        log('webServer 服务不可用，跳过面板路由注册（面板将显示提示）');\n        return;\n      }\n      ws.register({\n        kind: 'exact',\n        path: '/api/agent-clinic/report',\n        handler: async (_req, res) => {\n          const send = (code, payload) => {\n            const body = JSON.stringify(payload);\n            res.writeHead(code, {\n              'content-type': 'application/json; charset=utf-8',\n              'cache-control': 'no-store',\n            });\n            res.end(body);\n          };\n          try {\n            // 旋钮同样要生效：面板路由与模型工具必须同一口径\n            // （待优化报告 §3：这里是最后一处漏传 opts 的地方）\n            // 决策 D4：指纹也要在同一处开（扫描前），否则面板里的 K1/K2 永远不判定\n            const fp = beginFingerprintRun();\n            const scan = limitSessions(scanSessions({ dshHome: config.dshHome }), config.maxSessions);\n            const summary = summarize(scan);\n            const ctxReport = { scan, summary };\n            const fpOpts = fp.diagnosticOpts(scan);\n            const fpData = analyze(ctxReport, { ...analyzeOptsFromConfig(config), ...fpOpts, ...feedbackOpts() });\n            const fpNotice = fingerprintNotice(fp.finish(scan));\n            send(200, {\n              ok: true,\n              version: API_VERSION,\n              generatedAt: new Date().toISOString(),\n              report: buildReport(ctxReport, { ...analyzeOptsFromConfig(config), ...fpOpts, ...feedbackOpts() }),\n              data: fpNotice ? { ...fpData, fingerprintNotice: fpNotice } : fpData,\n            });\n          } catch (e) {\n            send(500, { ok: false, error: String(e?.message ?? e) });\n          }\n        },\n      });\n      log('已注册只读路由 /api/agent-clinic/report');\n      // 「发现问题就联网找方案」的面板入口。\n      // 刻意做成**独立路由**而不是 /report 的一个参数：\n      //   - 面板默认仍然零外发（用户直接看报告不会偷偷联网）\n      //   - 只有点「联网现搜」按钮才会走这里\n      // 只发送问题类型关键词，不发送任何会话内容（响应里的 sent 列出实际检索词）。\n      ws.register({\n        kind: 'exact',\n        path: '/api/agent-clinic/live',\n        handler: async (_req, res) => {\n          const send = (code, payload) => {\n            const body = JSON.stringify(payload);\n            res.writeHead(code, {\n              'content-type': 'application/json; charset=utf-8',\n              'cache-control': 'no-store',\n            });\n            res.end(body);\n          };\n          try {\n            // 决策 D4：现搜路径同样要开指纹，否则\"点联网现搜后 K1/K2 又不判定\"——\n            // 同一面板两种口径（与旋钮那处是同一类问题）\n            const fp = beginFingerprintRun();\n            const scan = limitSessions(scanSessions({ dshHome: config.dshHome }), config.maxSessions);\n            const summary = summarize(scan);\n            const fpOpts = fp.diagnosticOpts(scan);\n            // 现搜也要带上旋钮：否则\"点联网后阈值又变回默认\"——同一面板两种口径\n            const { data, live } = await analyzeLive({ scan, summary }, {\n              ...analyzeOptsFromConfig(config),\n              ...fpOpts,\n              liveOptions: { budgetMs: LIVE_BUDGET_MS },\n            });\n            const fpNotice = fingerprintNotice(fp.finish(scan));\n            send(200, {\n              ok: true,\n              version: API_VERSION,\n              generatedAt: new Date().toISOString(),\n              live,\n              data: fpNotice ? { ...data, fingerprintNotice: fpNotice } : data,\n            });\n          } catch (e) {\n            send(500, { ok: false, error: String(e?.message ?? e) });\n          }\n        },\n      });\n      log('已注册联网现搜路由 /api/agent-clinic/live（仅按钮触发）');\n      ws.register({\n        kind: 'exact',\n        path: '/api/agent-clinic/watch',\n        handler: async (_req, res) => {\n          const send = (code, payload) => {\n            const body = JSON.stringify(payload);\n            res.writeHead(code, {\n              'content-type': 'application/json; charset=utf-8',\n              'cache-control': 'no-store',\n            });\n            res.end(body);\n          };\n          try {\n            send(200, currentState(config.dshHome, config));\n          } catch (e) {\n            send(500, { ok: false, error: String(e?.message ?? e) });\n          }\n        },\n      });\n      log('已注册只读路由 /api/agent-clinic/watch（轻量状态，供客户端轮询）');\n    });\n  } catch (e) {\n    log(`路由注册失败（不影响其他功能）：${e?.message ?? e}`);\n  }\n}\n"
    },
    {
      "path": "src/adapters/dsh.mjs",
      "content": "/**\n * DeepSeek Harness (DSH) 适配器\n *\n * 已在本机 4 个真实会话（463 帧 / 994 行）上验证。\n *\n * 数据格式要点（详见 docs/data-formats.md）：\n *   - 文件：<DSH_HOME>/sessions/<workspace-slug>/<session-id>/session.vN.jsonl.zstd\n *   - 磁盘上是多帧 zstd 拼接 → 必须走 zstd-frames.mjs\n *   - 第 1 行是 header，字段在**顶层**（不是 .data）\n *   - 之后每行是事件 {type, seq, time, data}，字段在 .data\n *   - usage 是 camelCase：inputTokens / outputTokens / cacheReadTokens ...\n *   - tool/call 的 arguments 是 **JSON 字符串**，需先 parse 再哈希\n *   - tool/result 失败有双信号：data.error 或 data.message.isError\n */\n\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\nimport crypto from 'node:crypto';\n\nimport { decodeFrames } from './zstd-frames.mjs';\nimport { resolveDshHome as resolveEnvDshHome } from '../config/index.mjs';\nimport { KIND, PLATFORM, makeLocator, makeEvent, stableStringify } from './base.mjs';\n// 决策 D4：用户文本指纹（K1/K2 的数据基础）。此处只在解析时**当场**算哈希，\n// 正文不落到事件里；详见 src/privacy/fingerprints.mjs 的隐私边界说明。\nimport { fingerprintOf, getActiveSalt, textOfContent } from '../privacy/fingerprints.mjs';\n\n/** 会话文件名匹配：session.v4.jsonl.zstd / session.v1.jsonl */\nconst SESSION_FILE_RE = /^session\\.v(\\d+)\\.jsonl(\\.zstd)?$/;\n\n/** 解析 DSH_HOME：显式参数 > 环境变量 > ~/.dsh */\n/**\n * 会话根目录所在（DSH_HOME）。\n *\n * ⚠️ 第三轮：这里原本自带一份回退逻辑，与 src/config/index.mjs 的\n * resolveDshHome 已经分叉（那份会 trim 并回退 HOME/USERPROFILE）。\n * 现在统一委托给 config 的那一份，只保留\"显式路径优先\"的包装。\n */\nexport function resolveDshHome(explicit) {\n  if (explicit) return explicit;\n  return resolveEnvDshHome(process.env) || path.join(os.homedir(), '.dsh');\n}\n\n/** 会话根目录 */\nexport function resolveSessionsRoot(opts = {}) {\n  return path.join(resolveDshHome(opts.dshHome), 'sessions');\n}\n\n/**\n * 递归找出所有会话文件，按路径排序（保证输出稳定可复现）。\n *\n * 第二轮评估 F4：旧实现是 `catch { return; }` 静默跳过 —— 目录**不可读**与\n * **本来就没有会话**在下游看起来一模一样，于是 CLI 会打印\"未找到会话文件\"，\n * 把权限/路径问题伪装成\"你机器上没有数据\"。现在把读取失败如实带出去。\n *\n * @returns {{files:string[], errors:Array<{dir:string, code:string|null, message:string}>}}\n */\nexport function findSessionFilesDetailed(root) {\n  const files = [];\n  const errors = [];\n  const walk = (dir) => {\n    let entries;\n    try {\n      entries = fs.readdirSync(dir, { withFileTypes: true });\n    } catch (e) {\n      // ENOENT = 这个目录确实不存在（正常：没装过/没用过）；其余要报出来\n      if (e?.code !== 'ENOENT') {\n        errors.push({ dir, code: e?.code ?? null, message: e?.message ?? String(e) });\n      }\n      return;\n    }\n    for (const e of entries) {\n      const p = path.join(dir, e.name);\n      if (e.isDirectory()) walk(p);\n      else if (SESSION_FILE_RE.test(e.name)) files.push(p);\n    }\n  };\n  walk(root);\n  return { files: files.sort(), errors };\n}\n\n/** 兼容入口：只要文件列表（不关心读取失败） */\nexport function findSessionFiles(root) {\n  return findSessionFilesDetailed(root).files;\n}\n\n/** 会话文件版本（v4 / v3 …），未知返回 null */\nexport function sessionVersion(file) {\n  const m = SESSION_FILE_RE.exec(path.basename(file));\n  return m ? Number(m[1]) : null;\n}\n\n// ---------------------------------------------------------------------------\n// 内部工具\n// ---------------------------------------------------------------------------\n\nfunction hashArgs(args) {\n  let normalized;\n  if (typeof args === 'string') {\n    try {\n      normalized = stableStringify(JSON.parse(args)); // arguments 是 JSON 字符串\n    } catch {\n      normalized = args; // 不是 JSON 就按原串处理\n    }\n  } else {\n    normalized = stableStringify(args ?? null);\n  }\n  return crypto.createHash('sha1').update(normalized).digest('hex').slice(0, 16);\n}\n\nfunction isErrorResult(data) {\n  if (data?.error) return true; // { name:\"AbortError\", code:\"ABORTED\" }\n  if (data?.message?.isError === true) return true; // 第二重信号\n  return false;\n}\n\n/**\n * N2 高风险操作的模式表。\n *\n * 隐私约束（本项目硬性原则）：只返回**命中的模式标签**，\n * 绝不返回原始参数、路径或命令正文。报告与面板里也只出现标签。\n *\n * ⚠️ 只匹配命令执行类工具的 command 字段。\n * 实测踩过的坑：早期版本对整个 arguments JSON 做匹配，结果把\n * `write` 工具写入的 Markdown 文档正文里的 \"--force\" 当成高危命令，\n * 报了 2 条假警报。write/edit/read 的参数是**用户内容**，不是命令。\n */\nconst DANGER_PATTERNS = [\n  { label: 'rm -r/-f', re: /\\brm\\s+-[a-z]*(?:r|f)[a-z]*\\b/i },\n  { label: '--force', re: /--force\\b/i },\n  { label: 'git reset --hard', re: /\\breset\\s+--hard\\b/i },\n  { label: 'git clean -fd', re: /\\bgit\\s+clean\\s+-[a-z]*f/i },\n  { label: 'DROP/TRUNCATE', re: /\\b(?:drop|truncate)\\s+(?:table|database|schema)\\b/i },\n  { label: 'curl | sh', re: /\\bcurl\\b[^|]{0,200}\\|\\s*(?:ba|z|a)?sh\\b/i },\n  { label: 'kill -9', re: /\\bkill\\s+-9\\b/i },\n  { label: 'chmod 777', re: /\\bchmod\\s+777\\b/i },\n  { label: 'mkfs', re: /\\bmkfs\\b/i },\n  { label: 'fork bomb', re: /:\\(\\)\\s*\\{/ },\n];\n\n/** 命令执行类工具：只有它们的参数才是\"命令\"而非\"内容\" */\nconst COMMAND_TOOLS =\n  /^(?:pwsh|powershell|powershell\\.exe|pwsh\\.exe|bash|sh|zsh|dash|shell|exec|execute|run_command|cmd|cmd\\.exe|terminal|node|python|python3|ruby)$/i;\n\n/** 从参数里取出命令文本；取不到返回 null */\nfunction commandTextOf(args) {\n  let obj;\n  if (typeof args === 'string') {\n    try {\n      obj = JSON.parse(args);\n    } catch {\n      return args; // 纯字符串当作命令\n    }\n  } else {\n    obj = args;\n  }\n  if (!obj || typeof obj !== 'object') return null;\n  for (const k of ['command', 'cmd', 'script', 'code', 'shellCommand']) {\n    if (typeof obj[k] === 'string' && obj[k].trim()) return obj[k];\n  }\n  return null;\n}\n\n/** 返回命中的高危模式标签数组（空数组 = 未命中）。不携带任何原始内容。 */\nfunction dangerOf(name, args) {\n  if (!name || !COMMAND_TOOLS.test(String(name))) return [];\n  const cmd = commandTextOf(args);\n  if (!cmd) return [];\n  const hits = [];\n  for (const p of DANGER_PATTERNS) {\n    try {\n      if (p.re.test(cmd)) hits.push(p.label);\n    } catch {\n      /* 单个正则异常不影响其他模式 */\n    }\n  }\n  return hits;\n}\n\n/** todo 条目数。结构未知时保守返回 null，不下结论。 */\nfunction todoCountOf(data) {\n  const t = data?.todos ?? data?.todoList ?? data?.items;\n  if (Array.isArray(t)) return t.length;\n  if (typeof t === 'number') return t;\n  return null;\n}\n\n/** 已完成的 todo 条目数 */\nfunction todoDoneOf(data) {\n  const t = data?.todos ?? data?.todoList ?? data?.items;\n  if (!Array.isArray(t)) return null;\n  let n = 0;\n  for (const item of t) {\n    const st = item?.status ?? item?.state;\n    if (st === 'done' || st === 'completed' || item?.done === true) n += 1;\n  }\n  return n;\n}\n\nfunction usageOf(data) {\n  const u = data?.usage;\n  if (!u) return {};\n  return {\n    input_tokens: u.inputTokens ?? 0,\n    output_tokens: u.outputTokens ?? 0,\n    cache_read_tokens: u.cacheReadTokens ?? 0,\n    cache_write_tokens: u.cacheWriteTokens ?? 0,\n    total_tokens: u.totalTokens ?? 0,\n  };\n}\n\n/** 累加 content 块中指定类型的文本长度 */\nfunction sumTextLen(blocks, type) {\n  if (!Array.isArray(blocks)) return 0;\n  let n = 0;\n  for (const b of blocks) {\n    if (b && b.type === type && typeof b.text === 'string') n += b.text.length;\n  }\n  return n;\n}\n\n/**\n * 结构化数据的**字节/字符体量** —— 只取长度，绝不保留内容。\n *\n * 用于 C6（工具 schema 体量）与 C7（上下文注入量）：这两个指标要的是\"多大\"，\n * 不是\"是什么\"。用 JSON 序列化长度而不是递归数叶子，是为了让口径可复核\n * （同一份数据任何时候算出同一个数）。\n */\nfunction jsonLen(value) {\n  if (value === undefined || value === null) return 0;\n  try {\n    return JSON.stringify(value)?.length ?? 0;\n  } catch {\n    return 0; // 循环引用等异常输入：按 0 处理，不让单条脏数据毁掉整个会话解析\n  }\n}\n\n/**\n * 从工具参数里只取出**技能名**（A2 需要）。\n *\n * ⚠️ 第二轮评估 F13 的根因：DSH 的 skill 触发**不是**同名工具调用，\n * 而是唯一的 `skill` 工具 + 参数 `{\"name\":\"<技能名>\"}`。\n * 旧代码拿 tool_name 去比技能目录名，于是永远匹配不上 → 窗口一到\n * 所有已装 skill 都被误报为\"闲置\"。\n *\n * 只提炼 `name` 一个字段，不保留其它参数（隐私硬约束与 A2 的判据一致）。\n */\nfunction skillNameOf(name, args) {\n  if (String(name ?? '') !== 'skill') return null;\n  let obj = args;\n  if (typeof args === 'string') {\n    try {\n      obj = JSON.parse(args);\n    } catch {\n      return null;\n    }\n  }\n  const v = obj?.name;\n  return typeof v === 'string' && v.trim() ? v.trim() : null;\n}\n\n/** 供冒烟测试直接验证技能名提取（不在生产路径上调用） */\nexport const skillNameOfForTest = skillNameOf;\n\nfunction projectOf(meta) {\n  const cwd = meta?.cwd;\n  if (typeof cwd === 'string' && cwd.trim()) {\n    return path.basename(cwd.replace(/[\\\\/]+$/, '')) || cwd;\n  }\n  return '(unknown)';\n}\n\n// ---------------------------------------------------------------------------\n// 主入口\n// ---------------------------------------------------------------------------\n\n/**\n * 解析单个会话文件 → 统一事件模型\n *\n * 只读、容错：坏帧 / 坏行跳过并计数，绝不中断。\n *\n * @param {string} file 会话文件绝对路径\n */\nexport function parseSession(file) {\n  const buf = fs.readFileSync(file); // 只读，绝不写回\n  const { frames, badFrames, text, plain } = decodeFrames(buf);\n\n  const rawLines = text.split('\\n');\n  // 文本以 \\n 结尾时 split 会产生一个尾部空串，它不是真实行 —— 去掉，\n  // 保证 totalLines 准确，且与 evidence.readRange 的行号完全一致。\n  if (rawLines.length && rawLines[rawLines.length - 1] === '') rawLines.pop();\n\n  const events = [];\n  let meta = null;\n  let sessionId = null;\n  let title = null;\n  let badLines = 0;\n  let unmapped = 0;\n\n  for (let i = 0; i < rawLines.length; i++) {\n    const raw = rawLines[i];\n    if (!raw.trim()) continue;\n\n    let rec;\n    try {\n      rec = JSON.parse(raw);\n    } catch {\n      badLines += 1;\n      continue;\n    }\n\n    const lineNo = i + 1; // 解码后的全局行号（1-based）\n\n    // header：字段在顶层\n    if (rec.type === 'session') {\n      meta = { ...rec };\n      sessionId = rec.id ?? path.basename(path.dirname(file));\n      continue;\n    }\n\n    const data = rec.data ?? {};\n    const base = {\n      platform: PLATFORM.DSH,\n      session_id: sessionId ?? path.basename(path.dirname(file)),\n      project: projectOf(meta),\n      ts: typeof rec.time === 'number' ? new Date(rec.time).toISOString() : null,\n      seq: rec.seq ?? null,\n      locator: makeLocator(file, lineNo),\n    };\n\n    let ev = null;\n    switch (rec.type) {\n      case 'user/message':\n        // content 在 data.content\n        ev = makeEvent({ ...base, kind: KIND.USER_MSG }, {\n          text_len: sumTextLen(data.content, 'text'),\n          // 决策 D4（K1/K2 的数据基础）：用户文本在**解析时**当场规范化 + 加盐哈希，\n          // 只把 32 位十六进制指纹放进事件 —— 正文既不进事件、也不进报告，更不落盘。\n          // 没有盐（未走 report/scan 的指纹路径）或文本过短（<12 字符）时为 null，\n          // 上层会如实说明\"本次未采集指纹\"，而不是假装没问题。\n          text_hash: fingerprintOf(getActiveSalt(), textOfContent(data.content, 'text'))?.hash ?? null,\n        });\n        break;\n\n      case 'assistant/message':\n        // content 在 data.message.content\n        ev = makeEvent({ ...base, kind: KIND.ASSISTANT_MSG }, {\n          text_len: sumTextLen(data.message?.content, 'text'),\n          reasoning_len: sumTextLen(data.message?.content, 'reasoning'),\n          ...usageOf(data),\n        });\n        break;\n\n      case 'tool/call':\n        ev = makeEvent({ ...base, kind: KIND.TOOL_CALL }, {\n          tool_name: data.name ?? '(unknown)',\n          tool_call_id: data.callId ?? null,\n          tool_args_hash: hashArgs(data.arguments),\n          // A2：skill 触发是 `skill` 工具 + 参数 name（不是同名工具调用）\n          skill_name: skillNameOf(data.name, data.arguments),\n          // N2：只对命令执行类工具检测，且只记命中的模式标签，\n          // 不记原始参数（隐私硬约束 + 防 write/edit 内容误报）\n          danger: dangerOf(data.name, data.arguments),\n        });\n        break;\n\n      case 'tool/result':\n        ev = makeEvent({ ...base, kind: KIND.TOOL_RESULT }, {\n          tool_call_id: data.toolCallId ?? data.message?.source?.callId ?? null,\n          is_error: isErrorResult(data),\n          // E3：工具结果过大。只记**长度**，不保留正文 ——\n          // 旧版本连长度都没记，于是 E3 被误判成\"数据源缺失\"。\n          text_len: sumTextLen(data.message?.content ?? data.content, 'text'),\n        });\n        break;\n\n      case 'todo/write':\n        // E4 计划执行脱节：把「写了计划」这个事实记下来。\n        // 只记条目数与是否全部完成，不记计划正文。\n        ev = makeEvent({ ...base, kind: KIND.TODO_WRITE }, {\n          todo_count: todoCountOf(data),\n          done_count: todoDoneOf(data),\n        });\n        break;\n\n      case 'approval/policy':\n        ev = makeEvent({ ...base, kind: KIND.APPROVAL }, {\n          approval_phase: 'policy',\n          policy: data.policy ?? null,\n        });\n        break;\n\n      // N3 权限审批摩擦：asked 与 decided 用 id 关联 ——\n      // 旧版本只认 approval/policy，于是把 N3 判成\"DSH 没有这些事件\"。\n      // 这里记 id / 工具名 / 决定结果，**不记 reason 正文**（可能含用户上下文）。\n      case 'approval/asked':\n        ev = makeEvent({ ...base, kind: KIND.APPROVAL }, {\n          approval_phase: 'asked',\n          approval_id: data.id ?? null,\n          tool_name: data.toolName ?? null,\n          reason_len: typeof data.reason === 'string' ? data.reason.length : 0,\n        });\n        break;\n      case 'approval/decided':\n        ev = makeEvent({ ...base, kind: KIND.APPROVAL }, {\n          approval_phase: 'decided',\n          approval_id: data.id ?? null,\n          outcome: data.outcome ?? null,\n        });\n        break;\n\n      // N4 API 重试频繁：llm/retry 携带失败码、重试序号与退避时长\n      case 'llm/retry':\n        ev = makeEvent({ ...base, kind: KIND.RETRY }, {\n          retry_id: data.retryId ?? null,\n          provider: data.provider ?? null,\n          retry_mode: data.mode ?? null,\n          retry_index: Number.isFinite(data.retry) ? data.retry : null,\n          max_retries: Number.isFinite(data.maxRetries) ? data.maxRetries : null,\n          delay_ms: Number.isFinite(data.delayMs) ? data.delayMs : null,\n          failure_code: data.failure?.code ?? null,\n        });\n        break;\n\n      // ---------------------------------------------------------------------\n      // C5 压缩可观测性 —— DSH 自己记着\"这次压缩实际释放了多少 token\"：\n      //   compaction/summary 带 shadowedTokenCount + shadowedSeqs + provider/model\n      //   compaction/prune   带 shadowedTokenCount（只有剪枝，没有摘要）\n      // 旧版本完全不解析这四类事件，于是 C1/C3 只能靠启发式估算绕圈子。\n      // 只记数字与范围，**不记 summary / rawOutput 正文**。\n      // ---------------------------------------------------------------------\n      case 'compaction/start':\n      case 'compaction/end':\n        ev = makeEvent({ ...base, kind: KIND.COMPACTION }, {\n          compaction_phase: rec.type === 'compaction/start' ? 'start' : 'end',\n          compaction_id: data.compactionId ?? null,\n          turn: Number.isFinite(data.turn) ? data.turn : null,\n        });\n        break;\n\n      case 'compaction/summary':\n        ev = makeEvent({ ...base, kind: KIND.COMPACTION }, {\n          compaction_phase: 'summary',\n          compaction_id: data.compactionId ?? null,\n          shadowed_token_count: Number.isFinite(data.shadowedTokenCount) ? data.shadowedTokenCount : null,\n          shadowed_count: Array.isArray(data.shadowedSeqs) ? data.shadowedSeqs.length : null,\n          shadowed_start: Number.isFinite(data.shadowedRange?.start) ? data.shadowedRange.start : null,\n          shadowed_end: Number.isFinite(data.shadowedRange?.end) ? data.shadowedRange.end : null,\n          // 摘要本身的体量（与\"释放了多少\"对比，能看出压缩效率）\n          summary_chars: Array.isArray(data.summary) ? sumTextLen(data.summary, 'text') : null,\n          provider: data.provider ?? null,\n          model: data.model ?? null,\n        });\n        break;\n\n      case 'compaction/prune':\n        ev = makeEvent({ ...base, kind: KIND.COMPACTION }, {\n          compaction_phase: 'prune',\n          compaction_id: data.compactionId ?? null,\n          shadowed_token_count: Number.isFinite(data.shadowedTokenCount) ? data.shadowedTokenCount : null,\n          shadowed_count: Array.isArray(data.shadowedSeqs) ? data.shadowedSeqs.length : null,\n          shadowed_start: Number.isFinite(data.shadowedRange?.start) ? data.shadowedRange.start : null,\n          shadowed_end: Number.isFinite(data.shadowedRange?.end) ? data.shadowedRange.end : null,\n        });\n        break;\n\n      // ---------------------------------------------------------------------\n      // C6 工具面成本 —— request/header 里有**完整的工具 schema**（实测 27 个工具）。\n      // 工具 schema 每个请求都要重发，但此前从未被计量过。\n      // 记工具名（它们是指令标识符，不是用户内容）+ schema 字节数与 maxTokens。\n      // ---------------------------------------------------------------------\n      case 'request/header': {\n        const header = data.header ?? {};\n        const tools = Array.isArray(header.tools) ? header.tools : [];\n        ev = makeEvent({ ...base, kind: KIND.REQUEST_HEADER }, {\n          request_reason: typeof data.reason === 'string' ? data.reason : null,\n          tool_count: tools.length,\n          tool_names: tools.map((t) => (typeof t?.name === 'string' ? t.name : null)).filter(Boolean),\n          tool_schema_bytes: jsonLen(tools),\n          max_tokens: Number.isFinite(header.config?.maxTokens)\n            ? header.config.maxTokens\n            : Number.isFinite(header.adapterDefaults?.maxTokens)\n              ? header.adapterDefaults.maxTokens\n              : null,\n        });\n        break;\n      }\n\n      // C7 上下文注入量 —— inbox 被 splice 的痕迹（塞了什么进去、多大）。\n      // 只记体积与目标，不记插入内容。\n      case 'agent/inbox/spliced':\n        ev = makeEvent({ ...base, kind: KIND.INBOX_SPLICE }, {\n          splice_target: typeof data.target === 'string' ? data.target : null,\n          splice_start: Number.isFinite(data.start) ? data.start : null,\n          inserted_count: Array.isArray(data.inserted) ? data.inserted.length : null,\n          inserted_chars: jsonLen(data.inserted),\n        });\n        break;\n\n      // ---------------------------------------------------------------------\n      // A5 辅助 LLM 开销 —— 这两类请求**没有 usage 记录**，但它们确实在花钱：\n      //   web/deepseek-search-llm-request（联网检索，实测 max_tokens=4096）\n      //   session/title-llm-request（会话标题，maxTokens=64）\n      // 只记次数、模型与 token 上限（据此给上界估算），不记请求体正文。\n      // ---------------------------------------------------------------------\n      case 'web/deepseek-search-llm-request':\n        ev = makeEvent({ ...base, kind: KIND.AUX_REQUEST }, {\n          aux_source: 'web-search',\n          aux_model: data.body?.model ?? null,\n          aux_max_tokens: Number.isFinite(data.body?.max_tokens) ? data.body.max_tokens : null,\n          aux_input_chars: jsonLen(data.body?.messages),\n        });\n        break;\n\n      case 'session/title-llm-request':\n        ev = makeEvent({ ...base, kind: KIND.AUX_REQUEST }, {\n          aux_source: 'session-title',\n          aux_model: data.route?.model ?? null,\n          aux_max_tokens: Number.isFinite(data.maxTokens) ? data.maxTokens : null,\n          aux_input_chars: jsonLen(data.messages),\n        });\n        break;\n\n      case 'session/title':\n        // 标题不是事件，挂在会话上；provider 生成的标题优于 fallback\n        if (typeof data.title === 'string' && data.title.trim()) {\n          if (title === null || data.source?.kind === 'provider') title = data.title.trim();\n        }\n        unmapped += 1;\n        break;\n\n      default:\n        unmapped += 1; // 不关心的事件类型：只计数\n        break;\n    }\n\n    if (ev) events.push(ev);\n  }\n\n  return {\n    file,\n    sessionId: sessionId ?? path.basename(path.dirname(file)),\n    version: sessionVersion(file),\n    meta,\n    title,\n    frames,\n    badFrames,\n    plain,\n    totalLines: rawLines.length,\n    badLines,\n    unmapped,\n    // A4 子代理开销：header 顶层字段（不在 .data 里）\n    delegationDepth: Number.isFinite(meta?.delegationDepth) ? meta.delegationDepth : null,\n    parentSession: typeof meta?.parentSession === 'string' ? meta.parentSession : null,\n    isSubagent: (meta?.origin === 'subagent') || (Number(meta?.delegationDepth) > 0),\n    origin: typeof meta?.origin === 'string' ? meta.origin : null,\n    events,\n  };\n}\n\n/**\n * 按上限裁剪会话集合（`maxSessions` 旋钮的实现）。\n *\n * 第三轮验收（待优化报告 §3）：插件 Config 声明了 `maxSessions`，但从来没有\n * 传到扫描侧 —— 用户改了没效果，也没有提示。这个函数是那个旋钮的唯一实现，\n * 插件侧（report / analyze / live / watch 四条路径）都经过它。\n *\n * 语义：保留**最近修改**的 N 个会话（按 mtime 降序）。\n * 不按路径排序取前 N 个 —— 目录名按项目名排，取前几个会拿到最老的那批，\n * 与\"体检当下状态\"的意图相反。\n *\n * @param {{sessions:Array}} scan\n * @param {number} [maxSessions] 省略/非正数则原样返回\n */\nexport function limitSessions(scan, maxSessions) {\n  if (!Number.isFinite(maxSessions) || maxSessions <= 0) return scan;\n  if (!Array.isArray(scan?.sessions) || scan.sessions.length <= maxSessions) return scan;\n  const withTime = scan.sessions.map((s) => {\n    let mtime = 0;\n    try {\n      mtime = fs.statSync(s.file).mtimeMs;\n    } catch {\n      /* 读不到 mtime 的排到最后，而不是丢弃 */\n    }\n    return { s, mtime };\n  });\n  withTime.sort((a, b) => b.mtime - a.mtime);\n  return {\n    ...scan,\n    sessions: withTime.slice(0, maxSessions).map((x) => x.s),\n    // 让\"报告分母被裁过\"这件事可复核（只报 N 个会话时读者要知道为什么）\n    limitedFrom: scan.sessions.length,\n  };\n}\n\n/** 扫描根目录下全部会话 */\nexport function scanSessions(opts = {}) {\n  const root = resolveSessionsRoot(opts);\n  const { files, errors: scanErrors } = findSessionFilesDetailed(root);\n  const sessions = [];\n  // 目录读取失败与文件解析失败**分开记**：前者让人以为\"没数据\"，后者让人以为\"没问题\"\n  const errors = scanErrors.map((e) => ({\n    kind: 'read',\n    file: e.dir,\n    code: e.code,\n    message:\n      e.code === 'EACCES' || e.code === 'EPERM'\n        ? `无权限读取目录（${e.code}）`\n        : `读取目录失败：${e.message}`,\n  }));\n\n  for (const f of files) {\n    try {\n      sessions.push(parseSession(f));\n    } catch (e) {\n      errors.push({ kind: 'parse', file: f, code: e?.code ?? null, message: e?.message ?? String(e) });\n    }\n  }\n\n  return { root, sessions, errors, fileCount: files.length };\n}\n"
    },
    {
      "path": "src/adapters/zstd-frames.mjs",
      "content": "/**\n * 多帧 zstd 解码器 —— agent-clinic 的核心基础能力\n *\n * ⚠️ 为什么需要这个文件：\n * DSH 的会话文件是「追加式事件流」，磁盘上表现为 **N 个独立 zstd 帧首尾拼接**。\n * 实测单个会话文件含 60 ~ 233 个帧。而：\n *   - zlib.zstdDecompressSync(整文件)  → 只返回第 1 帧（静默丢数据）\n *   - zlib.createZstdDecompress() 流式 → 同样只返回第 1 帧\n * 因此必须按 magic number 手工切帧，逐帧解码后拼接。\n *\n * 本实现已在真实数据上验证：463/463 帧解码成功。\n */\n\nimport fs from 'node:fs';\nimport zlib from 'node:zlib';\n\n/** zstd 帧的 magic number：0x28 0xB5 0x2F 0xFD（小端 0xFD2FB528） */\nexport const ZSTD_MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);\n\n/** 运行环境是否支持原生 zstd 解码（Node >= 22.15） */\nexport function hasZstdSupport() {\n  return typeof zlib.zstdDecompressSync === 'function';\n}\n\n/**\n * 断言运行环境支持 zstd，否则抛出可操作的错误。\n * 绝不静默降级 —— 缺依赖时必须让用户看见。\n */\nexport function assertZstdSupport() {\n  if (hasZstdSupport()) return;\n  throw new Error(\n    [\n      '运行环境不支持原生 zstd 解码，无法读取 DSH 会话文件。',\n      `当前 Node 版本：${process.version}（需要 >= 22.15.0）`,\n      '',\n      '解决办法（任选其一）：',\n      '  1) 升级 Node：nvm install 22 && nvm use 22',\n      '  2) 从 https://nodejs.org 安装 22.x LTS 或更高版本',\n      '',\n      '本工具不会静默跳过无法解码的数据。',\n    ].join('\\n'),\n  );\n}\n\n/** 扫描 buffer 中所有 zstd 帧的起始偏移 */\nexport function findFrameOffsets(buf) {\n  const offsets = [];\n  let p = 0;\n  while (true) {\n    const i = buf.indexOf(ZSTD_MAGIC, p);\n    if (i < 0) break;\n    offsets.push(i);\n    p = i + ZSTD_MAGIC.length;\n  }\n  return offsets;\n}\n\n/**\n * 解码一个可能是多帧 zstd 的 buffer，返回解码后的文本。\n *\n * @param {Buffer} buf 原始文件内容\n * @returns {{frames:number, badFrames:number, text:string, plain:boolean}}\n *   frames    识别到的 zstd 帧数（0 表示不是 zstd）\n *   badFrames 解码失败的帧数（坏帧不中断，计入统计）\n *   text      拼接后的文本\n *   plain     true 表示输入本身是明文（无 zstd magic），已原样返回\n */\nexport function decodeFrames(buf) {\n  assertZstdSupport();\n\n  const offsets = findFrameOffsets(buf);\n\n  // 非 zstd：可能是无压缩的明文 .jsonl，原样返回\n  if (offsets.length === 0) {\n    return { frames: 0, badFrames: 0, text: buf.toString('utf8'), plain: true };\n  }\n\n  const parts = [];\n  let badFrames = 0;\n\n  for (let i = 0; i < offsets.length; i++) {\n    const start = offsets[i];\n    const end = i + 1 < offsets.length ? offsets[i + 1] : buf.length;\n    try {\n      let part = zlib.zstdDecompressSync(buf.subarray(start, end)).toString('utf8');\n      // 防御：若帧未以换行结尾，补一个，避免与下一帧首行粘连成坏行\n      if (part.length > 0 && !part.endsWith('\\n')) part += '\\n';\n      parts.push(part);\n    } catch {\n      badFrames += 1; // 坏帧跳过并计数，绝不中断整体扫描\n    }\n  }\n\n  return { frames: offsets.length, badFrames, text: parts.join(''), plain: false };\n}\n\n"
    },
    {
      "path": "src/evidence/index.mjs",
      "content": "/**\n * L3 证据层 —— agent-clinic 的护城河\n *\n * 所有竞品都只给统计数字；本层给的是**可复核**的证据：\n *   - 精确定位：<file>#L<start>-L<end>\n *   - 可展开：readRange() 重新解码并打印该区间\n *   - 可复现：与 scan 共用同一套切帧逻辑，行号严格一致\n *\n * 【当前状态：骨架】readRange 已实现并可用；buildEvidencePackage 待 M1 Step 4。\n */\n\nimport fs from 'node:fs';\n\nimport { decodeFrames } from '../adapters/zstd-frames.mjs';\nimport { parseLocator, makeLocator } from '../adapters/base.mjs';\n\n/**\n * 读取某个会话文件的指定行**区间**（重新解码，与 scan 逻辑完全一致）。\n *\n * 第三轮（待优化报告 Phase 2 第 5 项）：以前只接受单个行号，`#L1733-L2688`\n * 这种带区间的定位符会被**静默忽略终点** —— 报告里 955 行跨度的结论\n * （例如\"同一个 read 调了 3 次\"的第 1 与第 3 次）根本打不开。\n *\n * 2026-10-15 决策 D8：区间过长时不再只是\"截断 + 让你自己猜怎么继续\"，\n * 而是支持**显式分页**（`opts.offset` / `opts.limit`），并由 renderEvidence\n * 在截断提示里直接给出下一条可执行的复核命令。\n *\n * @param {string} file         会话文件绝对路径\n * @param {number} line         起始行号（1-based，解码后全局行号）\n * @param {number} [context=2]  区间两端各多取几行\n * @param {number} [endLine]    结束行号；省略或等于 line 时退化为单行 ± context\n * @param {{offset?:number, limit?:number}} [opts]\n *        offset：从本次请求窗口起点（`line - context`）再向后跳过的行数，用于翻页\n *        limit ：本次最多展开多少行（默认 200，上限仍然是\"不刷屏\"的默认值，仅当显式传入时生效）\n */\nexport function readRange(file, line, context = 2, endLine = undefined, opts = {}) {\n  const buf = fs.readFileSync(file);\n  const { text, frames, badFrames, plain } = decodeFrames(buf);\n  const all = text.split('\\n');\n  // 与 adapters/dsh.mjs 保持一致：去掉尾部空串，保证行号严格对齐\n  if (all.length && all[all.length - 1] === '') all.pop();\n\n  const end = Number.isInteger(endLine) && endLine > line ? endLine : line;\n  for (const n of [line, end]) {\n    if (n < 1 || n > all.length) {\n      const err = new Error(`行号 ${n} 超出范围（该文件共 ${all.length} 行）`);\n      err.code = 'LINE_OUT_OF_RANGE';\n      throw err;\n    }\n  }\n\n  const winStart = Math.max(1, line - context); // 本次请求窗口起点（未翻页时）\n  const offset = Math.max(0, Math.trunc(Number(opts.offset) || 0));\n  const pageFrom = Math.min(all.length, winStart + offset);\n  // 区间跨度大时行数会爆掉：默认上限 200 行（可用 limit 显式调整）\n  const MAX_LINES = Math.max(1, Math.trunc(Number(opts.limit) || 0) || 200);\n  const wanted = end + context - pageFrom + 1;\n  const truncated = wanted > MAX_LINES;\n  const to = truncated ? Math.min(all.length, pageFrom + MAX_LINES - 1) : Math.min(all.length, end + context);\n  const from = pageFrom;\n\n  const lines = [];\n  for (let n = from; n <= to; n++) {\n    lines.push({ no: n, text: all[n - 1] ?? '', isTarget: n >= line && n <= end });\n  }\n\n  return {\n    file,\n    from,\n    to,\n    totalLines: all.length,\n    frames,\n    badFrames,\n    plain,\n    lines,\n    rangeStart: line,\n    rangeEnd: end,\n    truncated,\n    offset,\n    limit: MAX_LINES,\n    // 还有多少行没展开（截断后用来说明\"下一页从哪开始\"）\n    remaining: truncated ? Math.max(0, end + context - to) : 0,\n  };\n}\n\n/**\n * 解析 \"<file>#L<line>\" 或 \"<file>#L<start>-L<end>\" 形式的定位符。\n *\n * 2026-10-15 决策 D7：这里**不再有第二份解析实现** —— 统一转发给\n * `src/adapters/base.mjs` 的 `parseLocator`（唯一实现，支持区间）。\n * 保留本导出是为了不改动既有调用方（CLI / 插件 / 自检）。\n */\nexport function parseRange(locator) {\n  return parseLocator(locator);\n}\n\n/** 把一段定位符渲染成可读的证据块（默认脱敏：超长行截断） */\nexport function renderEvidence(locator, { context = 2, maxLen = 400, offset = 0, limit = undefined } = {}) {\n  const range = parseRange(locator);\n  if (!range) throw new Error(`无法解析定位符：${locator}`);\n\n  // 带上区间终点：旧版本只读 range.start，955 行跨度的证据只能看到开头 5 行\n  const r = readRange(range.file, range.start, context, range.end, { offset, limit });\n  const out = [];\n  out.push(`证据位置：${locator}`);\n  out.push(\n    `文件共 ${r.totalLines} 行 · zstd 帧 ${r.frames}（坏帧 ${r.badFrames}）` +\n      (range.end > range.start\n        ? ` · 目标区间 #L${range.start}-L${range.end}（${range.end - range.start + 1} 行）`\n        : ''),\n  );\n  // 翻页时先说清\"本页是从哪里开始的\"：这条以前挂在 truncation 的 else 分支里，\n  // 于是\"区间很长 + 正在翻页\"（恰好是最常见的组合）时反而看不到 —— 现在独立输出。\n  if (r.offset > 0) {\n    out.push(`（已跳过前 ${r.offset} 行，本页 #L${r.from}-L${r.to}）`);\n  }\n  if (r.truncated) {\n    // 决策 D8：截断不只是\"告知\"，而是给出**可直接复制的下一条命令** ——\n    // 旧提示写的是\"请用 offset/limit 分段复核\"，但从没告诉用户具体该填什么。\n    const nextOffset = r.to - Math.max(1, range.start - context) + 1;\n    out.push(\n      `⚠ 本次只展开 #L${r.from}-L${r.to}（共 ${r.totalLines} 行中的一段，每页 ${r.limit} 行），` +\n        `还剩 ${r.remaining} 行未展开。继续看下一页：`,\n    );\n    out.push(`    agent-clinic show \"${locator}\" --offset ${nextOffset} --limit ${r.limit}`);\n    out.push(`  （也可一次多给些：--limit ${Math.min(r.limit + r.remaining, 5000)}）`);\n  }\n  out.push('');\n  for (const l of r.lines) {\n    const mark = l.isTarget ? '>' : ' ';\n    const body = l.text.length > maxLen ? `${l.text.slice(0, maxLen)} …(+${l.text.length - maxLen})` : l.text;\n    out.push(`${mark} ${String(l.no).padStart(5)} | ${body}`);\n  }\n  return out.join('\\n');\n}\n\n\nexport { makeLocator, parseLocator };\n"
    },
    {
      "path": "src/diagnostics/index.mjs",
      "content": "/**\n * L2 诊断层 —— 指标判定\n *\n * 约定（与任务书 §5.3 一致）：\n *   1. 可定位 —— 每个结论必须附 locator，不可复现的结论不出\n *   2. 死循环豁免正常重试 —— 同参数 + 同错误 + >=3 次，参数有变化的不算\n *   3. 软信号仅 K2 一项，措辞\"疑似\"，不给\"高\"严重度\n *   4. 单样本不出结论\n *   5. 禁止硬编问题 —— 未检测到异常必须在报告中显式列出\n *   6. 处方须自证有效\n */\n\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { KIND } from '../adapters/base.mjs';\nimport { num, pct } from '../summary.mjs';\nimport { observationsFromScan, observationsFromStore, MIN_CHARS } from '../privacy/fingerprints.mjs';\nimport { readProfilePatch, mcpServersFromRows } from '../config/index.mjs';\n\n/** 严重度 */\nexport const SEVERITY = { HIGH: '高', MID: '中', LOW: '低' };\n\n/**\n * @typedef {Object} Finding\n * @property {string} id          指标 ID，如 'E1'\n * @property {string} title       问题标题\n * @property {string} severity    SEVERITY.*\n * @property {string} category    'C'|'E'|'K'|'N'|'A'\n * @property {string} summary     一句话结论\n * @property {Array<{locator:string,note?:string}>} evidence 证据定位\n * @property {string} [impact]    影响估算\n * @property {number} confidence  0~1\n * @property {string} [scope]     会话标识（用于报告分组）\n * @property {string} [tool]      涉及的工具名（E1/E5）\n * @property {number} [repeatCount] 重复次数（E1/E5）\n */\n\n// ---------------------------------------------------------------------------\n// 内部工具\n// ---------------------------------------------------------------------------\n\n/** 把 tool/call 与 tool/result 按 callId 配对 */\nfunction pairCalls(session) {\n  const calls = session.events.filter((e) => e.kind === KIND.TOOL_CALL);\n  const results = session.events.filter((e) => e.kind === KIND.TOOL_RESULT);\n  const byId = new Map();\n  for (const r of results) {\n    if (r.tool_call_id) byId.set(r.tool_call_id, r);\n  }\n  return { calls, results, byId };\n}\n\n/** 按 tool_name + args_hash 分组 */\nfunction groupIdenticalCalls(calls) {\n  const groups = new Map();\n  for (const c of calls) {\n    const key = `${c.tool_name}|${c.tool_args_hash}`;\n    if (!groups.has(key)) groups.set(key, []);\n    groups.get(key).push(c);\n  }\n  return groups;\n}\n\nconst lineOf = (locator) => {\n  const s = String(locator);\n  const i = s.lastIndexOf('#L');\n  return i < 0 ? '?' : s.slice(i + 2);\n};\n\n// ---------------------------------------------------------------------------\n// E1 死循环\n// ---------------------------------------------------------------------------\n\nfunction detectE1(ctx, opts) {\n  const minRepeat = opts.minRepeatCount ?? 3;\n  const findings = [];\n\n  for (const s of ctx.scan.sessions) {\n    const { calls, byId } = pairCalls(s);\n    for (const [key, list] of groupIdenticalCalls(calls)) {\n      if (list.length < minRepeat) continue;\n\n      // 防误报：只取「同参数 + 同错误」的调用；参数有变化的试错不算\n      const errored = list.filter((c) => {\n        const r = byId.get(c.tool_call_id);\n        return r && r.is_error;\n      });\n      if (errored.length < minRepeat) continue;\n\n      const toolName = key.split('|')[0];\n      const first = errored[0];\n      const last = errored[errored.length - 1];\n      findings.push({\n        id: 'E1',\n        title: '死循环',\n        category: 'E',\n        severity: SEVERITY.HIGH,\n        scope: s.sessionId,\n        tool: toolName,\n        repeatCount: errored.length,\n        summary: `${toolName} 用相同参数连续失败 ${errored.length} 次`,\n        evidence: [\n          {\n            locator: `${first.locator}-L${lineOf(last.locator)}`,\n            note: `${errored.length} 次同参数同错误的调用`,\n          },\n          ...errored.map((c) => ({ locator: c.locator, note: `${toolName} 失败` })),\n        ],\n        impact: `约 ${errored.length} 次无效工具调用`,\n        confidence: 0.9,\n      });\n    }\n  }\n  return findings;\n}\n\n// ---------------------------------------------------------------------------\n// C 类：成本\n// ---------------------------------------------------------------------------\n\n/** 中位数（自身基线，不做跨用户比较） */\nfunction median(arr) {\n  if (!arr.length) return null;\n  const s = [...arr].sort((a, b) => a - b);\n  const m = s.length >> 1;\n  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;\n}\n\n/**\n * C5 压缩可观测性 —— **第三轮（待优化报告 Phase 1）新增**\n *\n * 为什么它比 C1 更可信：C1 用\"单位请求 output vs 基线\"**推**浪费，\n * 而 DSH 自己把**实测释放量**写进了日志：\n *   compaction/summary → shadowedTokenCount（这次摘要替代了多少 token）\n *   compaction/prune   → shadowedTokenCount（这次剪枝释放了多少 token）\n * 两者都是白给的交叉验证信号，此前完全没采。\n *\n * 判定：单会话压缩次数 ≥ 3 次（说明上下文反复触顶），报告实测释放量、\n * prune 与 summary 的比例、摘要正文与释放量的比（压缩效率）。\n * 数据全是数字，**零隐私代价**。\n */\nfunction detectC5(ctx, opts) {\n  const minCompactions = opts.c5MinCompactions ?? 3;\n  const findings = [];\n  let totalFreed = 0;\n  let totalCount = 0;\n\n  for (const s of ctx.scan.sessions) {\n    const comps = s.events.filter((e) => e.kind === KIND.COMPACTION);\n    if (!comps.length) continue;\n    const starts = comps.filter((e) => e.compaction_phase === 'start').length;\n    const summaries = comps.filter((e) => e.compaction_phase === 'summary');\n    const prunes = comps.filter((e) => e.compaction_phase === 'prune');\n    // ⚠️ 待优化报告 §4.3：释放量必须**分开算**。\n    //    旧版 freed = summary + prune，却拿只统计 summary 的 summaryChars 去除它 ——\n    //    prune 多的会话里\"回吐比例\"会被系统性低估（分母被 prune 撑大了）。\n    const freedBySummary = summaries.reduce((n, e) => n + (e.shadowed_token_count ?? 0), 0);\n    const freedByPrune = prunes.reduce((n, e) => n + (e.shadowed_token_count ?? 0), 0);\n    const freed = freedBySummary + freedByPrune;\n    const summaryChars = summaries.reduce((n, e) => n + (e.summary_chars ?? 0), 0);\n    const count = starts || summaries.length + prunes.length;\n    totalFreed += freed;\n    totalCount += count;\n    if (count < minCompactions) continue;\n\n    const first = summaries[0] ?? prunes[0] ?? comps[0];\n    // 压缩效率：摘要正文换成 token（4 字符≈1 token）÷ **摘要自己**的释放量\n    const summaryTokens = Math.round(summaryChars / 4);\n    const ratio = freedBySummary > 0 ? summaryTokens / freedBySummary : 0;\n    const parts = [\n      `本会话压缩 ${count} 次（摘要 ${summaries.length} / 剪枝 ${prunes.length}）`,\n      `**实测**释放 ${num(freed)} token（DSH 日志的 shadowedTokenCount，非估算）`,\n    ];\n    if (freedBySummary || freedByPrune) {\n      parts.push(`其中摘要释放 ${num(freedBySummary)}、剪枝释放 ${num(freedByPrune)}`);\n    }\n    if (freedBySummary > 0) {\n      parts.push(`摘要自身约 ${num(summaryTokens)} token，相对**摘要释放量**回吐 ${(ratio * 100).toFixed(0)}%`);\n    }\n\n    findings.push({\n      id: 'C5',\n      title: '压缩可观测性',\n      category: 'C',\n      severity: count >= minCompactions * 3 ? SEVERITY.MID : SEVERITY.LOW,\n      scope: s.sessionId,\n      summary: parts.join('，'),\n      evidence: [\n        { locator: first.locator, note: `首次压缩（实测释放 ${num(first.shadowed_token_count ?? 0)} token）` },\n      ],\n      impact:\n        `反复触发压缩说明上下文一次又一次顶到上限（每次压缩还会让该点之后的 KV cache 失效）。` +\n        `实测释放 ${num(freed)} token 是**DSH 自报的数字**，可以直接和 C1/C2 的估算互相验证`,\n      confidence: 0.95, // 数字是日志里抄的，不是推断的\n    });\n  }\n\n  if (!findings.length) {\n    return {\n      findings,\n      note:\n        totalCount > 0\n          ? `窗口内共压缩 ${totalCount} 次，实测释放 ${num(totalFreed)} token —— 没有会话达到 ${minCompactions} 次阈值`\n          : '窗口内没有 compaction 事件（本机尚未触发过自动压缩）',\n    };\n  }\n  return findings;\n}\n\n/**\n * C6 工具面成本 —— **第三轮新增**\n *\n * `request/header` 里有**完整的工具 schema**（实测 27 个工具、约 29.8 KB），\n * 而它每个请求都要重发一次 —— 这块成本此前从未被计量。\n * 同时能回答：\"注册了但整个窗口 0 次调用\"的工具有几个（白付的 schema）。\n *\n * 只记工具名（指令标识符，不是用户内容）与字节数。\n */\nfunction detectC6(ctx, opts) {\n  const minSchemaChars = opts.c6SchemaChars ?? 20000;\n  const minDeadTools = opts.c6MinDeadTools ?? 5;\n\n  const headers = [];\n  for (const s of ctx.scan.sessions) {\n    for (const e of s.events) if (e.kind === KIND.REQUEST_HEADER) headers.push({ ev: e, session: s });\n  }\n  if (!headers.length) {\n    return { findings: [], note: '窗口内没有 request/header 事件，无法计量工具面成本' };\n  }\n\n  const registered = new Set();\n  for (const h of headers) for (const n of h.ev.tool_names ?? []) registered.add(n);\n  const used = new Set();\n  for (const s of ctx.scan.sessions) {\n    for (const e of s.events) if (e.kind === KIND.TOOL_CALL && e.tool_name) used.add(e.tool_name);\n  }\n  const dead = [...registered].filter((n) => !used.has(n)).sort();\n\n  const bytes = headers.map((h) => h.ev.tool_schema_bytes ?? 0).sort((a, b) => a - b);\n  const medianBytes = bytes[bytes.length >> 1] ?? 0;\n  const maxBytes = bytes[bytes.length - 1] ?? 0;\n  const findings = [];\n  const anchor = headers[0].ev;\n\n  if (medianBytes >= minSchemaChars) {\n    // 4 字符≈1 token 是工具自己的口径（token-meter 的启发式），这里沿用并标注\n    const perRequestTokens = Math.round(medianBytes / 4);\n    findings.push({\n      id: 'C6',\n      title: '工具面成本',\n      category: 'C',\n      severity: perRequestTokens >= 6000 ? SEVERITY.MID : SEVERITY.LOW,\n      scope: `窗口 ${headers.length} 个请求头`,\n      summary:\n        `工具 schema ${num(medianBytes)} 字符（约 ${num(perRequestTokens)} token，按 4 字符/token 估算）` +\n        `随**每个**请求重发；窗口内注册工具 ${registered.size} 个`,\n      evidence: [{ locator: anchor.locator, note: `request/header（${anchor.request_reason ?? '未知原因'}，${anchor.tool_count ?? '?'} 个工具）` }],\n      impact:\n        `按 4 字符/token 估算，这一项每个请求都要付约 ${num(perRequestTokens)} token 的固定输入成本；` +\n        `与工具数量成正比 —— 少注册一个用不到的工具就少付一份`,\n      confidence: 0.8,\n    });\n  }\n\n  if (dead.length >= minDeadTools) {\n    findings.push({\n      id: 'C6',\n      title: '工具面成本',\n      category: 'C',\n      severity: SEVERITY.LOW,\n      scope: '本窗口未观察到调用的工具',\n      // ⚠️ 待优化报告 §4.1：旧措辞\"整个窗口内 0 次调用\"会被读成\"这工具没用/该卸\"。\n      //    但注册是**所有会话的并集**，而单个会话只用自己的预设 ——\n      //    低频插件（如只在做某类任务时才用的工具）仅仅是因为窗口里没遇到那类任务。\n      summary:\n        `注册了 ${registered.size} 个工具，其中 ${dead.length} 个在**本窗口内未观察到调用**：${dead.join('、')}`,\n      evidence: [{ locator: anchor.locator, note: '工具清单来自 request/header 的 tools 数组' }],\n      impact:\n        '这些工具的 schema 仍然每个请求都要重发。**注意：未被调用 ≠ 不需要** —— ' +\n        '窗口内恰好没遇到需要它的任务，同样会出现在这张清单里；' +\n        '请按自己的使用习惯判断，插件的价值不该由一次窗口统计决定。' +\n        '内置工具（create_goal / workflow / read_image 等）是 DSH 自带的，不必处理。',\n      confidence: 0.7, // 从 0.85 下调：这个判据本身带着\"窗口没覆盖到\"的不确定性\n    });\n  }\n\n  if (!findings.length) {\n    return {\n      findings,\n      note: `工具 schema 中位 ${num(medianBytes)} 字符（低于 ${num(minSchemaChars)} 阈值），注册 ${registered.size} 个工具、窗口内未调用 ${dead.length} 个（低于 ${minDeadTools} 阈值）`,\n    };\n  }\n  return findings;\n}\n\n/**\n * C7 上下文注入量 —— **第三轮新增**\n *\n * `agent/inbox/spliced` 是上下文被拼接/替换的痕迹（DSH 往对话里塞东西）。\n * 塞进去的每一个字符都会随后的请求重复计费，所以它算成本。\n * 只记体积与目标，**不记插入内容**。\n */\nfunction detectC7(ctx, opts) {\n  const minSplices = opts.c7MinSplices ?? 20;\n  const minChars = opts.c7MinChars ?? 100000;\n\n  const splices = [];\n  for (const s of ctx.scan.sessions) {\n    for (const e of s.events) if (e.kind === KIND.INBOX_SPLICE) splices.push({ ev: e, session: s });\n  }\n  const chars = splices.reduce((n, x) => n + (x.ev.inserted_chars ?? 0), 0);\n  if (splices.length < minSplices || chars < minChars) {\n    return {\n      findings: [],\n      note:\n        splices.length === 0\n          ? '窗口内没有上下文注入事件'\n          : `窗口内注入 ${splices.length} 次、共 ${num(chars)} 字符 —— 低于阈值（${minSplices} 次 / ${num(minChars)} 字符）`,\n    };\n  }\n\n  const byTarget = new Map();\n  for (const x of splices) {\n    const k = x.ev.splice_target ?? '(未知)';\n    byTarget.set(k, (byTarget.get(k) ?? 0) + 1);\n  }\n  const biggest = splices.reduce((a, b) => ((b.ev.inserted_chars ?? 0) > (a.ev.inserted_chars ?? 0) ? b : a), splices[0]);\n\n  return [\n    {\n      id: 'C7',\n      title: '上下文注入量',\n      category: 'C',\n      severity: chars >= minChars * 3 ? SEVERITY.MID : SEVERITY.LOW,\n      scope: '窗口',\n      summary:\n        `上下文被注入 ${splices.length} 次、共 ${num(chars)} 字符` +\n        `（约 ${num(Math.round(chars / 4))} token，按 4 字符/token 估算）；` +\n        `目标分布：${[...byTarget].map(([k, n]) => `${k}(${n})`).join('、')}`,\n      evidence: [{ locator: biggest.ev.locator, note: `单次注入最大（${num(biggest.ev.inserted_chars ?? 0)} 字符）` }],\n      impact:\n        '注入的内容会留在历史里，被后续每个请求重复计费；' +\n        '把反复粘贴的长内容（约定、文档、术语表）落到项目文件、让 Agent 按需读取，可以省掉这部分',\n      confidence: 0.7,\n    },\n  ];\n}\n\n/**\n * A5 辅助 LLM 开销 —— **第三轮新增**\n *\n * 联网检索（`web/*-llm-request`）与会话标题（`session/title-llm-request`）\n * 都是**独立的模型调用**，日志里没有 usage —— 但它们确实在花钱。\n * 这里用 次数 × max_tokens 给**上界**，并明确标注是上界而不是实测。\n */\nfunction detectA5(ctx, opts) {\n  const minRequests = opts.a5MinRequests ?? 20;\n\n  const aux = [];\n  for (const s of ctx.scan.sessions) {\n    for (const e of s.events) if (e.kind === KIND.AUX_REQUEST) aux.push({ ev: e, session: s });\n  }\n  if (aux.length < minRequests) {\n    return {\n      findings: [],\n      note:\n        aux.length === 0\n          ? '窗口内没有辅助 LLM 请求'\n          : `窗口内辅助 LLM 请求 ${aux.length} 次（需 ${minRequests} 次）—— 低于阈值`,\n    };\n  }\n\n  const bySource = new Map();\n  let bound = 0;\n  const models = new Set();\n  for (const x of aux) {\n    bySource.set(x.ev.aux_source, (bySource.get(x.ev.aux_source) ?? 0) + 1);\n    bound += x.ev.aux_max_tokens ?? 0;\n    if (x.ev.aux_model) models.add(x.ev.aux_model);\n  }\n  const top = [...bySource].sort((a, b) => b[1] - a[1]);\n\n  return [\n    {\n      id: 'A5',\n      title: '辅助 LLM 开销',\n      category: 'A',\n      severity: aux.length >= minRequests * 3 ? SEVERITY.MID : SEVERITY.LOW,\n      scope: '窗口',\n      summary:\n        `主对话之外还有 ${aux.length} 次辅助模型调用：` +\n        `${top.map(([k, n]) => `${k === 'web-search' ? '联网检索' : '会话标题'} ${n} 次`).join('、')}；` +\n        `按各自的 maxTokens 上限估算，最多 ${num(bound)} token（模型：${[...models].join('、') || '未标注'}）`,\n      evidence: aux.slice(0, 3).map((x) => ({\n        locator: x.ev.locator,\n        note: `${x.ev.aux_source} · ${x.ev.aux_model ?? '?'} · maxTokens ${num(x.ev.aux_max_tokens ?? 0)}`,\n      })),\n      impact:\n        `**这些调用不计入报告的 token 概览**（DSH 没给它们记 usage），所以真实开销比概览数字更高。` +\n        `${num(bound)} 是上界（每次都跑满 maxTokens 才会达到），实际通常远低于它 —— 但次数本身是可优化的：` +\n        '先 grep 本地已有结论、少做重复联网检索',\n      confidence: 0.9,\n    },\n  ];\n}\n\n/**\n * C1 token 消耗过快 —— **第二轮评估 F12 重写**\n *\n * 旧判据（\"单会话 output 总量 > 全会话总量中位数 × 1.5\"）有三处硬伤，\n * 实测 13 个会话命中 6 个，测出来的是\"这个会话干了多少活\"而不是\"浪费\"：\n *   1. 基线混入空会话：两个 0 值会话把中位数从 15,760 拉到 10,329；\n *   2. 主会话与子代理会话混在一个中位数里 —— 子代理串行干活天然高于中位数；\n *   3. 不做归一化：output 总量只反映会话长短，长会话必然上榜。\n * 而且报告里写\"自身基线\"，那个数字其实与\"自身\"无关。\n *\n * 新判据：\n *   - 基线只取**主会话**（非子代理、有 assistant 用量、output > 0）的单位请求 output 中位数，\n *     且**排除被判定的那个会话自身**（评估 §5.1：自己不该当自己的对照）\n *   - 归一化：比较 output / 请求数，而不是会话总量\n *   - 绝对量下限：会话 output 总量低于阈值不报（小会话凭比例上榜没有意义）\n *   - 措辞如实说明\"产出量大不必然是浪费\"，并指向 E1/E5/C2 去看重复劳动\n */\nfunction detectC1(ctx, opts) {\n  const ratio = opts.c1BaselineRatio ?? 2;\n  const minSessions = opts.c1MinSessions ?? 3;\n  const minOutput = opts.c1MinOutputTokens ?? 20000;\n  if (ctx.scan.sessions.length < minSessions) return [];\n\n  const stats = [];\n  for (const s of ctx.scan.sessions) {\n    const msgs = s.events.filter((e) => e.kind === KIND.ASSISTANT_MSG);\n    if (!msgs.length) continue;\n    const output = msgs.reduce((n, e) => n + (e.output_tokens ?? 0), 0);\n    stats.push({\n      session: s,\n      msgs,\n      output,\n      requests: msgs.length,\n      perRequest: output / msgs.length,\n      subagent: Boolean(s.isSubagent),\n    });\n  }\n\n  // 基线：主会话、有实际产出 —— **且排除被判定者自身**。\n  //\n  // 旧实现把被判会话自己也算进基线池（第三方评估 §5.1）：中位数对离群值稳健，\n  // 所以多数情况下结论不变，但\"自己当自己的对照\"在口径上站不住 ——\n  // 一个远超他人的会话会把基线抬高，从而**压低自己的倍率**，属于自我掩饰。\n  // 现在逐会话排除自身后再取中位数。\n  const poolEntries = stats.filter((x) => !x.subagent && x.output > 0);\n  const baselineFor = (self) =>\n    median(poolEntries.filter((x) => x !== self).map((x) => x.perRequest));\n  const base = median(poolEntries.map((x) => x.perRequest));\n  if (!poolEntries.length || !base || base <= 0) return [];\n\n  const findings = [];\n  for (const x of stats) {\n    if (x.subagent) continue; // 子代理天然高于基线，单列（A4）而不是在这里报\n    if (x.output < minOutput) continue; // 绝对量下限\n    // 对照取\"排除了本会话之后\"的基线；剩余样本不足时退回全体基线（并在摘要里如实标注）\n    const own = baselineFor(x);\n    const useBase = own && own > 0 ? own : base;\n    const selfExcluded = own && own > 0;\n    if (x.perRequest <= useBase * ratio) continue;\n    const worst = x.msgs.reduce((a, b) => ((b.output_tokens ?? 0) > (a.output_tokens ?? 0) ? b : a), x.msgs[0]);\n    findings.push({\n      id: 'C1',\n      title: 'token 消耗过快',\n      category: 'C',\n      severity: SEVERITY.HIGH,\n      scope: x.session.sessionId,\n      summary:\n        `本会话单位请求 output ${num(x.perRequest)}（共 ${num(x.output)} / ${x.requests} 次请求），` +\n        `是主会话基线 ${num(useBase)} 的 ${(x.perRequest / useBase).toFixed(1)} 倍（阈值 ${ratio} 倍；` +\n        `基线为${selfExcluded ? '排除本会话后的其余主会话' : '全体主会话（可对照样本不足）'}中位值）`,\n      evidence: [{ locator: worst.locator, note: `单次 output 最高的一条（${num(worst.output_tokens ?? 0)} token）` }],\n      impact:\n        `相对基线约多消耗 ${num(Math.round((x.perRequest - useBase) * x.requests))} output token；` +\n        `注意：产出量大不必然是浪费，请结合 E1（死循环）/E5（冗余调用）/C2（上下文膨胀）判断`,\n      confidence: 0.6,\n    });\n  }\n  return findings;\n}\n\n/**\n * C2 上下文膨胀\n * 末轮 / 首轮 input 比值 > 10x 且 cache_read 占比 < 30%\n */\nfunction detectC2(ctx, opts) {\n  const growthRatio = opts.c2GrowthRatio ?? 10;\n  const cacheShareMin = opts.c2CacheShareMin ?? 0.3;\n  const findings = [];\n\n  for (const s of ctx.scan.sessions) {\n    const msgs = s.events.filter((e) => e.kind === KIND.ASSISTANT_MSG);\n    if (msgs.length < 8) continue; // 太少没有\"膨胀\"可言\n    const inputs = msgs.map((m) => m.input_tokens ?? 0);\n    const first = inputs[0];\n    const last = inputs[inputs.length - 1];\n    if (first <= 0 || last <= first * growthRatio) continue;\n\n    const totalIn = inputs.reduce((a, b) => a + b, 0);\n    const cacheRead = msgs.reduce((n, m) => n + (m.cache_read_tokens ?? 0), 0);\n    const share = totalIn + cacheRead > 0 ? cacheRead / (totalIn + cacheRead) : 0;\n    if (share >= cacheShareMin) continue; // 已经在吃缓存红利，不算膨胀\n\n    findings.push({\n      id: 'C2',\n      title: '上下文膨胀',\n      category: 'C',\n      severity: SEVERITY.HIGH,\n      scope: s.sessionId,\n      summary:\n        `input 从首轮 ${num(first)} 涨到末轮 ${num(last)}（${(last / first).toFixed(1)} 倍），` +\n        `cacheRead 仅占 ${pct(share)}`,\n      evidence: [\n        { locator: msgs[0].locator, note: `首轮 input ${num(first)}` },\n        { locator: msgs[msgs.length - 1].locator, note: `末轮 input ${num(last)}` },\n      ],\n      impact: `末轮比首轮多带 ${num(last - first)} input token`,\n      confidence: 0.8,\n    });\n  }\n  return findings;\n}\n\n/**\n * C3 长会话疲劳 —— **第三轮接线 compaction**\n *\n * 旧实现的注释写着\"且无 compact\"，代码却只数消息条数：实测有一个会话被报\n * \"长会话疲劳\"，而它**实际压缩过 19 次**（每次释放几万 token）。长期靠\n * `/compact` 续命的用户会被反复建议 `/compact` —— 而压缩早就在发生了。\n *\n * 现在：只数**最后一次压缩之后**还\"活着\"的消息（compaction 的 shadowedRange.end\n * 之后的部分），因为被压缩遮蔽的历史已经不再占用上下文。\n *   - 活消息 > 200 → 真的在疲劳（压缩没跟上）\n *   - 总消息 > 200 但活消息 ≤ 200 → 不报，并在 notDetected 里说明\"压缩正在起作用\"\n */\nfunction detectC3(ctx, opts) {\n  const limit = opts.c3MessageLimit ?? 200;\n  const findings = [];\n  let relieved = 0;\n\n  for (const s of ctx.scan.sessions) {\n    const msgs = s.events.filter((e) => e.kind === KIND.USER_MSG || e.kind === KIND.ASSISTANT_MSG);\n    if (msgs.length <= limit) continue;\n\n    // 压缩遮蔽到哪里为止（取所有 compaction 事件里最大的 shadowed_end）\n    const comps = s.events.filter((e) => e.kind === KIND.COMPACTION);\n    const shadowedUpTo = comps.reduce(\n      (m, e) => (Number.isFinite(e.shadowed_end) ? Math.max(m, e.shadowed_end) : m),\n      0,\n    );\n    const liveMsgs = msgs.filter((e) => (Number.isFinite(e.seq) ? e.seq > shadowedUpTo : true));\n    const freed = comps.reduce((n, e) => n + (e.shadowed_token_count ?? 0), 0);\n\n    if (shadowedUpTo > 0 && liveMsgs.length <= limit) {\n      relieved += 1; // 压缩在起作用，不该报\"疲劳\"\n      continue;\n    }\n\n    const ev = s.events.find((e) => e.kind === KIND.USER_MSG) ?? s.events[0];\n    if (!ev) continue;\n    const compNote =\n      shadowedUpTo > 0\n        ? `；已压缩 ${comps.filter((c) => c.compaction_phase === 'start').length} 次、实测释放 ${num(freed)} token，` +\n          `但压缩后仍有 ${liveMsgs.length} 条未遮蔽消息`\n        : '；会话内**没有发生任何压缩**';\n    findings.push({\n      id: 'C3',\n      title: '长会话疲劳',\n      category: 'C',\n      severity: SEVERITY.MID,\n      scope: s.sessionId,\n      summary: `单会话共 ${msgs.length} 条消息，超过 ${limit} 条阈值${compNote}`,\n      evidence: [{ locator: ev.locator, note: `会话共 ${msgs.length} 条消息（活消息 ${liveMsgs.length} 条）` }],\n      impact: '长会话更容易跑偏、重复劳动，建议拆分任务或开新会话',\n      confidence: 0.7,\n    });\n  }\n\n  if (!findings.length) {\n    return {\n      findings,\n      note:\n        relieved > 0\n          ? `${relieved} 个会话消息数超 ${limit} 条，但压缩在起作用（最后一次压缩之后再无 ${limit} 条以上的未遮蔽消息）—— 不判为疲劳`\n          : null,\n    };\n  }\n  return findings;\n}\n\n// ---------------------------------------------------------------------------\n// E2 反复失败\n// ---------------------------------------------------------------------------\n\nfunction detectE2(ctx, opts) {\n  const threshold = opts.errorRateThreshold ?? 0.3;\n  const minCalls = opts.minCallsForRate ?? 10;\n  const findings = [];\n\n  for (const s of ctx.scan.sessions) {\n    const { calls, results } = pairCalls(s);\n    if (calls.length < minCalls) continue; // 样本太小不下结论\n    const errors = results.filter((r) => r.is_error);\n    const rate = results.length > 0 ? errors.length / results.length : 0;\n    if (rate <= threshold) continue;\n\n    findings.push({\n      id: 'E2',\n      title: '反复失败',\n      category: 'E',\n      severity: SEVERITY.MID,\n      scope: s.sessionId,\n      summary:\n        `工具调用错误率 ${(rate * 100).toFixed(1)}%（${errors.length}/${results.length}）` +\n        `，高于 ${(threshold * 100).toFixed(0)}% 阈值`,\n      evidence: errors.slice(0, 10).map((r) => ({ locator: r.locator, note: '工具调用失败' })),\n      impact: `${errors.length} 次失败的工具调用`,\n      confidence: 0.85,\n    });\n  }\n  return findings;\n}\n\n// ---------------------------------------------------------------------------\n// E5 冗余重复调用\n//\n// ⚠️ 本指标为**基于真实数据实测新增**，不在任务书原 17 项内。\n//\n// 起因：任务书的 E1 要求「同参数 + 同错误」，但实测本机数据中\n// 同参数重复 4 次的 list_agents 调用**全部成功** —— 严格按 E1 定义\n// 一条都命中不了。而这类「同参数、成功、重复」的调用同样在浪费\n// token（每次调用都要重新走一遍模型 + 工具），值得单独报出。\n//\n// 与 E1 的边界：\n//   E1 = 同参数 + 同错误（卡死，无法推进）\n//   E5 = 同参数 + 无错误（冗余，可避免的重复劳动）\n// ---------------------------------------------------------------------------\n\nfunction detectE5(ctx, opts) {\n  const minRepeat = opts.minRepeatCount ?? 3;\n  const findings = [];\n\n  for (const s of ctx.scan.sessions) {\n    const { calls, byId } = pairCalls(s);\n    for (const [key, list] of groupIdenticalCalls(calls)) {\n      if (list.length < minRepeat) continue;\n\n      const paired = list.map((c) => byId.get(c.tool_call_id)).filter(Boolean);\n      if (paired.length < list.length) continue; // 结果缺失则不下结论\n      // 只要有错误就交给 E1，避免同一件事报两次\n      if (paired.some((r) => r.is_error)) continue;\n\n      const toolName = key.split('|')[0];\n      const redundant = list.length - 1; // 首次视为可能必要\n      const first = list[0];\n      const last = list[list.length - 1];\n      findings.push({\n        id: 'E5',\n        title: '冗余重复调用',\n        category: 'E',\n        severity: SEVERITY.MID,\n        scope: s.sessionId,\n        tool: toolName,\n        repeatCount: list.length,\n        summary: `${toolName} 用完全相同的参数成功调用了 ${list.length} 次（可省 ${redundant} 次）`,\n        evidence: [\n          {\n            locator: `${first.locator}-L${lineOf(last.locator)}`,\n            note: `${list.length} 次同参数调用`,\n          },\n          ...list.map((c) => ({ locator: c.locator, note: `${toolName} 同参数调用` })),\n        ],\n        impact: `约 ${redundant} 次冗余调用，每次都要重新消耗 token`,\n        confidence: 0.75,\n      });\n    }\n  }\n  return findings;\n}\n\n// ---------------------------------------------------------------------------\n// 指标注册表\n// ---------------------------------------------------------------------------\n\n// ---------------------------------------------------------------------------\n// E4 计划执行脱节\n// ---------------------------------------------------------------------------\n\nfunction detectE4(ctx, opts) {\n  const minStepsAfter = opts.e4MinStepsAfter ?? 5;\n  const findings = [];\n\n  for (const s of ctx.scan.sessions) {\n    const todos = s.events.filter((e) => e.kind === KIND.TODO_WRITE);\n    if (todos.length === 0) continue;\n    const last = todos[todos.length - 1];\n    const total = last.todo_count ?? 0;\n    const done = last.done_count ?? 0;\n    if (total <= 0 || done > 0) continue;\n\n    // 写完计划之后还得真的在干活，否则\"没执行\"可能只是会话刚开始\n    const idx = s.events.indexOf(last);\n    const after = s.events.slice(idx + 1).filter((e) => e.kind === KIND.TOOL_CALL).length;\n    if (after < minStepsAfter) continue;\n\n    findings.push({\n      id: 'E4',\n      title: '计划执行脱节',\n      category: 'E',\n      severity: SEVERITY.MID,\n      scope: s.sessionId,\n      summary: `写了 ${total} 条计划，之后又执行了 ${after} 次工具调用，但没有一条被标记完成`,\n      evidence: [\n        { locator: last.locator, note: `${total} 条计划，0 条完成` },\n      ],\n      impact: '计划与执行脱节时，Agent 容易重复劳动或漏掉步骤',\n      confidence: 0.65,\n    });\n  }\n  return findings;\n}\n\n// ---------------------------------------------------------------------------\n// N 类：风险\n// ---------------------------------------------------------------------------\n\n/** 命令执行类工具（与适配器的 COMMAND_TOOLS 保持一致） */\nconst CMD_TOOL_RE =\n  /^(?:pwsh|powershell|powershell\\.exe|pwsh\\.exe|bash|sh|zsh|dash|shell|exec|execute|run_command|cmd|cmd\\.exe|terminal|node|python|python3|ruby)$/i;\n\n/**\n * N1 环境命令反复失败\n * 与 E1 的区别：不要求同参数 —— 命令类失败往往是参数不同但环境相同\n */\nfunction detectN1(ctx, opts) {\n  const minRepeat = opts.n1MinRepeat ?? 3;\n  const findings = [];\n\n  for (const s of ctx.scan.sessions) {\n    const { byId } = pairCalls(s);\n    const cmdCalls = s.events.filter(\n      (e) => e.kind === KIND.TOOL_CALL && CMD_TOOL_RE.test(String(e.tool_name || '')),\n    );\n    if (cmdCalls.length === 0) continue;\n\n    const errs = cmdCalls.filter((c) => {\n      const r = byId.get(c.tool_call_id);\n      return r && r.is_error;\n    });\n    if (errs.length < minRepeat) continue;\n\n    findings.push({\n      id: 'N1',\n      title: '环境命令反复失败',\n      category: 'N',\n      severity: SEVERITY.MID,\n      scope: s.sessionId,\n      summary: `命令类调用失败 ${errs.length} 次（阈值 ${minRepeat}）`,\n      evidence: errs.slice(0, 8).map((c) => ({ locator: c.locator, note: `${c.tool_name} 失败` })),\n      impact: '命令反复失败通常是环境问题（权限 / 路径 / 工具缺失），不是模型问题',\n      confidence: 0.8,\n    });\n  }\n  return findings;\n}\n\n/** N2 高危操作 —— danger 由适配器在解析时打标，这里只汇总 */\nfunction detectN2(ctx) {\n  const findings = [];\n  for (const s of ctx.scan.sessions) {\n    const hits = s.events.filter((e) => e.kind === KIND.TOOL_CALL && e.danger?.length);\n    if (hits.length === 0) continue;\n    const patterns = [...new Set(hits.flatMap((h) => h.danger))];\n    findings.push({\n      id: 'N2',\n      title: '高风险操作',\n      category: 'N',\n      severity: SEVERITY.HIGH,\n      scope: s.sessionId,\n      summary: `检测到 ${hits.length} 次高危命令调用，命中模式：${patterns.join('、')}`,\n      dangerPatterns: patterns,\n      evidence: hits.slice(0, 8).map((h) => ({\n        locator: h.locator,\n        note: `${h.tool_name} 命中 ${h.danger.join('、')}`,\n      })),\n      impact: '建议对这类命令建立人工确认习惯',\n      confidence: 0.9,\n    });\n  }\n  return findings;\n}\n\n/** 事件时间戳 → 毫秒（拿不到返回 null） */\nfunction tsOf(ev) {\n  const t = ev?.ts ? Date.parse(ev.ts) : NaN;\n  return Number.isFinite(t) ? t : null;\n}\n\n/**\n * N3 权限审批摩擦 —— **第二轮评估 F1：从\"不可实现\"变成可实现**\n *\n * 旧版本的定性理由是\"DSH 只有 approval/policy，没有 approval/asked / approval/decided\"。\n * 实测这句话是错的：本机 23 次 asked + 23 次 decided 都在日志里，且 decided 通过\n * `id` 与 asked 关联。适配层已补上这两类事件（只记 id / 工具名 / 结论，\n * **不记 reason 正文**）。\n *\n * 现在能回答：审批多不多、卡在哪些工具上、等人批了多久、有没有被拒。\n */\nfunction detectN3(ctx, opts) {\n  const minAsks = opts.n3MinAsks ?? 5;\n  const slowMs = opts.n3SlowDecisionMs ?? 60000;\n\n  const asked = new Map(); // id → { ev, tool }\n  const decided = new Map();\n  for (const s of ctx.scan.sessions) {\n    for (const e of s.events) {\n      if (e.kind !== KIND.APPROVAL) continue;\n      if (e.approval_phase === 'asked' && e.approval_id) asked.set(e.approval_id, { ev: e, tool: e.tool_name });\n      if (e.approval_phase === 'decided' && e.approval_id) decided.set(e.approval_id, e);\n    }\n  }\n  if (asked.size < minAsks) {\n    return {\n      findings: [],\n      note: `窗口内审批请求 ${asked.size} 次（需 ${minAsks} 次）—— 低于阈值，不判定为摩擦`,\n    };\n  }\n\n  const byTool = new Map();\n  let denied = 0;\n  let unknown = 0;\n  let unknownOutcome = 0;\n  const waits = [];\n  let slowest = null;\n  for (const [id, a] of asked) {\n    byTool.set(a.tool, (byTool.get(a.tool) ?? 0) + 1);\n    const d = decided.get(id);\n    if (!d) {\n      unknown += 1;\n      continue;\n    }\n    // outcome 判定：**显式匹配拒绝语义**，其余归\"未知结果\"，绝不猜。\n    //\n    // 旧实现是 `if (!/^allow/i.test(outcome)) denied += 1` —— 任何非 allow* 开头\n    // 的结果（approved / accept / granted …）都被计成\"被拒\"。第三方实测拿\n    // 5 个 approved 跑出\"被拒 5 次\"；若 DSH 某版本改用 approved 措辞，N3 的\n    // 被拒字段会系统性全错，而用户会据此调整权限配置 —— 误导比不报更糟。\n    const outcome = String(d.outcome ?? '').toLowerCase().trim();\n    if (/^(deny|denied|reject|rejected|decline|declined|refus|forbid)/.test(outcome)) {\n      denied += 1;\n    } else if (!/^(allow|approv|accept|grant|ok|yes|permit)/.test(outcome)) {\n      unknownOutcome += 1;\n    }\n    const gap = tsOf(d) !== null && tsOf(a.ev) !== null ? tsOf(d) - tsOf(a.ev) : null;\n    if (gap !== null && gap >= 0) {\n      waits.push(gap);\n      if (!slowest || gap > slowest.gap) slowest = { gap, ev: a.ev, tool: a.tool };\n    }\n  }\n  const topTools = [...byTool.entries()].sort((x, y) => y[1] - x[1]).slice(0, 3);\n  const medWait = median(waits);\n  const parts = [`审批请求 ${asked.size} 次`];\n  if (topTools.length) parts.push(`集中在 ${topTools.map(([t, n]) => `${t}(${n})`).join('、')}`);\n  if (medWait !== null) parts.push(`等待审批中位 ${(medWait / 1000).toFixed(1)} 秒`);\n  // 三类结果分开报：被拒 / 结果无法识别 / 无对应决定记录（彼此不混算）\n  if (denied) parts.push(`被拒 ${denied} 次`);\n  if (unknownOutcome) parts.push(`结果无法识别 ${unknownOutcome} 次`);\n  if (unknown) parts.push(`无对应决定记录 ${unknown} 次`);\n\n  const first = [...asked.values()][0].ev;\n  const evidence = [{ locator: first.locator, note: `首次审批请求（${String(first.tool_name)}）` }];\n  if (slowest) {\n    evidence.push({\n      locator: slowest.ev.locator,\n      note: `等待最久的一次：${(slowest.gap / 1000).toFixed(1)} 秒（${String(slowest.tool)}）`,\n    });\n  }\n\n  return [\n    {\n      id: 'N3',\n      title: '权限审批摩擦',\n      category: 'N',\n      severity: medWait !== null && medWait > slowMs ? SEVERITY.MID : SEVERITY.LOW,\n      scope: (ctx.scan.sessions.find((s) => s.events.includes(first)) ?? {}).sessionId ?? null,\n      summary: parts.join('，'),\n      evidence,\n      impact: '反复审批会打断你的节奏；把常用且低风险的工具固化到权限预设可省掉这些往返',\n      confidence: 0.8,\n    },\n  ];\n}\n\n/**\n * N4 API 重试频繁 —— **第二轮评估 F1：从\"不可实现\"变成可实现**\n *\n * 旧理由\"DSH 会话日志中不存在 llm/retry 事件\"实测是错的：\n * `llm/retry` 携带失败码、重试序号、退避时长。适配层已补上。\n */\nfunction detectN4(ctx, opts) {\n  const minRetries = opts.n4MinRetries ?? 3;\n\n  const retries = [];\n  for (const s of ctx.scan.sessions) {\n    for (const e of s.events) {\n      if (e.kind === KIND.RETRY) retries.push({ ev: e, session: s });\n    }\n  }\n  if (retries.length < minRetries) {\n    return {\n      findings: [],\n      note: `窗口内模型请求重试 ${retries.length} 次（需 ${minRetries} 次）—— 低于阈值，不判定为频繁`,\n    };\n  }\n\n  const codes = new Map();\n  let delaySum = 0;\n  for (const r of retries) {\n    codes.set(r.ev.failure_code ?? '(未标注)', (codes.get(r.ev.failure_code ?? '(未标注)') ?? 0) + 1);\n    delaySum += r.ev.delay_ms ?? 0;\n  }\n  const codeText = [...codes.entries()].sort((a, b) => b[1] - a[1]).map(([c, n]) => `${c}×${n}`).join('、');\n\n  return [\n    {\n      id: 'N4',\n      title: 'API 重试频繁',\n      category: 'N',\n      severity: retries.length >= minRetries * 2 ? SEVERITY.MID : SEVERITY.LOW,\n      scope: retries[0].session.sessionId,\n      summary: `发生 ${retries.length} 次模型请求重试，失败码：${codeText}，累计退避 ${(delaySum / 1000).toFixed(1)} 秒`,\n      evidence: retries.slice(0, 5).map((r) => ({\n        locator: r.ev.locator,\n        note: `${r.ev.provider ?? '?'} ${r.ev.failure_code ?? ''} 第 ${r.ev.retry_index ?? '?'}/${r.ev.max_retries ?? '?'} 次重试`,\n      })),\n      impact: '每次重试都是一次新的提供方请求，可能重复计费并增加等待',\n      confidence: 0.8,\n    },\n  ];\n}\n\n/**\n * E3 工具结果过大 —— **第二轮评估 F1：从\"不可实现\"变成可实现**\n *\n * 旧理由\"tool/result 只归一化 is_error，不含 content 原文与长度\"是**适配层的自我描述错误**：\n * 原始记录里 `data.message.content[].text` 就在手边（适配器算完长度把正文丢了）。\n * 现在适配层记录 `text_len`（**只有长度，没有正文**），本指标据此判定。\n */\nfunction detectE3(ctx, opts) {\n  const bigChars = opts.e3ResultChars ?? 8192;\n  const minCount = opts.e3MinCount ?? 5;\n  const maxFindings = opts.e3MaxFindings ?? 3; // 只列最严重的几个会话，避免刷屏\n  const candidates = [];\n  let sawSome = 0;\n  let totalBig = 0;\n\n  for (const s of ctx.scan.sessions) {\n    // tool/result 只有 callId，需要用 tool/call 把工具名接回来\n    const nameByCall = new Map();\n    for (const e of s.events) {\n      if (e.kind === KIND.TOOL_CALL && e.tool_call_id) nameByCall.set(e.tool_call_id, e.tool_name);\n    }\n    const results = s.events.filter((e) => e.kind === KIND.TOOL_RESULT);\n    if (!results.length) continue;\n\n    const big = results.filter((e) => (e.text_len ?? 0) > bigChars);\n    if (big.length) sawSome += big.length;\n    if (big.length < minCount) continue;\n\n    const chars = big.reduce((n, e) => n + (e.text_len ?? 0), 0);\n    totalBig += chars;\n    const byTool = new Map();\n    for (const e of big) {\n      const t = nameByCall.get(e.tool_call_id) ?? '(未知工具)';\n      const cur = byTool.get(t) ?? { n: 0, chars: 0 };\n      cur.n += 1;\n      cur.chars += e.text_len ?? 0;\n      byTool.set(t, cur);\n    }\n    const topTools = [...byTool.entries()].sort((a, b) => b[1].chars - a[1].chars).slice(0, 3);\n    const largest = big.reduce((a, b) => ((b.text_len ?? 0) > (a.text_len ?? 0) ? b : a), big[0]);\n\n    candidates.push({\n      chars,\n      finding: {\n        id: 'E3',\n        title: '工具结果过大',\n        category: 'E',\n        severity: big.length >= 10 ? SEVERITY.MID : SEVERITY.LOW,\n        scope: s.sessionId,\n        summary:\n          `工具结果 ${results.length} 条中有 ${big.length} 条超过 ${num(bigChars)} 字符` +\n          `（累计 ${num(chars)} 字符，最大一条 ${num(largest.text_len ?? 0)} 字符）` +\n          (topTools.length ? `，主要来自 ${topTools.map(([t, v]) => `${t}(${v.n} 条)`).join('、')}` : ''),\n        evidence: [{ locator: largest.locator, note: `最大一条工具结果（${num(largest.text_len ?? 0)} 字符）` }],\n        impact:\n          '超大工具结果会随历史反复重发并挤占上下文；用 compaction/prune 或落盘（spill）可省下这部分重复输入',\n        confidence: 0.8,\n      },\n    });\n  }\n\n  // 只留最严重的几个会话：E3 的处方是**一个全局配置**，列 6 个会话只是刷屏\n  const findings = candidates\n    .sort((a, b) => b.chars - a.chars)\n    .slice(0, maxFindings)\n    .map((c) => c.finding);\n\n  if (!findings.length) {\n    return {\n      findings,\n      note:\n        sawSome > 0\n          ? `窗口内有 ${sawSome} 条超大工具结果，但没有任何会话达到 ${minCount} 条阈值（已按会话过滤噪音）`\n          : `窗口内没有超过 ${num(bigChars)} 字符的工具结果`,\n    };\n  }\n  if (candidates.length > findings.length) {\n    findings[0] = {\n      ...findings[0],\n      impact:\n        `${findings[0].impact}（同类会话共 ${candidates.length} 个、累计 ${num(totalBig)} 字符，` +\n        `此处只列最大的 ${findings.length} 个）`,\n    };\n  }\n  return findings;\n}\n\n// ---------------------------------------------------------------------------\n// A 类：资产\n// ---------------------------------------------------------------------------\n\n/**\n * A3 高频手动序列 —— **第二轮评估 F14 收窄**\n *\n * 旧版本是\"相邻工具对直方图\"：相邻两个不同工具重复 ≥5 次就报\"可考虑固化为技能\"。\n * 实测本机 18 条，其中一半是同一个对的镜像（grep→read 10 与 read→grep 9、\n * pwsh→read 与 read→pwsh），而\"读文件后编辑、编辑后跑命令\"本来就是正规工作流。\n *\n * 三处收窄：\n *   1. 去镜像：a→b 与 b→a 合成一次计数；\n *   2. 排除含通用工具的对：任一端是通用工具（读 / 写 / 编辑 / grep / 命令 / 委派）\n *      就不算\"可固化套路\"—— 任何任务都要走这些路，留下的是两端都很专门的序列；\n *   3. 跨会话合并：同一个对只报一条，并给出会话数。\n *\n * ⚠️ 另有一条老约束：必须是两个**不同**工具的相邻转换。\n *    早期版本允许 `web_fetch→web_fetch`，把\"连续抓取 44 个 URL\"报成 4 条 —— 那是\n *    单一工具的重复使用（已由 E5 覆盖），不是\"序列\"。\n *\n * 2026-10-15 决策 D5：通用工具清单不再纯硬编码，改为 **基础集 + 从会话数据自动学习**。\n *\n *   - **基础集**（`BASE_GENERIC_TOOLS`）硬编码、不可被学习移除 —— 它是保底判据，\n *     任何\"从数据学出来\"的东西都不许把 `read`/`pwsh` 这类工具重新变成候选。\n *   - **学习只做排除**，判据是**广度**：一个工具出现在 ≥ `a3GenericMinSessions`（默认 3）\n *     个不同会话里，就视为通用工具 —— 跨任务普遍出现的工具不可能是\"某个任务的固定套路\"。\n *   - **为什么不用\"内置包白名单\"**：会话数据里只有工具名，**没有工具→包的映射**\n *     （`request/header` 给的是 tool_names 与 schema 体积，不含包名），所以\"排除\n *     `@deepseek-ai/*` 提供的工具\"在这条数据源上无法判定。硬要按包名排除就只能靠猜，\n *     而本项目\"宁可承认做不到，也不假装有数据\"。广度判据是**可复核**的：它只看\n *     \"这个工具出现在几个会话里\"，任何人都能从报告里验证。\n *   - 学习结果**如实报出**：A3 命中时写进 summary，未命中时作为说明进 notDetected\n *     （`runDiagnostics` 会把 `{findings, note}` 的 note 放进\"未检测到\"的说明里）。\n *   - 可关掉/可追加：`opts.a3LearnGeneric = false` 关闭学习；`opts.a3GenericTools`\n *     追加排除名单（用户知道自己环境里哪些工具是通用的）。\n */\nconst BASE_GENERIC_TOOLS = new Set([\n  'read', 'write', 'edit', 'grep', 'glob', 'pwsh', 'bash', 'sh', 'shell',\n  'todo_write', 'ask_user_question', 'compress', 'subagent', 'subagent_fork',\n  'list_agents', 'send_message', 'job_output', 'job_list', 'job_kill',\n]);\n\n/**\n * 从会话数据里学习\"通用工具\"（决策 D5）：在 ≥ minSessions 个不同会话里都出现过的工具。\n *\n * @param {{scan:{sessions:Array}}} ctx\n * @param {{a3GenericMinSessions?:number, a3LearnGeneric?:boolean}} [opts]\n * @returns {Set<string>}\n */\nexport function learnedGenericTools(ctx, opts = {}) {\n  const out = new Set();\n  if (opts.a3LearnGeneric === false) return out;\n  const minSessions = opts.a3GenericMinSessions ?? 3;\n  const byTool = new Map();\n  for (const s of ctx?.scan?.sessions ?? []) {\n    const seen = new Set();\n    for (const e of s.events ?? []) {\n      if (e.kind !== KIND.TOOL_CALL || !e.tool_name || seen.has(e.tool_name)) continue;\n      seen.add(e.tool_name);\n      byTool.set(e.tool_name, (byTool.get(e.tool_name) ?? 0) + 1);\n    }\n  }\n  for (const [tool, sessions] of byTool) {\n    if (sessions >= minSessions) out.add(tool);\n  }\n  return out;\n}\n\nfunction detectA3(ctx, opts) {\n  const minRepeat = opts.a3MinRepeat ?? 5;\n  const learned = learnedGenericTools(ctx, opts);\n  const extra = new Set(opts.a3GenericTools ?? []);\n  const isGeneric = (n) => BASE_GENERIC_TOOLS.has(n) || extra.has(n) || learned.has(n);\n  const learnedList = [...learned].sort();\n  const criteria =\n    `判据：基础通用工具 ${BASE_GENERIC_TOOLS.size} 个` +\n    ` + 本次自动学习 ${learnedList.length} 个` +\n    (learnedList.length ? `（${learnedList.slice(0, 8).join('、')}${learnedList.length > 8 ? '…' : ''}）` : '') +\n    (extra.size ? ` + 手工追加 ${extra.size} 个` : '');\n\n  const pairs = new Map();\n  for (const s of ctx.scan.sessions) {\n    const calls = s.events.filter((e) => e.kind === KIND.TOOL_CALL);\n    const names = calls.map((e) => e.tool_name);\n    if (names.length < minRepeat * 2) continue;\n\n    for (let i = 0; i + 1 < names.length; i++) {\n      const a = names[i];\n      const b = names[i + 1];\n      if (!a || !b || a === b) continue; // 同一工具的连续使用不算\"序列\"\n      // 任一端是通用工具就不算\"可固化套路\"：任何任务都要读文件、跑命令，\n      // 「跑命令→搜网页」这种组合是任务形状，不是可复用的固定套路。\n      if (isGeneric(a) || isGeneric(b)) continue;\n      const key = [a, b].sort().join('\\u0000');\n      let rec = pairs.get(key);\n      if (!rec) {\n        rec = { from: a, to: b, count: 0, first: calls[i].locator, sessions: new Set() };\n        pairs.set(key, rec);\n      }\n      rec.count += 1;\n      rec.sessions.add(s.sessionId);\n    }\n  }\n\n  const findings = [];\n  for (const rec of pairs.values()) {\n    if (rec.count < minRepeat) continue;\n    findings.push({\n      id: 'A3',\n      title: '高频手动序列',\n      category: 'A',\n      severity: SEVERITY.LOW,\n      scope: [...rec.sessions].join(','),\n      summary:\n        `工具序列「${rec.from}↔${rec.to}」出现 ${rec.count} 次（跨 ${rec.sessions.size} 个会话），` +\n        `两端都不在通用工具清单里，可考虑固化（${criteria}）`,\n      evidence: [{ locator: rec.first, note: '该序列首次出现' }],\n      impact: `约 ${rec.count} 次固定的两步操作，可合并为一次调用或固化为技能`,\n      confidence: 0.6,\n    });\n  }\n  return { findings, note: criteria };\n}\n\n/**\n * A4 子代理开销\n * delegationDepth>0 的会话 token 占比 > 40%\n */\nfunction detectA4(ctx, opts) {\n  const threshold = opts.a4SubagentShare ?? 0.4;\n  const findings = [];\n\n  let total = 0;\n  let sub = 0;\n  const subSessions = [];\n  for (const s of ctx.scan.sessions) {\n    const t = s.events\n      .filter((e) => e.kind === KIND.ASSISTANT_MSG)\n      .reduce((n, e) => n + (e.total_tokens ?? (e.input_tokens ?? 0) + (e.output_tokens ?? 0)), 0);\n    total += t;\n    if (s.isSubagent) {\n      sub += t;\n      subSessions.push({ s, t });\n    }\n  }\n  if (total <= 0 || subSessions.length === 0) return [];\n\n  const share = sub / total;\n  if (share <= threshold) return [];\n\n  const worst = subSessions.sort((a, b) => b.t - a.t)[0];\n  findings.push({\n    id: 'A4',\n    title: '子代理开销',\n    category: 'A',\n    severity: SEVERITY.MID,\n    scope: worst.s.sessionId,\n    summary: `${subSessions.length} 个子代理会话占总 token 的 ${pct(share)}（阈值 ${(threshold * 100).toFixed(0)}%）`,\n    evidence: subSessions.slice(0, 8).map(({ s, t }) => {\n      const ev = s.events.find((e) => e.kind === KIND.ASSISTANT_MSG);\n      return { locator: ev?.locator ?? s.file, note: `子代理会话 ${num(t)} token` };\n    }),\n    impact: '子代理是按会话全额计费的，收敛使用策略可直接降本',\n    confidence: 0.75,\n  });\n  return findings;\n}\n\n/**\n * A1 / A2 资产闲置\n *\n * 需要外部数据（MCP 配置 / 已装 skill 目录），且任务书要求\"30 天窗口\"。\n * 扫描窗口不足时**明确不报**，并说明原因 —— 拿 3 天数据假装能下 30 天\n * 的结论，比不报更糟。\n *\n * @returns {{findings:Array, note?:string}}\n */\nfunction detectAssetIdle(ctx, opts) {\n  const minDays = opts.assetMinDays ?? 30;\n\n  // ⚠️ 第三轮（待优化报告 2.1）：这里原来用的是**事件时间跨度**\n  //    （max(时间) - min(时间)），不是日历跨度。反例：用户 60 天前集中用了一次、\n  //    昨天又用了一次 → 跨度 ≈60 天就过门槛，于是\"这个 skill 闲置 60 天\"，\n  //    可中间 59 天他根本没用过 Agent，这不代表 skill 闲置。\n  //    现在改成两个都算，并把\"活跃天数\"作为置信度参考：\n  //      calendarDays = 今天 - 首次会话时间（这才是\"观察窗口有多长\"）\n  //      activeDays   = 有事件的不同日历天数（这才是\"实际用了多少天\"）\n  const now = Number.isFinite(opts.now) ? opts.now : Date.now();\n  const times = ctx.scan.sessions\n    .flatMap((s) => s.events)\n    .map((e) => (e.ts ? Date.parse(e.ts) : NaN))\n    .filter((t) => Number.isFinite(t));\n  if (!times.length) {\n    return { findings: [], note: '窗口内没有带时间戳的事件，无法判断资产闲置' };\n  }\n  const firstMs = Math.min(...times);\n  const lastMs = Math.max(...times);\n  const calendarDays = Math.max(0, (now - firstMs) / 86400000);\n  const historyDays = (lastMs - firstMs) / 86400000;\n  const activeDays = new Set(\n    ctx.scan.sessions\n      .flatMap((s) => s.events)\n      .map((e) => (e.ts ? new Date(e.ts).toISOString().slice(0, 10) : null))\n      .filter(Boolean),\n  ).size;\n\n  const findings = [];\n  const dayWord = (d) => `${d.toFixed(1)} 天`;\n\n  if (calendarDays < minDays) {\n    // 报告 2.1 的第二个点：DSH 发布于 2026-08-13，新用户短期内永远够不到 30 天。\n    // 如实说明\"还差多久\"，而不是让用户以为 A2 坏了。\n    const needDays = Math.ceil(minDays - calendarDays);\n    return {\n      findings,\n      note:\n        `观察窗口只有 ${dayWord(calendarDays)}（自首次会话算起，需 ${minDays} 天）—— ` +\n        `样本不足，无法判定资产闲置；这不是\"已确认无异常\"，再过约 ${needDays} 天本项才会开始生效`,\n    };\n  }\n\n  const skills = listInstalledSkills();\n  // ⚠️ 第二轮评估 F13：DSH 的 skill 触发**不是**同名工具调用。\n  //    实测 22 个 distinct tool_name 里没有任何技能名，只有唯一的 `skill` 工具，\n  //    参数形如 {\"name\":\"agent-clinic\"}。旧代码拿 tool_name 比技能目录名，\n  //    于是 usedTools.has(name) 永不为真 → 窗口一到全部 skill 都被误报\"闲置\"。\n  const usedSkills = new Set(\n    ctx.scan.sessions.flatMap((s) =>\n      s.events.filter((e) => e.kind === KIND.TOOL_CALL && e.skill_name).map((e) => e.skill_name),\n    ),\n  );\n  // 证据：拿窗口内最早的一条事件作为\"扫描范围\"的复核锚点（旧版本这里是 []）\n  const firstEv = ctx.scan.sessions\n    .flatMap((s) => s.events)\n    .filter((e) => e.ts)\n    .sort((a, b) => Date.parse(a.ts) - Date.parse(b.ts))[0];\n  const windowNote =\n    `观察窗口 ${dayWord(calendarDays)}（首次会话起算）· 活跃 ${activeDays} 天 · ` +\n    `历史跨度 ${dayWord(historyDays)} · 起点 ${firstEv?.ts ?? '未知'}`;\n\n  for (const name of skills) {\n    if (usedSkills.has(name)) continue;\n    findings.push({\n      id: 'A2',\n      title: 'skill 闲置',\n      category: 'A',\n      severity: SEVERITY.MID,\n      // 活跃天数少 → 结论更弱，置信度如实下调\n      scope: `窗口 ${Math.floor(calendarDays)} 天（活跃 ${activeDays} 天）`,\n      summary: `已装 skill「${name}」在 ${Math.floor(calendarDays)} 天观察窗口内 0 次触发`,\n      evidence: firstEv ? [{ locator: firstEv.locator, note: `窗口起点（${windowNote}）` }] : [],\n      impact: '卸载可省启动时间与维护成本',\n      confidence: activeDays >= 5 ? 0.7 : 0.5,\n    });\n  }\n  if (findings.length === 0) {\n    return { findings, note: `已装 skill 共 ${skills.length} 个，窗口内均有触发（${windowNote}）` };\n  }\n  return { findings };\n}\n\n/** 列出已安装的 skill 名（只读目录名，不读内容） */\nfunction listInstalledSkills() {\n  const out = [];\n  // 目录来源可覆盖（`AGENT_CLINIC_SKILL_DIRS`，用平台路径分隔符分隔多个）。\n  // 为什么需要它：本项的输入一半来自会话（窗口天数），一半来自**跑测机器上装了什么** ——\n  // 于是自检与 CI 的结果取决于宿主机恰好装了哪个 skill（第三方评估 §4.2 正是这类病：\n  // 断言针对作者本机校准，换个环境就挂）。CI / 合成语料用本变量给一个确定性的 skill 目录。\n  const override = (process.env.AGENT_CLINIC_SKILL_DIRS ?? '')\n    .split(path.delimiter)\n    .map((s) => s.trim())\n    .filter(Boolean);\n  const roots = override.length\n    ? override\n    : (() => {\n        const home = process.env.HOME || process.env.USERPROFILE;\n        if (!home) return [];\n        return ['.agents/skills', '.workbuddy/skills'].map((sub) => `${home}/${sub}`);\n      })();\n  for (const dir of roots) {\n    try {\n      if (!fs.existsSync(dir)) continue;\n      for (const e of fs.readdirSync(dir, { withFileTypes: true })) {\n        if (e.isDirectory()) out.push(e.name);\n      }\n    } catch {\n      /* 目录不存在或无权限：跳过 */\n    }\n  }\n  return [...new Set(out)];\n}\n\n// ---------------------------------------------------------------------------\n// 指标注册表\n// ---------------------------------------------------------------------------\n\nexport const REGISTRY = [\n  // --- C 类：成本 ---\n  {\n    id: 'C1',\n    title: 'token 消耗过快',\n    category: 'C',\n    severity: SEVERITY.HIGH,\n    implemented: true,\n    desc: '单会话 output 超自身其他会话中位数 50%',\n    detect: detectC1,\n  },\n  {\n    id: 'C2',\n    title: '上下文膨胀',\n    category: 'C',\n    severity: SEVERITY.HIGH,\n    implemented: true,\n    desc: '末轮/首轮 input 增长 >10x 且 cacheRead <30%',\n    detect: detectC2,\n  },\n  {\n    id: 'C3',\n    title: '长会话疲劳',\n    category: 'C',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '单会话消息数 > 200',\n    detect: detectC3,\n  },\n  // --- 第三轮（待优化报告 Phase 1）：把 DSH 自己记的实测值接进来 ---\n  {\n    id: 'C5',\n    title: '压缩可观测性',\n    category: 'C',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '单会话压缩 ≥3 次，报告 DSH 实测释放量（shadowedTokenCount，非估算）',\n    detect: detectC5,\n  },\n  {\n    id: 'C6',\n    title: '工具面成本',\n    category: 'C',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '工具 schema >20000 字符（每请求重发）+ 窗口内 0 调用的工具 ≥5 个',\n    detect: detectC6,\n  },\n  {\n    id: 'C7',\n    title: '上下文注入量',\n    category: 'C',\n    severity: SEVERITY.LOW,\n    implemented: true,\n    desc: 'agent/inbox/spliced 注入 ≥20 次且 ≥100000 字符',\n    detect: detectC7,\n  },\n  // --- E 类：效率 ---\n  {\n    id: 'E1',\n    title: '死循环',\n    category: 'E',\n    severity: SEVERITY.HIGH,\n    implemented: true,\n    desc: '同工具 + 同参数 + 同错误，重复 >=3 次',\n    detect: detectE1,\n  },\n  {\n    id: 'E2',\n    title: '反复失败',\n    category: 'E',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '会话工具错误率 > 30%',\n    detect: detectE2,\n  },\n  {\n    id: 'E4',\n    title: '计划执行脱节',\n    category: 'E',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '有计划无执行（写 >=1 条计划后仍大量调用工具但 0 条完成）',\n    detect: detectE4,\n  },\n  {\n    id: 'E5',\n    title: '冗余重复调用',\n    category: 'E',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '同工具 + 同参数 + 无错误，重复 >=3 次（实测新增）',\n    detect: detectE5,\n  },\n  {\n    id: 'E3',\n    title: '工具结果过大',\n    category: 'E',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '单条 tool/result 文本超过 8192 字符（第二轮评估 F1：补记 text_len 后从\"不可实现\"变为可实现）',\n    detect: detectE3,\n  },\n  // --- N 类：风险 ---\n  {\n    id: 'N1',\n    title: '环境命令反复失败',\n    category: 'N',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '命令类调用失败 >=3 次（不要求同参数）',\n    detect: detectN1,\n  },\n  {\n    id: 'N2',\n    title: '高风险操作',\n    category: 'N',\n    severity: SEVERITY.HIGH,\n    implemented: true,\n    desc: '命令执行类工具命中高危模式（rm -rf / --force / reset --hard 等）',\n    detect: detectN2,\n  },\n  {\n    id: 'N3',\n    title: '权限审批摩擦',\n    category: 'N',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '审批请求 >=5 次，并给出等待时长与被拒（第二轮评估 F1：补记 approval/asked + decided 后变为可实现）',\n    detect: detectN3,\n  },\n  {\n    id: 'N4',\n    title: 'API 重试频繁',\n    category: 'N',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '模型请求重试 >=3 次，并给出失败码与累计退避（第二轮评估 F1：补记 llm/retry 后变为可实现）',\n    detect: detectN4,\n  },\n  // --- A 类：资产 ---\n  {\n    id: 'A2',\n    title: 'skill 闲置',\n    category: 'A',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '已装 skill 在扫描窗口内 0 次触发（需 >=30 天窗口）',\n    detect: detectAssetIdle,\n  },\n  {\n    id: 'A3',\n    title: '高频手动序列',\n    category: 'A',\n    severity: SEVERITY.LOW,\n    implemented: true,\n    desc: '非通用工具的两步序列复现 >=5 次（去镜像、跨会话合并；通用工具 = 基础集 + 从会话广度自动学习，见决策 D5）',\n    detect: detectA3,\n  },\n  {\n    id: 'A4',\n    title: '子代理开销',\n    category: 'A',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: 'delegationDepth>0 会话 token 占比 >40%',\n    detect: detectA4,\n  },\n  {\n    id: 'A5',\n    title: '辅助 LLM 开销',\n    category: 'A',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '窗口内辅助模型调用（联网检索 / 会话标题）≥20 次，给出 maxTokens 上界估算',\n    detect: detectA5,\n  },\n  // --- 决策 D4（2026-10-15）：K1/K2 从\"隐私取舍下方案未定\"变为已实现 ---\n  //   数据基础：用户文本的**加盐指纹**（正文不落盘），详见 src/privacy/fingerprints.mjs\n  {\n    id: 'K1',\n    title: '跨会话失忆',\n    category: 'K',\n    severity: SEVERITY.MID,\n    implemented: true,\n    desc: '同一用户文本指纹出现在 ≥3 个不同会话（本地加盐指纹，正文不落盘）',\n    detect: detectK1,\n  },\n  {\n    id: 'K2',\n    title: '已解决重新排查',\n    category: 'K',\n    severity: SEVERITY.LOW,\n    implemented: true,\n    desc: '同一指纹在 ≥2 个会话出现，且较晚的会话在其后有失败/重试（软信号，措辞\"疑似\"）',\n    detect: detectK2,\n  },\n  // --- M2+ 预留 ---\n  { id: 'A1', title: 'MCP 闲置', category: 'A', severity: SEVERITY.MID, implemented: true, desc: 'profile patch 里已配置 MCP 服务器，但观察窗口（≥30 天）内 0 次调用（工具名 mcp__<serverName>__*）', detect: detectA1 },\n  // --- 第二轮评估：以下三项原本被列在\"不可实现\"，实为适配层没抽，已实现并移入上方 REGISTRY ---\n  //   E3（工具结果过大）：tool/result 补记 text_len（只记长度，不留正文）\n  //   N3（权限审批摩擦）：补记 approval/asked + approval/decided（按 id 关联）\n  //   N4（API 重试频繁）：补记 llm/retry（失败码 / 重试序号 / 退避时长）\n  // I1/I2/I3（无用思考 / 反复澄清 / 不合偏好）：v4 已整体砍掉\n];\n\n/**\n * 尚未实现、且**原因需要如实说明**的指标。\n *\n * ⚠️ 第二轮评估 F1 更正了这里的定性口径：\n *    旧版写的是\"数据源在 DSH 里不存在\"（不可实现），但实测 E3/N3/N4 的数据都在日志里\n *    —— 那是适配层没抽（已修）。剩下 K1/K2 同样**不是数据源缺失**：\n *    user/message 的正文就在日志里，是适配层按隐私约束只记了长度。\n *\n * 2026-10-15 决策 D4：K1/K2 已实现（列为项已移入 REGISTRY），本数组因此为空。\n * 保留这个导出是为了报告结构稳定（\"尚未实现的维度\"这一节会如实显示\"没有\"）。\n */\nexport const UNIMPLEMENTABLE = [];\n\n/**\n * K1 跨会话失忆 / K2 已解决重新排查 —— **决策 D4（2026-10-15）实现**\n *\n * ⚠️ 这两项以前被列在\"尚未实现\"，原因写的是\"隐私取舍\"：适配层按隐私约束只记\n *    `user/message` 的 `text_len`、不留正文，所以做不了\"你是不是又在问同一个问题\"。\n *    用户拍板选了**较强的**一档：把**规范化文本指纹（加盐 sha256）写入本地快照**\n *    （`~/.agent-clinic/text-fingerprints.json`）。于是这两项从\"方案未定\"变成已实现，\n *    代价与边界都写在 src/privacy/fingerprints.mjs 里（正文不落盘、加盐、可清除、可关闭）。\n *\n * 判定口径（写在代码里，就是为了可复核）：\n *   K1：**同一指纹在 ≥3 个不同会话里出现**（默认阈值 3）。取 3 而不是 2 —— 两次\n *       提问同一件事可能是正常的追问，三次跨会话才是\"没记住\"。\n *   K2：同一指纹在 ≥2 个会话里出现，且**较晚那个会话**在该消息之后又出现了\n *       失败/重试信号（`tool/result` 且 `is_error`，或 `llm/retry`）。\n *       为什么用这个代理判据：日志里**没有**\"这件事已解决\"的显式信号，\n *       能观测到的最接近事实是\"这个问题再次被提起，而且又走进了排查（失败/重试）\"。\n *       因此 K2 措辞必须是\"疑似\"，严重度只给 LOW（约定 3）。\n *\n * 单样本不出结论（约定 4）：一个指纹只在一个会话里出现时，两个指标都不报。\n */\n\n/** 把观测按指纹分组 */\nfunction groupByHash(observations) {\n  const byHash = new Map();\n  for (const o of observations) {\n    if (!o?.hash) continue;\n    const list = byHash.get(o.hash) ?? [];\n    list.push(o);\n    byHash.set(o.hash, list);\n  }\n  return byHash;\n}\n\nconst tsKey = (o) => String(o?.ts ?? '');\n\n/** 每个会话里\"失败/重试\"信号出现的时间点 */\nfunction failureTimesBySession(scan) {\n  const map = new Map();\n  for (const s of scan?.sessions ?? []) {\n    const times = [];\n    for (const e of s.events ?? []) {\n      const failed =\n        (e.kind === KIND.TOOL_RESULT && e.is_error) || e.kind === KIND.RETRY;\n      if (failed) times.push(String(e.ts ?? ''));\n    }\n    map.set(s.sessionId, times);\n  }\n  return map;\n}\n\n/** K1/K2 共用的观测来源：优先用调用方给的（scan + 快照合并后），否则只从本次 scan 里取 */\nfunction kObservations(ctx, opts) {\n  if (Array.isArray(opts.fingerprintObservations)) return opts.fingerprintObservations;\n  const { observations } = observationsFromScan(ctx.scan);\n  if (opts.fingerprintStore) return [...observations, ...observationsFromStore(opts.fingerprintStore)];\n  return observations;\n}\n\n/** 把\"这次到底采到指纹没有\"如实写进判据说明（不静默降级） */\nfunction fingerprintNoteSuffix(opts) {\n  const parts = [];\n  if (opts.fingerprintUnavailable) parts.push(`本次未采集指纹：${opts.fingerprintUnavailable}`);\n  if (opts.fingerprintMissing) {\n    parts.push(`本次有 ${opts.fingerprintMissing} 条用户消息未参与指纹（过短或未采集）`);\n  }\n  return parts.length ? `；${parts.join('；')}` : '';\n}\n\n/**\n * A1 MCP 闲置 —— **配置驱动**指标（2026-10-15 实现）\n *\n * 为什么它长期\"排期中\"：判定需要两个输入 —— ①**配置了哪些 MCP 服务器**、\n * ②窗口内对它们的**调用次数**。本机此前 `~/.dsh` 下没有任何 MCP 配置，两个输入都拿不到，\n * 于是如实写成\"没有可判定的数据源\"，而不是拿合成数据自证。\n *\n * 2026-10-15：用户接入本地 filesystem MCP server（配置写进 profile patch），\n * 两个输入就都有了 —— A1 可以实现，并且**用真实配置验收**。\n *\n * 判定口径：\n *   - 服务器清单来自 profile patch 里 `name: '@deepseek-ai/dsh-mcp-client'`\n *     （或 `@deepseek-ai/dsh-mcp-resources`）且未被 disabled 的行，取 `config.serverName`；\n *   - 调用次数按 DSH 的**固定工具命名** `mcp__<serverName>__<rawName>` 统计\n *     （`dsh-mcp-client` README「工具命名与共存」：公开名是 (serverName, rawName) 的纯函数，\n *     重启 / HMR / 重连后保持稳定，所以按前缀统计不会漏也不会串台）；\n *   - 观察窗口与 A2 同口径：`今天 − 首次会话时间`（日历跨度）。不足 `a1MinDays`（默认 30 天）\n *     时**只报\"窗口不够，还差 N 天\"**，不下闲置结论；\n *   - 缺 `serverName` 的配置行单独报出来（配置本身有问题），不静默忽略。\n *\n * 证据用**配置文件的行号**（`<patch>#L<行>`）：这个指标的证据是\"你配置了什么\"，\n * 不是某条会话事件 —— 而 `show` 能展开任何文件（非 zstd 按明文读），所以照样可复核。\n */\nfunction detectA1(ctx, opts) {\n  const minDays = opts.a1MinDays ?? 30;\n  const patch = opts.mcpPatch ?? readProfilePatch(opts.env ?? process.env);\n  if (!patch.exists) {\n    return {\n      findings: [],\n      note:\n        `没有读到 profile patch（${patch.path ?? '未知路径'}）—— 无法判断 MCP 配置，本项不下结论。` +\n        `（测试/CI 可用 AGENT_CLINIC_PROFILE_PATCH 指定一份 patch）`,\n    };\n  }\n  const servers = mcpServersFromRows(patch.rows, { patchPath: patch.path });\n  if (servers.length === 0) {\n    return {\n      findings: [],\n      note: `已读 profile patch（${patch.path}），其中没有 MCP 服务器配置行（@deepseek-ai/dsh-mcp-client / -resources）`,\n    };\n  }\n\n  const now = Number.isFinite(opts.now) ? opts.now : Date.now();\n  const times = (ctx.scan?.sessions ?? [])\n    .flatMap((s) => s.events ?? [])\n    .map((e) => (e.ts ? Date.parse(e.ts) : NaN))\n    .filter((t) => Number.isFinite(t));\n  if (!times.length) {\n    return { findings: [], note: '窗口内没有带时间戳的事件，无法判断 MCP 是否闲置' };\n  }\n  const calendarDays = Math.max(0, (now - Math.min(...times)) / 86400000);\n  if (calendarDays < minDays) {\n    const need = Math.ceil(minDays - calendarDays);\n    return {\n      findings: [],\n      note:\n        `观察窗口只有 ${calendarDays.toFixed(1)} 天（自首次会话算起，需 ${minDays} 天）—— ` +\n        `样本不足，无法判定 MCP 闲置；再过约 ${need} 天本项才会开始生效`,\n    };\n  }\n\n  // 调用计数：mcp__<serverName>__*\n  const calls = new Map(servers.filter((s) => s.serverName).map((s) => [s.serverName, 0]));\n  for (const s of ctx.scan?.sessions ?? []) {\n    for (const e of s.events ?? []) {\n      if (e.kind !== KIND.TOOL_CALL || typeof e.tool_name !== 'string') continue;\n      const m = /^mcp__(.+?)__/.exec(e.tool_name);\n      if (!m || !calls.has(m[1])) continue;\n      calls.set(m[1], calls.get(m[1]) + 1);\n    }\n  }\n\n  const findings = [];\n  for (const s of servers) {\n    if (!s.serverName) continue;\n    if ((calls.get(s.serverName) ?? 0) > 0) continue;\n    findings.push({\n      id: 'A1',\n      title: 'MCP 闲置',\n      category: 'A',\n      severity: SEVERITY.MID,\n      scope: s.serverName,\n      summary:\n        `MCP 服务器「${s.serverName}」已配置（${s.transport ?? '未知传输'}），` +\n        `但在 ${calendarDays.toFixed(0)} 天观察窗口内 **0 次调用** —— 它的工具每次请求都随工具面重发`,\n      evidence: s.locator\n        ? [{ locator: s.locator, note: `配置行：${s.rowId}（serverName=${s.serverName}）` }]\n        : [],\n      impact: '闲置的 MCP 服务器不产生价值，只增加工具面与维护成本（工具 schema 每随请求重发）',\n      confidence: 0.8,\n    });\n  }\n\n  const misconfigured = servers.filter((s) => !s.serverName);\n  const notes = [\n    `观察窗口 ${calendarDays.toFixed(0)} 天 · 已配置 ${servers.length} 个 MCP 服务器：` +\n      servers\n        .map((s) => `${s.serverName ?? '(缺 serverName)'}=${calls.get(s.serverName) ?? 0} 次`)\n        .join('、'),\n  ];\n  if (misconfigured.length) {\n    notes.push(\n      `⚠ ${misconfigured.length} 行 MCP 配置缺少 serverName（配置本身有问题）：${misconfigured.map((s) => s.rowId).join('、')}`,\n    );\n  }\n  if (patch.overridden) notes.push('（配置路径由 AGENT_CLINIC_PROFILE_PATCH 指定）');\n  return { findings, note: notes.join('；') };\n}\n\nfunction detectK1(ctx, opts) {\n  const minSessions = opts.k1MinSessions ?? 3;\n  const observations = kObservations(ctx, opts);\n  const byHash = groupByHash(observations);\n  const findings = [];\n  let multiSession = 0;\n\n  for (const [hash, list] of byHash) {\n    const sessions = [...new Set(list.map((o) => o.session).filter(Boolean))];\n    if (sessions.length < 2) continue;\n    multiSession += 1;\n    if (sessions.length < minSessions) continue;\n    const chars = list.reduce((m, o) => Math.max(m, o.chars ?? 0), 0);\n    const sorted = list.slice().sort((a, b) => tsKey(a).localeCompare(tsKey(b)));\n    findings.push({\n      id: 'K1',\n      title: '跨会话失忆',\n      category: 'K',\n      severity: SEVERITY.MID,\n      scope: sessions.join(','),\n      summary:\n        `同一段用户文本（指纹 ${hash.slice(0, 8)}…，约 ${num(chars)} 字符）在 ${sessions.length} 个会话里出现 ` +\n        `—— 疑似同一个问题被反复提出（跨会话没有记住）`,\n      evidence: sorted\n        .slice(0, 3)\n        .map((o) => ({ locator: o.locator, note: `${o.session} · ${o.ts ?? '无时间'}` })),\n      impact: `同一个问题被解释了 ${sessions.length} 遍，上下文成本按会话数翻倍`,\n      confidence: 0.6,\n    });\n  }\n\n  const criteria =\n    `判据：同一指纹出现在 ≥${minSessions} 个不同会话（本次有 ${multiSession} 个指纹跨了 2 个以上会话）` +\n    `；文本短于 ${MIN_CHARS} 字符不生成指纹` +\n    fingerprintNoteSuffix(opts);\n  return { findings, note: criteria };\n}\n\nfunction detectK2(ctx, opts) {\n  const minSessions = opts.k2MinSessions ?? 2;\n  const observations = kObservations(ctx, opts);\n  const byHash = groupByHash(observations);\n  const failures = failureTimesBySession(ctx.scan);\n  const findings = [];\n\n  for (const [hash, list] of byHash) {\n    const sessions = [...new Set(list.map((o) => o.session).filter(Boolean))];\n    if (sessions.length < minSessions) continue;\n    // 每个会话最早一次出现（用它判断\"先解决过、后来又提\"的时间关系）\n    const firstBySession = new Map();\n    for (const o of list) {\n      if (!o.session) continue;\n      const prev = firstBySession.get(o.session);\n      if (!prev || tsKey(o) < tsKey(prev)) firstBySession.set(o.session, o);\n    }\n    const ordered = [...firstBySession.values()].sort((a, b) => tsKey(a).localeCompare(tsKey(b)));\n    const earliest = ordered[0];\n    // 时间不可比时不出结论（约定 4：宁可不出，也不猜）\n    if (!earliest || !tsKey(earliest)) continue;\n    // ⚠️ 必须检查**最早一次之后的每一个会话**，而不是只看最后一个：\n    // 三次提问时，失败/重试可能发生在中间那次（只看最后一次会把这种情况漏掉）。\n    const laterFailed = ordered\n      .slice(1)\n      .filter((o) => tsKey(o) && tsKey(o) > tsKey(earliest))\n      .filter((o) => (failures.get(o.session) ?? []).some((t) => t >= tsKey(o)));\n    if (laterFailed.length === 0) continue;\n    const later = laterFailed[0];\n    // 收紧一步：**最早那次出现之后不能就有失败** —— 否则这条更可能是\"一直在排查\"\n    // （E2/N4 已经在报），而不是\"当时看着解决了、后来又翻出来\"。\n    // 实测未收紧时合成语料里 K2 一次报 8 条（同一段文本在很多会话里都出现），\n    // 收紧后降到 1 条量级；仍是软信号，故只给 LOW + \"疑似\"。\n    const earlierFailed = (failures.get(earliest.session) ?? []).some((t) => t >= tsKey(earliest));\n    if (earlierFailed) continue;\n\n    const chars = list.reduce((m, o) => Math.max(m, o.chars ?? 0), 0);\n    findings.push({\n      id: 'K2',\n      title: '已解决重新排查',\n      category: 'K',\n      severity: SEVERITY.LOW, // 软信号（约定 3）：只给低，且措辞\"疑似\"\n      scope: `${earliest.session},${later.session}`,\n      summary:\n        `疑似\"已经解决过的事又排查了一遍\"：同一段用户文本（指纹 ${hash.slice(0, 8)}…，约 ${num(chars)} 字符）` +\n        `先出现在 ${earliest.ts?.slice(0, 10) ?? '较早'}，之后在 ${later.ts?.slice(0, 10) ?? '较晚'} 再次出现，` +\n        `且后一次之后有失败/重试信号`,\n      evidence: [\n        { locator: earliest.locator, note: `较早提出（${earliest.session}）` },\n        { locator: later.locator, note: `再次提出（${later.session}），其后出现失败/重试` },\n      ],\n      impact: '同一问题被重新排查一遍：重复的定位与试错成本',\n      confidence: 0.4,\n    });\n  }\n\n  const criteria =\n    `判据：同一指纹在 ≥${minSessions} 个会话出现，且较晚的会话在该消息之后有失败/重试信号` +\n    `（日志里没有\"已解决\"的显式信号，故这是代理判据，措辞必须保留\"疑似\"）` +\n    fingerprintNoteSuffix(opts);\n  return { findings, note: criteria };\n}\n\n/**\n * 运行诊断。\n *\n * @param {{scan:object, summary:object}} ctx\n * @param {Object} [opts]\n * @returns {{findings:Finding[], notDetected:Array, notImplemented:Array, unimplementable:Array}}\n */\nexport function runDiagnostics(ctx, opts = {}) {\n  const findings = [];\n  const notDetected = [];\n  const notImplemented = [];\n\n  for (const metric of REGISTRY) {\n    if (!metric.implemented) {\n      notImplemented.push({ id: metric.id, title: metric.title, category: metric.category });\n      continue;\n    }\n    let result = [];\n    let note = null;\n    try {\n      const raw = metric.detect(ctx, opts);\n      // detect 可直接返回数组，或返回 { findings, note }\n      if (Array.isArray(raw)) {\n        result = raw;\n      } else if (raw && typeof raw === 'object') {\n        result = Array.isArray(raw.findings) ? raw.findings : [];\n        note = typeof raw.note === 'string' ? raw.note : null;\n      }\n    } catch (e) {\n      notDetected.push({ id: metric.id, title: metric.title, note: `判定异常：${e.message}` });\n      continue;\n    }\n    if (result.length === 0) {\n      notDetected.push({ id: metric.id, title: metric.title, note });\n    } else {\n      findings.push(...result);\n    }\n  }\n\n  const order = { [SEVERITY.HIGH]: 0, [SEVERITY.MID]: 1, [SEVERITY.LOW]: 2 };\n  findings.sort((a, b) => (order[a.severity] ?? 9) - (order[b.severity] ?? 9));\n\n  return { findings, notDetected, notImplemented, unimplementable: UNIMPLEMENTABLE };\n}\n\nexport { KIND };\n"
