    {
      "path": "src/report.mjs",
      "content": "/**\n * L5 输出层 —— 体检报告\n *\n * 单一事实来源：`analyze()` 只产结构化数据，再由两个渲染器分别输出：\n *   - `buildReport()` → Markdown 文本（CLI / 模型工具用）\n *   - 客户端 `plugin/client.js` → 结构化 UI（DSH 面板用）\n *\n * 这样避免「解析 markdown 文本」这种脆弱做法，也让面板能做出真正的卡片式 UI。\n *\n * 硬性要求（任务书 §5.3 / docs/report-format.md）：\n *   1. 每个结论必须带证据定位与复核命令\n *   2. 必须列出「未检测到异常的维度」\n *   3. 必须列出「未实现的维度」—— 不假装全知\n *   4. 零对话原文；证据只给定位符，原文由 show 命令按需展开\n *\n * 2026-10-15 修正：处方不再是\"一句正确的废话\"。`analyze()` 现在会先读一次\n * 本机真实生效配置（只读），处方因此能说出「当前 12500 → 建议 6000」。\n */\n\nimport { runDiagnostics } from './diagnostics/index.mjs';\nimport { KIND } from './adapters/base.mjs';\nimport { prescribe, prescribeOne, skippedFor, tokenInventory, KIND_LABEL } from './prescriber/index.mjs';\nimport {\n  FEEDBACK_STATE,\n  feedbackEntries,\n  feedbackIds,\n  summarizeFeedback,\n} from './prescriber/feedback.mjs';\nimport { readEffectiveConfig } from './config/index.mjs';\nimport { activeCatalog, applyTranslation, searchCatalog } from './catalog/index.mjs';\nimport { searchPluginsLive } from './catalog/live.mjs';\nimport { num, pct } from './summary.mjs';\n\n/**\n * 把同一指标的多条 finding 合并成一组 —— 「同类型合并，不要重复展示」。\n *\n * 合并键是**指标 ID**：C1 在 3 个会话里命中 = 1 类问题、3 处实例；\n * A3 有 4 种工具序列 = 1 类问题、4 处实例。展开后仍能看到每一处的\n * 会话、结论与证据定位，不会因为合并而丢信息。\n *\n * @param {Array} findings 诊断层的扁平结果\n * @returns {Array} 分组（保持原始出现顺序，即严重度顺序）\n */\nexport function groupFindings(findings) {\n  const byId = new Map();\n  for (const f of findings) {\n    if (!byId.has(f.id)) byId.set(f.id, []);\n    byId.get(f.id).push(f);\n  }\n\n  const groups = [];\n  for (const [id, list] of byId) {\n    const first = list[0];\n    const sessions = [...new Set(list.map((f) => f.scope).filter(Boolean))];\n    const tools = [...new Set(list.map((f) => f.tool).filter(Boolean))];\n    const dangerPatterns = [...new Set(list.flatMap((f) => f.dangerPatterns ?? []))];\n    const repeatCount = Math.max(...list.map((f) => f.repeatCount ?? 0)) || null;\n    const severity = pickSeverity(list);\n    const headline = buildHeadline(id, list, tools);\n\n    const instances = list.map((f) => ({\n      scope: f.scope ?? null,\n      summary: f.summary,\n      impact: f.impact ?? null,\n      confidence: f.confidence ?? null,\n      evidence: (f.evidence ?? []).map((e) => ({ locator: e.locator, note: e.note ?? null })),\n    }));\n\n    // 用于出处方的\"聚合 finding\"：处方文案对着整体数字说话，\n    // 而不是只描述第一个会话（否则合并后会张冠李戴）。\n    const meta = {\n      id,\n      title: first.title,\n      category: first.category,\n      severity,\n      scope: sessions[0] ?? null,\n      summary: headline,\n      tool: tools[0] ?? null,\n      repeatCount,\n      dangerPatterns,\n      evidence: instances.flatMap((i) => i.evidence).slice(0, 12),\n      occurrenceCount: list.length,\n      sessions,\n    };\n\n    groups.push({\n      id,\n      title: first.title,\n      category: first.category,\n      severity,\n      count: list.length,\n      sessions,\n      tools,\n      summary: headline,\n      impact: sumImpact(list),\n      confidence: Math.max(...list.map((f) => f.confidence ?? 0)),\n      instances,\n      dangerPatterns,\n      meta,\n    });\n  }\n  return groups;\n}\n\nconst SEV_ORDER = { 高: 0, 中: 1, 低: 2 };\nconst pickSeverity = (list) =>\n  [...list].sort((a, b) => (SEV_ORDER[a.severity] ?? 9) - (SEV_ORDER[b.severity] ?? 9))[0].severity;\n\n/**\n * 合并后的一句话结论。\n *\n * 尽量把\"最值\"提出来（最高倍数 / 最多条数 / 涉及的序列与工具）；\n * 拿不到就用\"N 处 + 首个实例结论\"兜底 —— 不编数字。\n */\nfunction buildHeadline(id, list, tools) {\n  const n = list.length;\n  const pick = (re, idx = 1) => {\n    const nums = list.map((f) => Number((f.summary.match(re) ?? [])[idx])).filter((x) => Number.isFinite(x));\n    return nums.length ? Math.max(...nums) : null;\n  };\n\n  if (id === 'C1') {\n    // ⚠️ 第二轮评估 F12：这里原来写「远超自身基线」并把倍数重复两遍\n    //    （标题里的\"最高 N 倍\" + 冒号后又一次）。措辞与算法对齐：\n    //    基线是**同类主会话的单位请求 output 中位数**，不是会话自己的历史。\n    const max = pick(/的\\s*([\\d.]+)\\s*倍/);\n    const perReq = list\n      .slice(0, 3)\n      .map((f) => {\n        const m = f.summary.match(/单位请求 output ([\\d,.]+)/);\n        return m ? `每请求 ${m[1]} token` : null;\n      })\n      .filter(Boolean)\n      .join(' / ');\n    return (\n      `${n} 个会话单位请求 output 高于同类会话基线${max ? `（最高 ${max} 倍）` : ''}` +\n      (perReq ? `：${perReq}` : '') +\n      (n > 3 ? ` 等 ${n} 处` : '')\n    );\n  }\n  if (id === 'C3') {\n    const max = pick(/单会话\\s*(\\d+)\\s*条消息/);\n    return `${n} 个会话消息数超阈值${max ? `（最多 ${max} 条）` : ''}`;\n  }\n  if (id === 'E3') {\n    // 结论里已经带了完整数字，标题只做概括，不重复抠数字\n    return `${n} 个会话存在超大工具结果（单条 >8K 字符）`;\n  }\n  if (id === 'N3') {\n    return list[0]?.summary ?? `${n} 处审批摩擦`;\n  }\n  if (id === 'N4') {\n    return list[0]?.summary ?? `${n} 处 API 重试`;\n  }\n  if (id === 'A3') {\n    const seqs = list\n      .map((f) => (f.summary.match(/「(.+?)」出现\\s*(\\d+)\\s*次/) ?? []).slice(1))\n      .filter((x) => x.length === 2);\n    if (seqs.length) {\n      return `${seqs.length} 类可固化序列：${seqs\n        .slice(0, 3)\n        .map(([s, c]) => `${s} ${c} 次`)\n        .join('、')}${seqs.length > 3 ? ` 等 ${seqs.length} 类` : ''}`;\n    }\n  }\n  if (id === 'E5' || id === 'E1') {\n    const detail = list\n      .slice(0, 3)\n      .map((f) => `${f.tool ?? '工具'} ${f.repeatCount ?? '?'} 次`)\n      .join('、');\n    return `${n} 处${id === 'E1' ? '死循环' : '冗余重复调用'}：${detail}${n > 3 ? ` 等 ${n} 处` : ''}`;\n  }\n  if (id === 'N2') {\n    const pats = [...new Set(list.flatMap((f) => f.dangerPatterns ?? []))];\n    return `${n} 处高风险操作${pats.length ? `：命中 ${pats.join('、')}` : ''}`;\n  }\n  if (id === 'A2') {\n    const names = list.map((f) => (f.summary.match(/skill「(.+?)」/) ?? [])[1]).filter(Boolean);\n    return names.length ? `${names.length} 个 skill 长期未触发：${names.join('、')}` : `${n} 处 skill 闲置`;\n  }\n  if (tools.length > 1) {\n    return `${n} 处${list[0].title}：涉及 ${tools.slice(0, 4).join('、')}`;\n  }\n  return n > 1 ? `${n} 处${list[0].title}：${list[0].summary}` : list[0].summary;\n}\n\n/**\n * 合计影响估算。\n *\n * 只在**所有实例的单位一致**时才相加（例如都是\"约多消耗 N output token\"）；\n * 单位不同就老实不合计 —— 宁可少说，不编一个加不出来的数。\n */\nfunction sumImpact(list) {\n  const parsed = list.map((f) => {\n    const m = String(f.impact ?? '').match(/^(.*?)([\\d,]+)(.*)$/);\n    if (!m) return null;\n    return { prefix: m[1], value: Number(m[2].replace(/,/g, '')), suffix: m[3] };\n  });\n  if (!parsed.length || parsed.some((p) => !p || !Number.isFinite(p.value))) return null;\n  const suffix = parsed[0].suffix;\n  if (!parsed.every((p) => p.suffix === suffix)) return null;\n  const total = parsed.reduce((a, p) => a + p.value, 0);\n  return `${parsed[0].prefix}${total.toLocaleString('en-US')}${suffix}`;\n}\n\n/**\n * 产出结构化体检结果。\n *\n * @param {{scan:object, summary:object}} ctx\n * @param {Object} [opts]\n * @returns {Object} 结构化结果\n */\n/**\n * 辅助 LLM 调用的口径汇总（第三轮 F3）。\n *\n * 这些调用（联网检索 / 会话标题）**没有 usage 记录**，所以它们不会出现在\n * `token：input … output …` 里。用户看到的那个数字比真实开销更低 ——\n * 这里给出次数与 maxTokens 上界，并明确标注是上界。\n */\nfunction auxSummary(scan) {\n  const bySource = new Map();\n  let bound = 0;\n  const models = new Set();\n  for (const s of scan.sessions ?? []) {\n    for (const e of s.events ?? []) {\n      if (e.kind !== KIND.AUX_REQUEST) continue;\n      bySource.set(e.aux_source, (bySource.get(e.aux_source) ?? 0) + 1);\n      bound += e.aux_max_tokens ?? 0;\n      if (e.aux_model) models.add(e.aux_model);\n    }\n  }\n  return {\n    count: [...bySource.values()].reduce((a, b) => a + b, 0),\n    bySource: Object.fromEntries(bySource),\n    maxTokensBound: bound,\n    models: [...models],\n  };\n}\n\nexport function analyze(ctx, opts = {}) {\n  const g = ctx.summary.global;\n  const { findings, notDetected, notImplemented, unimplementable } = runDiagnostics(ctx, opts);\n\n  // 只读探测本机生效配置：处方据此说\"当前值 → 建议值\"\n  let config = null;\n  let configError = null;\n  try {\n    config = readEffectiveConfig(opts.env ?? process.env);\n  } catch (e) {\n    configError = e.message;\n  }\n\n  // 插件目录检索：读本地已装插件 + 用能力/关键词匹配每个问题\n  //\n  // 两条数据来源，优先级从高到低：\n  //   1. 本次联网现搜（`analyzeLive()` 传入的 opts.liveEntries）—— 最新，但同名时\n  //      让位给已审阅过的素材（下面 2、3）\n  //   2. 人工核实条目（写死在 catalog 里，人工读过）\n  //   3. 同步快照（可能过期）\n  // 现搜条目只在\"目录里没有\"时补进来，避免把人工核实过的同一条降级成未审阅版本。\n  let catalog = null;\n  let liveMeta = opts.liveMeta ?? null;\n  // 本次**生效的目录条目**：快照（含人工核实）+ 联网现搜新增。\n  // 它必须一路传到处方层，否则现搜到的插件只会出现在\"插件目录\"段，\n  // 不会出现在\"针对 C1 的处方\"里 —— 用户点了联网却拿不到现搜的处方。\n  let effectiveEntries = null;\n  try {\n    const snapshot = activeCatalog({ env: opts.env ?? process.env });\n    const snapshotNames = new Set(snapshot.entries.map((e) => e.package));\n    const liveOnly = (opts.liveEntries ?? []).filter((e) => !snapshotNames.has(e.package));\n    const entries = [...snapshot.entries, ...liveOnly.map(applyTranslation)];\n    effectiveEntries = entries.length ? entries : null;\n    catalog = searchCatalog(findings, {\n      env: opts.env ?? process.env,\n      catalog: effectiveEntries ?? undefined,\n    });\n    catalog.sources = {\n      ...(catalog.sources ?? snapshot.sources),\n      live: liveMeta\n        ? {\n            at: liveMeta.fetchedAt,\n            elapsedMs: liveMeta.elapsedMs,\n            kept: liveMeta.stats?.kept ?? 0,\n            added: liveOnly.length,\n            sent: liveMeta.sent ?? [],\n            networked: liveMeta.networked ?? false,\n            degraded: liveMeta.degraded ?? false,\n            errors: liveMeta.errors ?? [],\n          }\n        : null,\n    };\n  } catch (e) {\n    catalog = { matches: {}, installed: { installed: [], error: e.message }, catalogSize: 0, catalogVersion: null };\n  }\n\n  const rxCtx = {\n    ...ctx,\n    config,\n    installedPlugins: catalog.installed.installed ?? [],\n    // 让处方层的插件检索也看到\"本次生效的目录\"（含联网现搜条目）\n    catalog: effectiveEntries ?? undefined,\n  };\n  // M3.5 处方反馈闭环：把用户标记过的处方应用进来。\n  //   - rejected  → 不再出现在处方里（但要在报告里**说出来**是你撤掉的，不能悄悄消失）\n  //   - interested → 不隐藏，只标记出来（用户说\"感兴趣\"≠\"别再给我看\"）\n  const feedbackStore = opts.feedback ?? null;\n  const rejectedIds = new Set([\n    ...(opts.rejected ?? []),\n    ...feedbackIds(feedbackStore, FEEDBACK_STATE.REJECTED),\n  ]);\n  const interestedIdSet = new Set([\n    ...(opts.interested ?? []),\n    ...feedbackIds(feedbackStore, FEEDBACK_STATE.INTERESTED),\n  ]);\n  const rejectedList = [...rejectedIds];\n\n  // 每个问题各自挂上它的处方与插件检索命中（旧版只在末尾给全局列表，\n  // 用户看不出\"这条对应哪个问题\"，也看不到\"为什么推荐这个插件\"）。\n  // 这里存**完整处方对象**，面板展开问题时可以直接渲染成卡片。\n  // 注意：要在全局处方之前算出来 —— 全局处方受名额轮转限制，\n  // 而\"本类问题本来有多少条可给\"正好用来统计因名额未展示的条数（不静默丢弃）。\n  const perFinding = findings.map((f) => ({\n    id: f.id,\n    scope: f.scope ?? null,\n    full: prescribeOne(f, { ctx: rxCtx, rejected: rejectedList }),\n    skipped: skippedFor(f, { ctx: rxCtx }),\n  }));\n\n  const prescriptions = prescribe(findings, { ...opts, ctx: rxCtx, rejected: rejectedList });\n\n  // 反馈带来的\"撤掉\"要单列出来：只有把**不带反馈时会给出的那批**算一遍，才知道\n  // 哪几条是被反馈撤掉的（而不是本来就不对症 / 名额不够）。纯函数，已带缓存语义，开销可忽略。\n  let feedbackEffect = { removed: [], interested: [], error: null, summary: null };\n  if (feedbackStore) {\n    const rawById = new Map();\n    for (const f of findings) {\n      for (const rx of prescribeOne(f, { ctx: rxCtx })) rawById.set(rx.targetId, rx);\n    }\n    for (const g of groupFindings(findings)) {\n      for (const rx of prescribeOne(g.meta, { ctx: rxCtx })) if (!rawById.has(rx.targetId)) rawById.set(rx.targetId, rx);\n    }\n    const entries = feedbackEntries(feedbackStore);\n    feedbackEffect = {\n      removed: entries\n        .filter((e) => e.state === FEEDBACK_STATE.REJECTED && rawById.has(e.targetId))\n        .map((e) => ({ ...e, title: rawById.get(e.targetId)?.title ?? null, kindLabel: rawById.get(e.targetId)?.kindLabel ?? null })),\n      interested: entries\n        .filter((e) => e.state === FEEDBACK_STATE.INTERESTED && rawById.has(e.targetId))\n        .map((e) => ({ ...e, title: rawById.get(e.targetId)?.title ?? null, kindLabel: rawById.get(e.targetId)?.kindLabel ?? null })),\n      // 标记过、但这次体检里根本没出现的（例如对应的指标没命中）—— 也要如实说，避免\"我记的反馈去哪了\"\n      notApplicable: entries\n        .filter((e) => !rawById.has(e.targetId))\n        .map((e) => ({ ...e })),\n      error: opts.feedbackError ?? null,\n      summary: summarizeFeedback(feedbackStore),\n    };\n  }\n\n\n  // plan-2026-10-15 §3.1：名额不够时**不静默丢弃** —— 报出\"本可给出、因名额未展示\"的条数。\n  // 口径：按 targetId 去重后的候选池大小 − 实际给出的条数（同一插件命中多类问题只算一条）。\n  const rxPoolIds = new Set(perFinding.flatMap((p) => p.full.map((c) => c.targetId)));\n  const rxPoolSize = rxPoolIds.size;\n  const prescriptionsOmitted = Math.max(0, rxPoolSize - prescriptions.length);\n\n  // 省 token 开关清单：已经作为处方给出的不再重复列\n  const levers = tokenInventory({\n    ctx: rxCtx,\n    excludeIds: prescriptions.map((r) => r.targetId),\n  });\n\n  // 同类型合并：一类问题一张卡，处方对着聚合后的数字生成（不再一处一张）\n  const groups = groupFindings(findings).map((grp) => ({\n    id: grp.id,\n    title: grp.title,\n    category: grp.category,\n    severity: grp.severity,\n    count: grp.count,\n    sessions: grp.sessions,\n    tools: grp.tools,\n    summary: grp.summary,\n    impact: grp.impact,\n    confidence: grp.confidence,\n    instances: grp.instances,\n    prescriptions: prescribeOne(grp.meta, { ctx: rxCtx, rejected: rejectedList }),\n    skippedPrescriptions: skippedFor(grp.meta, { ctx: rxCtx }),\n  }));\n\n  return {\n    header: {\n      platform: 'DSH',\n      sessions: g.sessions ?? 0,\n      lines: g.lines ?? 0,\n      toolCalls: g.toolCalls ?? 0,\n      errorRate: g.errorRate ?? 0,\n      inputTokens: g.inputTokens ?? 0,\n      outputTokens: g.outputTokens ?? 0,\n      cacheReadTokens: g.cacheReadTokens ?? 0,\n      cacheWriteTokens: g.cacheWriteTokens ?? 0,\n      badFrames: g.badFrames ?? 0,\n      badLines: g.badLines ?? 0,\n      // 第三轮 F3：token 概览只统计 assistant/message 的 usage，必须写明口径；\n      // 辅助调用（联网检索 / 会话标题）**没有 usage 记录**，单独给上界估算。\n      tokenScope: 'assistant/message 的 usage',\n      // 待优化报告 §3：maxSessions 接线后，报告分母会被裁 —— 必须让读者知道\n      sessionLimit: Number.isFinite(ctx.scan?.limitedFrom)\n        ? { kept: ctx.scan.sessions.length, total: ctx.scan.limitedFrom }\n        : null,\n      aux: auxSummary(ctx.scan),\n      // 第二轮评估 F4/L7：解析失败与会话目录读不了都要能看见，\n      // 否则报告的分母可能少算会话而读者不自知\n      scanErrors: (ctx.scan.errors ?? []).map((e) => ({\n        kind: e.kind ?? 'parse',\n        file: e.file,\n        message: e.message,\n      })),\n    },\n    findings: findings.map((f) => ({\n      id: f.id,\n      title: f.title,\n      severity: f.severity,\n      category: f.category,\n      summary: f.summary,\n      scope: f.scope ?? null,\n      confidence: f.confidence,\n      impact: f.impact ?? null,\n      // 保留这两个字段：处方层要据此生成具体建议（工具名、重复次数），\n      // 丢掉它们会让行为建议退化成无信息量的通用文案\n      tool: f.tool ?? null,\n      repeatCount: f.repeatCount ?? null,\n      dangerPatterns: f.dangerPatterns ?? null,\n      evidence: (f.evidence ?? []).map((e) => ({\n        locator: e.locator,\n        note: e.note ?? null,\n      })),\n      prescriptions: perFinding.find((p) => p.id === f.id && p.scope === (f.scope ?? null))?.full ?? [],\n      // 被\"当前值已足够\"否决掉的处方，写出来是为了让用户看到\"为什么没给这条\"\n      skippedPrescriptions: perFinding.find((p) => p.id === f.id && p.scope === (f.scope ?? null))?.skipped ?? [],\n    })),\n    // 同类型合并后的分组视图（面板与报告都用它，避免一处一张卡）\n    groups,\n    notDetected: notDetected.map((d) => ({ id: d.id, title: d.title, note: d.note ?? null })),\n    notImplemented: notImplemented.map((d) => ({\n      id: d.id,\n      title: d.title,\n      // 待优化报告 §5-6：不能只写\"排期中\"就完事，要说明本机为什么还判不了\n      note:\n        d.id === 'A1'\n          ? '本机未检测到 MCP 配置 —— 不是\"MCP 都闲置\"，而是没有可判定的数据源'\n          : null,\n    })),\n    unimplementable: unimplementable.map((d) => ({ id: d.id, title: d.title, reason: d.reason })),\n    // 处方：每条都可执行（配置片段 / 命令 / 插件入口 / 设置路径 / 具体动作）\n    prescriptions,\n    // 名额轮转语义（plan-2026-10-15 §3.1）：本可给出但因全局名额未展示的条数 —— 不静默丢弃\n    prescriptionsOmitted,\n    prescriptionsPoolSize: rxPoolSize,\n    // M3.5：处方反馈的效果（哪几条是被你标记\"已拒绝\"撤掉的、哪几条标了\"感兴趣\"、\n    // 哪些标记这次没对上任何处方）。**撤掉必须写出来** —— 静默消失会让人以为建议没了。\n    feedbackEffect,\n    // 省 token 开关清单（陈列本机真实存在的旋钮，不是诊断结论）\n    levers,\n    // 插件目录检索：本地已装清单 + 命中到的插件（**按插件去重**，列全命中的指标）\n    catalog: {\n      version: catalog.catalogVersion,\n      size: catalog.catalogSize,\n      sources: catalog.sources ?? null,\n      installedCount: (catalog.installed.installed ?? []).length,\n      installed: catalog.installed.installed ?? [],\n      installedDir: catalog.installed.profileDir ?? null,\n      error: catalog.installed.error ?? null,\n      // 被\"窄领域蹭通用能力词\"规则挡掉/降权的插件 —— 如实披露，不静默丢弃\n      offDomainFiltered: (catalog.offDomainFiltered ?? []).map((o) => ({\n        package: o.package,\n        displayName: o.displayName,\n        domain: o.domain,\n        domainLabel: o.domainLabel ?? o.domain,\n        domainMatched: o.domainMatched,\n        domainVia: o.domainVia ?? null,\n        caps: o.caps,\n      })),\n      // 去重后的推荐清单：同一个插件只出现一次，findingIds 列出它命中的全部指标\n      recommendations: (catalog.recommendations ?? []).map((r) => ({\n        id: r.id,\n        package: r.package,\n        displayName: r.displayName,\n        summary: r.summary,\n        summaryLang: r.summaryLang ?? null,\n        capabilities: r.capabilities,\n        capabilityEvidence: r.capabilityEvidence,\n        repo: r.repo,\n        version: r.version,\n        install: r.install,\n        risk: r.risk,\n        origin: r.origin,\n        hasDshBundlePatch: r.hasDshBundlePatch,\n        verifiedAt: r.verifiedAt,\n        sourceVia: r.sourceVia,\n        installed: r.installed,\n        score: r.score,\n        // 热度（star / 下载量）：只用于同分排序与展示，不参与对症打分\n        heat: r.heat ?? null,\n        heatText: r.heatText ?? null,\n        kind: r.kind ?? null,\n        kindText: r.kindText ?? null,\n        findingIds: r.findingIds,\n        reasons: r.reasons,\n      })),\n      // 按 finding 分组的视图（面板里\"这个问题命中什么\"仍可用）\n      matches: Object.entries(catalog.matches ?? {}).map(([id, hits]) => ({\n        findingId: id,\n        hits: hits.map((h) => ({\n          id: h.entry.id,\n          package: h.entry.package,\n          displayName: h.entry.displayName,\n          installed: h.installed,\n          reasons: h.reasons,\n        })),\n      })),\n    },\n    // 处方所依据的本机配置快照（只含我们真正会给处方的行）\n    config: config\n      ? {\n          patchPath: config.patchPath,\n          patchExists: config.patchExists,\n          profileDir: config.profileDir,\n          rows: Object.values(config.rows).map((r) => ({\n            id: r.id,\n            name: r.name,\n            source: r.source,\n            config: r.config,\n          })),\n          warnings: config.warnings,\n        }\n      : { patchPath: null, patchExists: false, error: configError },\n    // 页脚必须如实描述本次到底有没有联网 —— 跑过 --live 就不能再写「零外发」\n    footer: liveMeta && liveMeta.networked\n      ? '证据可复核 · 会话数据全程本地 · 插件检索已联网（仅发送问题类型关键词，报告上方列出实际检索词）'\n      : '证据可复核 · 全程本地 · 零外发',\n  };\n}\n\n/**\n * 生成体检报告（Markdown 文本）\n *\n * @param {{scan:object, summary:object}} ctx\n * @param {Object} [opts]\n * @returns {string}\n */\nexport function buildReport(ctx, opts = {}) {\n  return renderReport(analyze(ctx, opts));\n}\n\n/**\n * 体检 + **联网现搜**（发现问题后当场去 npm / GitHub 找插件），再渲染 Markdown。\n *\n * 与 `buildReport()` 的唯一区别是它在诊断出 findings 之后、生成处方之前\n * 先跑一次 `searchPluginsLive()`，把现搜到的插件并进目录参与匹配。\n * 联网失败只会让报告少几条推荐（并在报告里如实写明），不会让体检失败。\n *\n * @param {{scan:object, summary:object}} ctx\n * @param {Object} [opts] 另见 `src/catalog/live.mjs` 的 LIVE_DEFAULTS\n * @returns {Promise<{text:string, live:object, data:object}>}\n */\nexport async function buildReportLive(ctx, opts = {}) {\n  const data = await analyzeLive(ctx, opts);\n  return { text: renderReport(data), live: data.live ?? null, data };\n}\n\n/**\n * 结构化版 `buildReportLive()`：只产数据，不渲染。\n * 面板（`plugin/index.js`）用这个，CLI 用 `buildReportLive()`。\n */\nexport async function analyzeLive(ctx, opts = {}) {\n  // 先同步跑一次诊断，只为拿到 findings（现搜的检索词完全由 findings 决定）\n  const dry = analyze(ctx, opts);\n  const findings = dry.findings.map((f) => ({ id: f.id, scope: f.scope ?? null }));\n  const live = await searchPluginsLive(findings, opts.liveOptions ?? {});\n  const data = analyze(ctx, { ...opts, liveEntries: live.entries, liveMeta: live });\n  return { ...data, live };\n}\n\nexport function renderReport(data) {\n  const h = data.header;\n  const out = [];\n  const push = (s = '') => out.push(s);\n\n  push(`## Agent 体检报告（平台：${h.platform} · ${h.sessions} 个会话）`);\n  push();\n  push(\n    `扫描概览：${h.sessions} 会话 / ${h.lines} 行 / ${h.toolCalls} 次工具调用 / 错误率 ${pct(h.errorRate)}`,\n  );\n  push(\n    `token（**仅主对话**：${h.tokenScope ?? 'assistant/message 的 usage'}）：` +\n      `input ${num(h.inputTokens)} · output ${num(h.outputTokens)} · cacheRead ${num(h.cacheReadTokens)}`,\n  );\n  // 第三轮 F3：把\"没算进去的那部分\"如实说出来，否则读者会以为这就是全部开销\n  if (h.aux && h.aux.count > 0) {\n    const srcText = Object.entries(h.aux.bySource ?? {})\n      .map(([k, n]) => `${k === 'web-search' ? '联网检索' : k === 'session-title' ? '会话标题' : k} ${n} 次`)\n      .join(' · ');\n    push(\n      `辅助调用（**不计入上者**，DSH 未给它们记 usage）：${srcText}，` +\n        `按各自 maxTokens 上界估算 ≤${num(h.aux.maxTokensBound)} token` +\n        `${h.aux.models?.length ? `（模型 ${h.aux.models.join('、')}）` : ''}`,\n    );\n  }\n  // 分母被裁过就说出来（否则读者以为本机只有这么几个会话）\n  if (h.sessionLimit) {\n    push(\n      `> ⚠ 本次只扫描了最近修改的 ${h.sessionLimit.kept} 个会话（共 ${h.sessionLimit.total} 个）` +\n        ` —— 由插件配置 \\`maxSessions\\` 控制`,\n    );\n  }\n  if (h.badFrames || h.badLines) {\n    push(`⚠ 数据完整性：坏帧 ${h.badFrames} / 坏行 ${h.badLines}`);\n  }\n  // 第二轮评估 L7：解析失败的会话原先只在 `scan` 里显示，报告的分母会静默少算\n  const scanErrs = h.scanErrors ?? [];\n  if (scanErrs.length) {\n    const readErrs = scanErrs.filter((e) => e.kind === 'read');\n    const parseErrs = scanErrs.filter((e) => e.kind !== 'read');\n    if (readErrs.length) {\n      push(`⚠ 有 ${readErrs.length} 个目录读不了（这部分数据没被统计到）：`);\n      for (const e of readErrs) push(`  - ${e.file}：${e.message}`);\n    }\n    if (parseErrs.length) {\n      push(`⚠ 有 ${parseErrs.length} 个会话解析失败（下面的分母少了它们）：`);\n      for (const e of parseErrs) push(`  - ${e.message}`);\n    }\n  }\n  push();\n\n  if (data.groups.length === 0) {\n    push('### 未发现问题');\n    push();\n    push('所有已实现的指标均未检测到异常。');\n    push();\n  } else {\n    // 同类型合并：一类问题一条，实例作为子条目列出（不再一处一张）\n    const total = data.groups.reduce((n, g) => n + g.count, 0);\n    push(`### 发现 ${data.groups.length} 类问题（共 ${total} 处 · 按严重度排序）`);\n    push();\n    for (const grp of data.groups) {\n      push(\n        `**[${grp.severity}] ${grp.id} ${grp.title}** —— ${grp.count} 处` +\n          (grp.count > 1 ? `（${grp.sessions.length} 个会话）` : ''),\n      );\n      push(`- 结论：${grp.summary}`);\n      if (grp.impact) push(`- 影响估算：${grp.impact}`);\n      push(`- 置信度：${grp.confidence >= 0.8 ? '高' : '中'}`);\n      for (const [i, inst] of grp.instances.entries()) {\n        const sess = String(inst.scope ?? '').replace(/^session-/, '').slice(0, 12) || '(全局)';\n        const loc = inst.evidence[0]?.locator ?? null;\n        push(`  ${i + 1}. 会话 ${sess}：${inst.summary}`);\n        if (loc) {\n          push(`     - 证据定位：${loc}`);\n          // 第二轮评估 F18：原命令是 ./run.sh show（bash-only），在 Windows/pwsh 上\n          // 用户照着粘会直接失败。给跨平台的 node 形式，run.sh 留作说明。\n          push(`     - 复核命令：node src/cli.mjs show \"${loc}\"   （等同 ./run.sh show）`);\n        }\n      }\n      push();\n    }\n  }\n\n  if (data.prescriptions.length > 0) {\n    push(`### 处方（${data.prescriptions.length} 条 · 每条都有可执行动作）`);\n    push();\n    // 名额轮转语义（plan-2026-10-15 §3.1 / 评估 §4.1）：\n    // 全局处方有名额上限，但\"本可给出\"的候选多于名额时必须如实报数，不得静默丢弃。\n    // 每类问题各自的完整处方仍在上面每张问题卡里（perFinding/groups），这里只说明全局裁剪量。\n    if (data.prescriptionsOmitted > 0) {\n      push(\n        `> 名额说明：本次共 ${data.prescriptionsPoolSize ?? '?'} 条可给处方，` +\n          `本清单按\"每类问题轮转 + 严重度顺序\"取前 ${data.prescriptions.length} 条；` +\n          `另有 **${data.prescriptionsOmitted} 条** 因名额未在此列出（各类问题卡片里的处方不受此限）。`,\n      );\n      push();\n    }\n    if (data.config?.patchPath) {\n      push(`> 配置类处方改的是这份文件（本工具只读它，不代你改）：\\`${data.config.patchPath}\\``);\n      push();\n    }\n    // M3.5：每条处方都带 targetId —— 用户可以直接拿它做反馈，不用描述\"是那条拆会话的建议\"\n    push('> 不想再看到某条？`agent-clinic rx reject <目标 ID>` 记住它（下次不再给出，并写明是你撤掉的）；恢复用 `agent-clinic rx clear`。');\n    push();\n    for (const [i, rx] of data.prescriptions.entries()) {\n      push(\n        `${i + 1}. **【${rx.kindLabel}】${rx.title}** —— 针对 ${rx.findingId}` +\n          `（目标 ID：\\`${rx.targetId}\\`${data.feedbackEffect?.interested?.some((x) => x.targetId === rx.targetId) ? ' · 你标记过「感兴趣」' : ''}）`,\n      );\n      if (rx.steps?.length) {\n        push('   - 具体怎么做：');\n        for (const [n, s] of rx.steps.entries()) push(`     ${n + 1}. ${s}`);\n      }\n      push(`   - 说明：${rx.detail.replace(/\\n/g, '\\n     ')}`);\n      if (rx.command) {\n        const isYaml = rx.action?.type === 'config';\n        push(isYaml ? '   - 改成（可整段粘进 profile patch）：' : '   - 命令：');\n        push('     ```' + (isYaml ? 'yaml' : 'bash'));\n        for (const line of String(rx.command).split('\\n')) push(`     ${line}`);\n        push('     ```');\n      }\n      push(`   - 依据：${rx.because}`);\n      if (rx.risk) push(`   - 风险提示：${rx.risk}`);\n      if (rx.verify) push(`   - 怎么确认有效：${rx.verify}`);\n      if (rx.source) push(`   - 出处：${rx.source}${rx.sourceVia ? ` · ${rx.sourceVia}` : ''}`);\n      push();\n    }\n  }\n\n  push('### 未检测到异常的维度');\n  if (data.notDetected.length === 0) {\n    push('（无）');\n  } else {\n    for (const d of data.notDetected) {\n      push(d.note ? `- ${d.id} ${d.title} —— ${d.note}` : `- ${d.id} ${d.title}`);\n    }\n  }\n  push();\n\n  if (data.levers?.length) {\n    push('### 省 token 开关清单（本机真实存在，供按需调整）');\n    push();\n    push('> 这是**工具陈列**，不是体检结论 —— 本次未触发对应指标，列出来是因为你随时可以拧它们。');\n    if (data.config?.patchPath) push(`> 配置类改的是：\\`${data.config.patchPath}\\``);\n    push();\n    for (const lv of data.levers) {\n      push(`- **【${lv.kindLabel}】${lv.title}**`);\n      push(`  - 作用：${lv.solves}`);\n      if (lv.current || lv.suggested) {\n        push(`  - 当前：${lv.current ?? '(未读到)'} → 建议：${lv.suggested ?? '按需'}`);\n      }\n      if (lv.steps?.length) {\n        push('  - 具体怎么做：');\n        for (const [n, s] of lv.steps.entries()) push(`    ${n + 1}. ${s}`);\n      }\n      if (lv.snippet) {\n        push('  - 片段：');\n        push('    ```yaml');\n        for (const line of String(lv.snippet).split('\\n')) push(`    ${line}`);\n        push('    ```');\n      }\n      if (lv.install?.gui) push(`  - 安装：${lv.install.gui}`);\n      if (lv.install?.cli) push(`  - 命令行：\\`${lv.install.cli}\\``);\n      if (lv.note) push(`  - 备注：${lv.note}`);\n      if (lv.risk) push(`  - 风险：${lv.risk}`);\n      if (lv.source) push(`  - 出处：${lv.source}`);\n    }\n    push();\n  }\n\n  if (data.catalog?.recommendations?.length) {\n    const src = data.catalog.sources;\n    push(\n      `### 插件目录检索（目录 ${data.catalog.size} 条 · 本地已装 ${data.catalog.installedCount} 个）`,\n    );\n    push();\n    if (src) {\n      const parts = [`人工核实 ${src.curated} 条`, `npm 同步 ${src.registry} 条`];\n      if (src.github) parts.push(`GitHub 核实 ${src.github} 条`);\n      push(\n        `> 目录来源：${parts.join(' + ')}` +\n          (src.snapshotAt\n            ? `（同步于 ${String(src.snapshotAt).slice(0, 10)}，\\`./run.sh catalog-sync\\` 可更新）`\n            : '（快照未同步，可跑 `./run.sh catalog-sync`）'),\n      );\n    }\n    // 联网现搜的坦白：发了什么、拿到多少、是否降级 —— 都要能复核\n    if (src?.live && src.live.networked !== false) {\n      const L = src.live;\n      push(\n        `> **本次联网现搜**：新发现 ${L.added} 条（共取回 ${L.kept} 条，耗时 ${(L.elapsedMs / 1000).toFixed(1)}s` +\n          `${L.degraded ? '，部分通道降级' : ''}）`,\n      );\n      if (L.sent?.length) push(`> 实际发出的检索词（不含任何会话内容）：\\`${L.sent.join('`、`')}\\``);\n      for (const e of L.errors ?? []) push(`> ⚠ ${e}`);\n    } else if (data.catalog.size && !src?.live) {\n      push('> 本次未联网（只读本地目录）。要\"发现问题就联网找最新插件\"：`./run.sh report --live`');\n    }\n    push('> 按「能力标签 + 关键词」检索出来的相关插件 —— 同一个插件只列一次，**装过的不再推荐**。');\n    push('> 热度（star / 下载量）只用于同分时排序与展示，**不参与对症打分**。');\n    // 被域外规则挡掉的插件要写出来：否则用户无法判断\"是真的没有对症插件\"还是\"被规则挡了\"\n    const od = data.catalog.offDomainFiltered ?? [];\n    if (od.length) {\n      push(\n        `> 已挡掉 ${od.length} 个「窄领域插件蹭通用能力词」的推荐：` +\n          od\n            .slice(0, 4)\n            .map((o) => `\\`${o.package}\\`（${o.domainLabel ?? o.domain}，丢弃 ${o.caps.join('/')}）`)\n            .join('、') +\n          (od.length > 4 ? ` 等 ${od.length} 个` : ''),\n      );\n      push('> 原因：它们的\"省 token / 降成本\"通常指自己那条流水线，不是给你的主会话省上下文。');\n    }\n    push();\n    for (const h of data.catalog.recommendations) {\n      const originLabel =\n        h.origin === 'npm-live' || h.origin === 'github-live'\n          ? ' · 本次联网现搜'\n          : h.origin === 'github'\n            ? ' · GitHub 核实'\n            : h.origin === 'npm-registry'\n              ? ' · 来自 npm 同步'\n              : ' · 人工核实';\n      push(`- **${h.displayName}**（\\`${h.package}\\`${h.version ? ` v${h.version}` : ''}${originLabel}）`);\n      if (h.heatText) push(`  - 热度：${h.heatText}`);\n      if (h.kindText === '官方内置包') {\n        push('  - 提示：这是 DSH 官方内置包，通常已随 dsh-base 挂载，一般不需要再装（可当配置参考）');\n      }\n      push(`  - 命中指标：${(h.findingIds ?? []).join(' / ')}`);\n      push(`  - 能力：${(h.capabilities ?? []).join(' / ') || '(目录未标注)'}`);\n      push(`  - 作用：${h.summary}${h.summaryLang === 'en' ? '（英文原文）' : ''}`);\n      for (const r of h.reasons) push(`  - 命中原因：${r}`);\n      if (h.install?.gui) push(`  - 安装：${h.install.gui}`);\n      if (h.install?.cli) push(`  - 命令行：\\`${h.install.cli}\\``);\n      if (h.risk) push(`  - 风险：${h.risk}`);\n      if (h.repo) push(`  - 仓库：${h.repo}`);\n    }\n    push();\n  }\n\n  if (data.notImplemented.length) {\n    push('### 未实现的维度（排期中）');\n    for (const d of data.notImplemented) {\n      // 待优化报告 §5-6：不能只写\"排期中\"就完事 —— 要说明**本机为什么还判不了**\n      push(`- ${d.id} ${d.title}${d.note ? ` —— ${d.note}` : ''}`);\n    }\n    push();\n  }\n\n  if (data.unimplementable.length) {\n    // ⚠️ 第二轮评估 F1：这里原来写「DSH 数据源缺失，非排期问题」，\n    //    但实测 E3/N3/N4 的数据一直都在日志里（已实现并移出本列表）。\n    //    剩下的 K1/K2 同样不是\"平台没有\"，而是\"隐私取舍下还没定方案\" —— 如实写。\n    push('### 尚未实现的维度（原因见下，都不是\"平台做不到\"）');\n    for (const d of data.unimplementable) push(`- ${d.id} ${d.title} —— ${d.reason}`);\n    push();\n  }\n\n  // F16：被否决的处方要写出来 —— 否则用户分不清\"被规则挡掉\"与\"根本没有这条\"。\n  // 典型例子：spill 预算被禁用时，最该给的那条建议恰好会被 skipIf 撤掉。\n  const skippedAll = [\n    ...(data.groups ?? []).flatMap((g) =>\n      (g.skippedPrescriptions ?? []).map((s) => ({ ...s, findingId: g.id })),\n    ),\n  ];\n  if (skippedAll.length) {\n    push(`### 已评估但未给出的处方（${skippedAll.length} 条）`);\n    push();\n    push('> 这些建议本可针对下面的问题，但按**你当前的配置**判断\"已经达标或不需要\" —— 列出来是为了让你能复核这个判断。');\n    push();\n    for (const s of skippedAll) {\n      const when = s.current ? `（当前：${s.current}）` : '';\n      push(`- ${s.findingId} · ${s.title}${when} —— 未给出原因：${s.reason}`);\n    }\n    push();\n  }\n\n  // M3.5 处方反馈闭环：把你标记过的反馈**写出来**。\n  // 撤掉的必须可见（否则用户以为\"这条建议没了\"），感兴趣的要标记，没对上的也要说。\n  const fx = data.feedbackEffect;\n  if (fx) {\n    if (fx.error) {\n      push('### ⚠ 处方反馈没读到');\n      push();\n      push(`- ${fx.error.message}`);\n      push('- 本次体检**没有应用你的反馈**（是\"没读到\"，不是\"你没有反馈过\"）。');\n      push();\n    }\n    if (fx.removed?.length) {\n      push(`### 已按你的反馈撤掉的处方（${fx.removed.length} 条）`);\n      push();\n      push('> 这些是你标记过 `rx reject` 的 —— 本次**没有**再作为处方给出。删掉标记：`agent-clinic rx clear`（或改成 `rx interested <目标 ID>`）。');\n      push();\n      for (const r of fx.removed) {\n        push(\n          `- ${r.kindLabel ? `【${r.kindLabel}】` : ''}${r.title ?? r.targetId}（目标 ID：\\`${r.targetId}\\`）` +\n            ` —— 标记于 ${String(r.at ?? '').slice(0, 10) || '未知日期'}${r.reason ? `：${r.reason}` : ''}`,\n        );\n      }\n      push();\n    }\n    if (fx.interested?.length) {\n      push(`### 你标记为「感兴趣」的处方（${fx.interested.length} 条）`);\n      push();\n      for (const r of fx.interested) {\n        push(`- ${r.kindLabel ? `【${r.kindLabel}】` : ''}${r.title ?? r.targetId}（目标 ID：\\`${r.targetId}\\`）`);\n      }\n      push();\n    }\n    if (fx.notApplicable?.length) {\n      push(`### 反馈里这次没对上的条目（${fx.notApplicable.length} 条）`);\n      push();\n      push('> 你标记过，但本次体检里没有出现对应的处方（可能那类问题这次没命中）—— 列出来免得你以为反馈丢了。');\n      push();\n      for (const r of fx.notApplicable) {\n        push(`- \\`${r.targetId}\\`（${r.state === 'rejected' ? '已拒绝' : '感兴趣'}）`);\n      }\n      push();\n    }\n  }\n\n  // 待优化报告 §4.2 / §4.4：同一个报告里混着三种口径（日志实测 / usage 实测 /\n  // 字符估算），不标清楚容易被当成同一可信度。这里逐项写明来源。\n  push('### 口径说明（哪项是日志实测、哪项是估算）');\n  push();\n  push('| 数据 | 口径 |');\n  push('|---|---|');\n  push('| `token：input / output / cacheRead` | **日志实测** —— `assistant/message` 的 usage，但**不含辅助调用** |');\n  push('| 辅助调用「按 maxTokens 上界估算 ≤N」 | **上界估算** —— 次数是真数，token 量是上限（每次跑满才会达到，实际通常远低于它） |');\n  push('| C5 压缩释放量 | **日志实测** —— `compaction/*` 的 `shadowedTokenCount`，DSH 自己记的 |');\n  push('| C6 工具 schema、C7 注入量的**字符数** | **日志实测**（JSON 序列化长度） |');\n  push('| 字符 → token 的换算 | **估算** —— 按 4 字符 ≈ 1 token，已在结论里逐处标注 |');\n  push('| 其余指标（次数 / 比例 / 重复次数） | **日志实测** —— 由事件计数直接得出 |');\n  push('');\n\n  // 待优化报告 §5-3：19 个指标了，只写 C1/A3/E5 用户看不懂 —— 报告也要有图例\n  const legend = new Map();\n  for (const g of data.groups ?? []) legend.set(g.id, g.title);\n  for (const n of data.notDetected ?? []) legend.set(n.id, n.title);\n  for (const f of data.findings ?? []) legend.set(f.id, f.title);\n  if (legend.size) {\n    push('### 指标图例');\n    push();\n    for (const [id, title] of [...legend.entries()].sort()) push(`- ${id} · ${title}`);\n    push();\n  }\n\n  push('---');\n  push(data.footer);\n  return `${out.join('\\n')}\\n`;\n}\n\nexport { KIND_LABEL };\n"
    },
    {
      "path": "src/prescriber/index.mjs",
      "content": "/**\n * L4 处方层 —— 问题 → 可执行处方\n *\n * 单一事实来源：`remedies.mjs`（处方目录，带出处与风险）+\n * `src/config`（本机真实生效配置）。\n *\n * 本模块负责三件事：\n *   1. **匹配**：finding 的指标 ID → 对症处方（插件 > 配置 > 命令 > 设置 > 行为）\n *   2. **落地**：把处方渲染成\"当前值 → 建议值 + 可粘贴片段\"\n *   3. **自我否决**：当前值已经不弱于建议值时，撤掉那条处方（宁可少给，不给废话）\n *\n * ⚠️ 2026-10-14 的历史纪律仍然有效：**没有对症插件就不编插件**。\n *    当时池里 caveman / Superpowers / claude-mem / deja-vu 四条经 GitHub API\n *    核实为不存在，已全部移除；池中只保留核实过的仓库。\n *\n * ⚠️ 2026-10-15 修正（本文件被重写的原因）：\n *    旧版本的 `PRESCRIPTIONS` 三条插件 `targets` 全是 `[]`，`prescribeOne`\n *    的插件分支**永远匹配不上**，于是 C1/C2 这类成本问题只能落到\"行为建议\"。\n *    用户反馈原文：\"定位到了问题但是没有给出可行的解决方案，例如 token 消耗\n *    过高，但是没有给出可以省 token 的插件推荐。\"\n *    现在每条处方都声明 targets，并且指向**本机真实存在的**开关：\n *      · 随附插件（spill / pruner / repeat-reminder / compaction）→ 出处 app.asar\n *      · 社区插件（smart-compaction / billion-context-dsh）→ 出处 npm registry\n */\n\nimport { REMEDY_KIND, RX_TYPE, KIND_LABEL, toPatchSnippet } from './types.mjs';\nimport { REMEDIES, VERIFY_VIA } from './remedies.mjs';\nimport { readEffectiveConfig, valueOf } from '../config/index.mjs';\nimport { matchPlugins, PLUGIN_CATALOG, activeCatalog } from '../catalog/index.mjs';\nimport { num } from '../summary.mjs';\n\nexport { REMEDY_KIND, RX_TYPE, KIND_LABEL };\n\n/**\n * 已核实、但**当前没有指标靶子**的插件。\n *\n * 它们现在活在插件目录（src/catalog）里，靠**能力标签 + 关键词检索**被匹配出来，\n * 不再依赖硬绑 targets。这份列表保留，是为了让\"目录里到底有哪些、什么时候核实的\"\n * 有据可查。\n */\nexport const VERIFIED_BUT_UNTARGETED = PLUGIN_CATALOG.filter((p) => !(p.targets ?? []).length).map((p) => ({\n  id: p.id,\n  name: p.package,\n  repo: p.repo,\n  solves: p.summary,\n  verifiedAt: p.source?.verifiedAt,\n}));\n\n/**\n * 已核实的插件处方池 —— 现在**由插件目录派生**（单一事实来源 src/catalog）。\n * 保留 `repo` / `verifiedAt` / `targets` 字段，便于复核与防回归。\n */\nexport const PRESCRIPTIONS = PLUGIN_CATALOG.map((p) => ({\n  id: p.id,\n  name: p.package,\n  repo: p.repo,\n  type: RX_TYPE.INSTALL,\n  targets: p.targets ?? [],\n  solves: p.summary,\n  capabilities: p.capabilities ?? [],\n  verifiedAt: p.source?.verifiedAt,\n  verifiedVia: p.source?.via,\n  install: { dsh: p.install?.cli ?? null, gui: p.install?.gui ?? null },\n  note: p.risk,\n}));\n\n// ---------------------------------------------------------------------------\n// 自证\n// ---------------------------------------------------------------------------\n\n/**\n * 校验\"处方自证\"：一条处方必须能说明它解决什么、解决哪个指标、出处在哪。\n * @returns {{ok:boolean, reason?:string}}\n */\nexport function selfJustify(prescription, problemId) {\n  if (!prescription) return { ok: false, reason: '处方为空' };\n  if (!Array.isArray(prescription.targets) || !prescription.targets.includes(problemId)) {\n    return { ok: false, reason: `处方 ${prescription.id} 未声明可解决 ${problemId}` };\n  }\n  if (!prescription.solves) return { ok: false, reason: `处方 ${prescription.id} 缺少 solves 说明，无法自证` };\n  if (!prescription.source?.package) {\n    return { ok: false, reason: `处方 ${prescription.id} 缺少出处（source），无法复核` };\n  }\n  return { ok: true };\n}\n\n// ---------------------------------------------------------------------------\n// 渲染\n// ---------------------------------------------------------------------------\n\nconst q = (v) => `'${String(v)}'`;\n\n/**\n * 构造「具体怎么做」的分步指引。\n *\n * 用户反馈：「图一虽然给出建议，但是用户不知道具体操作步骤」、\n * 「图二给出命令，命令具体在哪里输入使用给出具体的」。\n * 所以每条处方都必须能展开成一串**照着做就行**的步骤，而不是一句结论。\n *\n * 配置 / 命令 / 插件 / 设置四类在这里按 action 生成（要带上真实文件路径）；\n * 行为类由 remedies.mjs 自带 steps。\n */\nfunction buildSteps(remedy, finding, ctx, action) {\n  if (Array.isArray(remedy.steps)) return remedy.steps;\n  if (typeof remedy.steps === 'function') return remedy.steps(finding, ctx, action);\n\n  const snap = ctx.config ?? null;\n  const verify = remedy.verify\n    ? `验证：${remedy.verify}`\n    : '验证：重跑 ./run.sh report，看这条指标是否还命中。';\n\n  // --- 改配置：打开文件 → 定位 → 替换/追加 → 保存 → 生效 → 验证 ---\n  if (remedy.kind === REMEDY_KIND.CONFIG && remedy.row) {\n    const file = action?.file || '~/.dsh/profiles/<profile>/cordis.patch.yml';\n    const exists = snap?.patchExists;\n    return [\n      `用任意文本编辑器打开这个文件：${file}` +\n        (exists\n          ? ''\n          : '　—— 该文件当前不存在，按同样路径新建一个即可（目录 ~/.dsh/profiles/desktop/ 已存在）'),\n      `在文件里搜索这一行：- id: ${remedy.row.id}`,\n      '分两种情况：① 搜到了 → 用下面的 YAML 片段把它**整段替换**（profile patch 是「整体替换」这一行的 config，没变的键也要一起写进去，缩进保持 2 空格）；② 没搜到 → 把片段**追加到文件末尾**',\n      '保存文件。profile 配置默认会热重载；若行为没有变化，完全退出 Harness（从托盘退出，不是关窗口）再重新打开',\n      verify,\n    ];\n  }\n\n  // --- 插件：界面安装 → 启用 → 重启 → 验证 ---\n  if (remedy.kind === REMEDY_KIND.PLUGIN) {\n    const pkg = remedy.source?.package;\n    const steps = [\n      '打开侧边栏 → 插件 → 添加插件',\n      `在输入框里粘贴包名并回车：${pkg}`,\n      '点「安装」，装完点「立即启用」',\n      '**完全退出 Harness**（从托盘/任务栏退出，不是关窗口）后重新打开 —— 插件只在启动时装载',\n      verify,\n    ];\n    if (remedy.install?.cli) {\n      steps.push(\n        `（仅自建 profile 适用；桌面版 profile 由应用独占，只能用上面的界面安装）命令行等价写法：${remedy.install.cli}`,\n      );\n    }\n    return steps;\n  }\n\n  // --- 斜杠命令：在输入框里敲 ---\n  if (remedy.kind === REMEDY_KIND.COMMAND) {\n    return [\n      `在 Harness 会话的输入框里直接输入并回车：${remedy.command}`,\n      '注意：Agent 必须处于空闲状态，正在执行时会被拒绝',\n      '该命令不接受参数；没有可压缩的历史时它会明确告诉你',\n      verify,\n    ];\n  }\n\n  // --- 设置项：点哪里、改成什么 ---\n  if (remedy.kind === REMEDY_KIND.SETTINGS && remedy.settings) {\n    const kv = Object.entries(remedy.settings.keys).map(([k, v]) => `${k} = ${fmt(v)}`).join('、');\n    return [\n      `打开：${remedy.settings.where}`,\n      `把这几项改成：${kv}`,\n      '保存（用户值会覆盖插件自带的组合配置）',\n      verify,\n    ];\n  }\n\n  return [verify];\n}\n\n/** 找到 finding 的证据定位（第一条） */\nconst firstLocator = (f) => f?.evidence?.[0]?.locator ?? null;\n\n/**\n * 构造一条可执行的处方输出。\n *\n * `command` 字段保持向后兼容（客户端会渲染成可复制的代码块）：\n *   - config   → 可粘贴的 YAML 片段\n *   - command  → 斜杠命令本身\n *   - plugin   → CLI 安装命令\n *   - settings → 界面路径\n */\nexport function buildPrescription(remedy, finding, ctx = {}) {\n  const snap = ctx.config ?? null;\n  const base = {\n    kind: remedy.kind,\n    kindLabel: KIND_LABEL[remedy.kind] ?? remedy.kind,\n    title: remedy.title,\n    solves: remedy.solves,\n    targetId: remedy.id,\n    findingId: finding.id,\n    risk: remedy.risk ?? null,\n    verify: remedy.verify ?? null,\n    source: remedy.source\n      ? `${remedy.source.package}（${\n          remedy.source.type === 'third-party'\n            ? '社区插件'\n            : remedy.source.type === 'builtin'\n              ? '本工具生成'\n              : '随附插件'\n        }）· 核实于 ${remedy.source.verifiedAt}`\n      : null,\n    sourceDoc: remedy.source?.doc ?? null,\n    sourceVia: remedy.source?.via ?? null,\n  };\n\n  const evidence = typeof remedy.evidence === 'function' ? remedy.evidence(finding, ctx) : null;\n\n  // --- config：把\"当前值 → 建议值\"写清楚 ---\n  if (remedy.kind === REMEDY_KIND.CONFIG && remedy.row) {\n    const row = snap?.rows?.[remedy.row.id] ?? null;\n    const currentKeys = Object.keys(remedy.suggest ?? {});\n    const current = currentKeys.map((k) => `${k}=${fmt(row?.config?.[k])}`);\n    const suggest = currentKeys.map((k) => `${k}=${fmt(remedy.suggest[k])}`);\n    const origin =\n      row?.source === 'profile'\n        ? '你的 profile 已覆盖这一行'\n        : row\n          ? '随附默认值（你的 profile 未覆盖这一行）'\n          : '未能读到该行（profile 未找到）';\n\n    // ⚠️ 第二轮评估 F17：profile patch 按 id 定位、**整体替换**该行 config。\n    //    所以只写 reasoningEffort 的片段会把同一行的 provider/model **抹掉**——\n    //    实测 remedies 里曾经硬编码 provider: deepseek-account，official 用户\n    //    整段粘贴就会被静默改成 account。\n    //    现在：这类处方声明 preserveKeys，片段里把当前行的这些键原样带上\n    //    （读不到当前行时退化为随附默认值，并在 note 里说明来源）。\n    const preserve = Array.isArray(remedy.preserveKeys) ? remedy.preserveKeys : [];\n    const carried = {};\n    const carriedNote = [];\n    for (const k of preserve) {\n      const v = row?.config?.[k];\n      if (v !== undefined && v !== null) {\n        carried[k] = v;\n        carriedNote.push(`${k}=${fmt(v)}（沿用你当前的值）`);\n      } else if (remedy.shippedConfig?.[k] !== undefined) {\n        carried[k] = remedy.shippedConfig[k];\n        carriedNote.push(`${k}=${fmt(remedy.shippedConfig[k])}（随附默认，未读到你当前的值）`);\n      }\n    }\n    const nextConfig = { ...carried, ...remedy.suggest };\n\n    const snippet = remedy.row ? toPatchSnippet(remedy.row.id, nextConfig, remedy.row.name) : null;\n    const action = {\n      type: 'config',\n      file: snap?.patchPath ?? '~/.dsh/profiles/<profile>/cordis.patch.yml',\n      rowId: remedy.row.id,\n      packageName: remedy.row.name,\n      config: nextConfig,\n      snippet,\n      note:\n        'profile patch 按 id 定位、**整体替换**该行的 config，所以片段里要把这一行需要的键写全' +\n        (carriedNote.length ? `。已带上：${carriedNote.join('、')}` : ''),\n    };\n    return {\n      ...base,\n      brief: `${current.join(' · ')} → ${suggest.join(' · ')}`,\n      steps: buildSteps(remedy, finding, ctx, action),\n      detail:\n        `${remedy.solves}。\\n` +\n        `当前：${current.join(' · ')}（${origin}）\\n` +\n        `建议：${suggest.join(' · ')}` +\n        (carriedNote.length ? `\\n片段里同时带上：${carriedNote.join('、')}` : '') +\n        (evidence ? `\\n为什么是你：${evidence}` : ''),\n      command: snippet,\n      because: `它解决「${remedy.solves}」，正好对上检测到的 ${finding.id}（${finding.summary}）`,\n      action,\n    };\n  }\n\n  // --- command ---\n  if (remedy.kind === REMEDY_KIND.COMMAND) {\n    const action = { type: 'command', command: remedy.command };\n    return {\n      ...base,\n      brief: `在会话输入框里输入 ${remedy.command} 并回车`,\n      steps: buildSteps(remedy, finding, ctx, action),\n      detail: `${remedy.solves}。${evidence ? `\\n为什么是你：${evidence}` : ''}`,\n      command: remedy.command,\n      because: `它解决「${remedy.solves}」，正好对上检测到的 ${finding.id}（${finding.summary}）`,\n      action,\n    };\n  }\n\n  // --- plugin ---\n  if (remedy.kind === REMEDY_KIND.PLUGIN) {\n    const gui = remedy.install?.gui ?? null;\n    const cli = remedy.install?.cli ?? null;\n    const action = { type: 'plugin', packageName: remedy.source?.package, gui, cli };\n    return {\n      ...base,\n      brief: `装社区插件 ${remedy.source?.package}（界面：插件 → 添加插件）`,\n      steps: buildSteps(remedy, finding, ctx, action),\n      detail:\n        `${remedy.solves}。\\n` +\n        (gui ? `界面安装：${gui}\\n` : '') +\n        (remedy.source?.repo ? `仓库：${remedy.source.repo}` : '') +\n        (evidence ? `\\n为什么是你：${evidence}` : ''),\n      command: cli,\n      because: `它解决「${remedy.solves}」，正好对上检测到的 ${finding.id}（${finding.summary}）`,\n      action,\n    };\n  }\n\n  // --- settings ---\n  if (remedy.kind === REMEDY_KIND.SETTINGS && remedy.settings) {\n    const kv = Object.entries(remedy.settings.keys).map(([k, v]) => `${k} = ${fmt(v)}`).join(' · ');\n    const action = { type: 'settings', where: remedy.settings.where, keys: remedy.settings.keys };\n    return {\n      ...base,\n      brief: `${remedy.settings.where}：${kv}`,\n      steps: buildSteps(remedy, finding, ctx, action),\n      detail:\n        `${remedy.solves}。\\n` +\n        `在哪里改：${remedy.settings.where}\\n` +\n        `改成：${kv}` +\n        (remedy.settings.note ? `\\n说明：${remedy.settings.note}` : '') +\n        (evidence ? `\\n为什么是你：${evidence}` : ''),\n      command: null,\n      because: `它解决「${remedy.solves}」，正好对上检测到的 ${finding.id}（${finding.summary}）`,\n      action,\n    };\n  }\n\n  // --- behavior ---\n  const built =\n    typeof remedy.build === 'function'\n      ? remedy.build(finding, ctx)\n      : { detail: remedy.solves, because: '' };\n  const action = { type: 'behavior' };\n  return {\n    ...base,\n    // 收起时只显示这一行；展开才给完整说明与分步操作\n    brief: built.brief || firstSentence(built.detail ?? remedy.solves),\n    steps: buildSteps(remedy, finding, ctx, action),\n    detail: built.detail,\n    command: null,\n    because: built.because || `针对 ${finding.id}（${finding.summary}）`,\n    action,\n  };\n}\n\n/** 取第一句（收起态用），过长则截断 */\nfunction firstSentence(text) {\n  const s = String(text ?? '').replace(/\\s+/g, ' ').trim();\n  const m = s.match(/^.*?[。！？；]/);\n  const one = m ? m[0] : s;\n  return one.length > 72 ? `${one.slice(0, 70)}…` : one;\n}\n\nconst fmt = (v) => {\n  if (Array.isArray(v)) return `[${v.join(', ')}]`;\n  if (typeof v === 'string') return q(v);\n  if (v === undefined) return '(未设置)';\n  if (v === null) return 'null';\n  return String(v);\n};\n\n/**\n * 把一条插件目录检索结果变成处方。\n *\n * 与固定处方不同：它带 `matchedOn`（为什么推荐它），因为这是\"检索\"出来的，\n * 用户有权知道匹配依据；已安装的不再推\"安装\"，改推\"确认启用 / 检查配置\"。\n */\nexport function buildCatalogPrescription(hit, finding, ctx = {}) {\n  const { entry, installed, reasons } = hit;\n  const pseudo = {\n    id: 'catalog-' + entry.id,\n    kind: REMEDY_KIND.PLUGIN,\n    targets: [finding.id],\n    title: `${installed ? '已装' : '装'} ${entry.displayName}`,\n    solves: entry.summary,\n    install: entry.install,\n    risk: entry.risk,\n    verify: entry.verify,\n    source: {\n      type: entry.source?.type === 'third-party' ? 'third-party' : 'first-party',\n      package: entry.package,\n      repo: entry.repo,\n      doc: entry.source?.doc,\n      via: entry.source?.via,\n      verifiedAt: entry.source?.verifiedAt,\n    },\n  };\n\n  const built = buildPrescription(pseudo, finding, ctx);\n  return {\n    ...built,\n    brief: installed\n      ? `已安装 ${entry.package}（${entry.version ?? ''}）—— 确认已启用并核对配置`\n      : `${entry.summary.slice(0, 40)}…（界面：插件 → 添加插件）`,\n    matchedOn: reasons,\n    installed,\n    catalogId: entry.id,\n    capabilityTags: entry.capabilities ?? [],\n    compatibility: entry.compatibility ?? null,\n    steps: installed\n      ? [\n          '打开侧边栏 → 插件，确认这个插件处于「已启用」状态',\n          `核对版本：本地已装 ${entry.package}${entry.version ? `，目录里核实到的最新版是 ${entry.version}` : ''}`,\n          entry.repo ? `用法与配置项见仓库：${entry.repo}` : '用法见插件自身的说明页',\n          `验证：${entry.verify}`,\n        ]\n      : built.steps,\n    action: installed\n      ? { type: 'plugin', packageName: entry.package, installed: true, repo: entry.repo }\n      : built.action,\n  };\n}\n\n/** 为一个 finding 做插件目录检索（返回处方形态；**已安装的不再推荐**） */\nexport function pluginRecommendations(finding, ctx = {}) {\n  const hits = matchPlugins(finding, {\n    // ctx.catalog 是\"本次生效的目录\"（可能含**联网现搜**到的条目）——\n    // 不传就会退回本地快照，现搜到的插件将无法进入处方。\n    ...(ctx.catalog ? { catalog: ctx.catalog } : {}),\n    installed: ctx.installedPlugins ?? [],\n    limit: ctx.pluginLimit ?? 3,\n  });\n  // 用户要求：已经装了的插件不再作为\"推荐\"出现\n  return hits.filter((hit) => !hit.installed).map((hit) => buildCatalogPrescription(hit, finding, ctx));\n}\n\n// ---------------------------------------------------------------------------\n// 匹配\n// ---------------------------------------------------------------------------\n\n/**\n * 为单个 finding 生成候选处方（已按优先级排序、已剔除\"当前值已经不弱\"的）。\n *\n * @param {Object} finding\n * @param {Object} [opts] { ctx, rejected=[] }\n * @returns {Array<Object>}\n */\nexport function prescribeOne(finding, opts = {}) {\n  const ctx = opts.ctx ?? {};\n  const snap = ctx.config ?? null;\n  const rejected = new Set(opts.rejected ?? []);\n  const out = [];\n\n  const candidates = REMEDIES.filter((r) => r.targets.includes(finding.id)).sort(\n    (a, b) => (a.priority ?? 99) - (b.priority ?? 99),\n  );\n\n  for (const remedy of candidates) {\n    const check = selfJustify(remedy, finding.id);\n    if (!check.ok) continue;\n    // 当前值已经不弱于建议 → 撤掉这条，绝不为了\"有话说\"而凑数。\n    // 注意：**只有真的读到了配置快照**才做这个否决 —— 读不到配置时不该假装知道当前值。\n    const skip = snap && typeof remedy.skipIf === 'function' ? remedy.skipIf(snap, finding) : null;\n    if (skip) continue;\n    const built = buildPrescription(remedy, finding, ctx);\n    if (rejected.has(built.targetId)) continue;\n    out.push({ ...built, skipped: null });\n  }\n\n  // 插件目录检索结果也参与排序：**能动手的排在纯建议前面**\n  // （用户明确希望\"能省 token 的插件\"被建议出来，而不是被一句行为建议盖住）\n  const seenIds = new Set(out.map((r) => r.targetId));\n  for (const rx of pluginRecommendations(finding, ctx)) {\n    if (rejected.has(rx.targetId)) continue;\n    if (seenIds.has(rx.targetId)) continue;\n    seenIds.add(rx.targetId);\n    out.push(rx);\n  }\n\n  const KIND_WEIGHT = {\n    [REMEDY_KIND.CONFIG]: 0,\n    [REMEDY_KIND.COMMAND]: 0,\n    [REMEDY_KIND.SETTINGS]: 0,\n    [REMEDY_KIND.PLUGIN]: 1,\n    [REMEDY_KIND.BEHAVIOR]: 2,\n  };\n  return out\n    .map((rx, i) => ({ rx, i }))\n    .sort((a, b) => {\n      const wa = KIND_WEIGHT[a.rx.kind] ?? 3;\n      const wb = KIND_WEIGHT[b.rx.kind] ?? 3;\n      return wa - wb || a.i - b.i;\n    })\n    .map((x) => x.rx);\n}\n\n/** 被 skipIf 否决的处方（报告里可用来解释\"为什么没给这条\"） */\nexport function skippedFor(finding, opts = {}) {\n  const snap = (opts.ctx ?? {}).config ?? null;\n  const out = [];\n  if (!snap) return out; // 没读到配置就不谈\"否决\"\n  for (const remedy of REMEDIES.filter((r) => r.targets.includes(finding.id))) {\n    const skip = typeof remedy.skipIf === 'function' ? remedy.skipIf(snap, finding) : null;\n    if (!skip) continue;\n    // 把\"为什么没给\"讲清楚：带上当前值，用户才能复核这个判断\n    // （典型场景：spill 预算被禁用时最该给的建议恰好被撤掉）\n    let current = null;\n    const rowId = remedy.row?.id;\n    if (rowId && remedy.suggest && typeof remedy.suggest === 'object') {\n      const cur = snap?.rows?.[rowId]?.config ?? null;\n      if (cur) {\n        const keys = Object.keys(remedy.suggest);\n        const pairs = keys\n          .filter((k) => cur[k] !== undefined)\n          .map((k) => `${k}=${JSON.stringify(cur[k])}`);\n        if (pairs.length) current = pairs.join(', ');\n      }\n    }\n    out.push({ id: remedy.id, title: remedy.title, reason: skip, current });\n  }\n  return out;\n}\n\n/**\n * 匹配处方（跨 finding 轮转，保证每个问题都能分到额度）。\n *\n * 与旧版的区别：默认上限从 2 提到 4。旧上限加上空靶插件池，\n * 是\"看到问题却拿不到方案\"的直接原因；现在每条都指向可执行动作，\n * 仍然不放任刷屏。\n *\n * @param {string|Array} problem 问题 ID 或 finding 列表\n * @param {Object} [opts] { limit=8, rejected=[], perFinding=2, ctx }\n */\nexport function matchPrescriptions(problem, opts = {}) {\n  // 上限 8（2026-10-15 决策 D3）：每类问题 2 个名额，8 个名额 = 前 4 类问题各 2 条。\n  // 上限 6 时只覆盖得下 3 类（7 类问题抢 6 个名额），第 4 类起在全局清单里没有处方 ——\n  // 虽已如实报出\"因名额未展示 N 条\"，但覆盖率太低。8 是\"每类 2 条\"语义下最小的\n  // 扩容（每 +2 个名额多覆盖 1 类），同时报告长度仍可控。\n  const limit = opts.limit ?? 8;\n  // 每个问题默认给 2 个名额：第 1 个是确定对症的处方，第 2 个留给插件目录检索结果，\n  // 这样\"能装的插件\"不会被一句行为建议挤掉。\n  const perFinding = opts.perFinding ?? 2;\n  const ctx = opts.ctx ?? {};\n\n  const findings = Array.isArray(problem) ? problem : [{ id: String(problem), summary: '' }];\n\n  const rounds = Math.max(perFinding, 1);\n  // 每轮配额 = 总名额按轮数分摊（上取整）。\n  //\n  // 旧实现用 `out.length < limit` 直接当轮次门控：perFinding=2、limit=6 时，\n  // 第 0 轮就把 6 个名额填满 → **第 1 轮永不执行** → 每类问题的第 2 个位次\n  // 结构性丢失。插件类处方正排在那个位次（KIND_WEIGHT 里 PLUGIN 排 1），\n  // 于是「联网现搜到的对症插件」只进推荐、进不了全局处方列表。\n  // 轮配额保证每一轮都有名额，位次轮转才是真的。\n  const roundCap = Math.max(1, Math.ceil(limit / rounds));\n\n  // 同一个 finding 的候选只算一次（旧写法每轮重算，且重算结果本应一致）\n  const allCache = new Map();\n  const allFor = (f) => {\n    if (!allCache.has(f)) allCache.set(f, prescribeOne(f, { ...opts, ctx }));\n    return allCache.get(f);\n  };\n\n  const out = [];\n  const seen = new Set();\n  const tryPush = (f, rank) => {\n    const pick = allFor(f)[rank];\n    if (!pick) return false;\n    // 按**处方本身**去重：同一个插件 / 同一条配置建议只出现一次。\n    // 否则 billion-context-dsh 会因为同时命中 C1 与 C3 而被重复列出。\n    if (seen.has(pick.targetId)) return false;\n    seen.add(pick.targetId);\n    out.push(pick);\n    return true;\n  };\n\n  // 第一遍：轮转 —— 每个问题、每个位次都有机会（公平性）\n  for (let round = 0; round < rounds && out.length < limit; round++) {\n    const roundStart = out.length;\n    for (const f of findings) {\n      if (out.length >= limit || out.length - roundStart >= roundCap) break;\n      tryPush(f, round);\n    }\n  }\n\n  // 第二遍：候选取尽后若仍有名额，按位次顺序继续填满。\n  // 轮转只负责\"位次有机会\"，不该因为公平而浪费名额（旧实现贪婪填充这一点是对的）。\n  for (let round = 0; round < rounds && out.length < limit; round++) {\n    for (const f of findings) {\n      if (out.length >= limit) break;\n      tryPush(f, round);\n    }\n  }\n\n  return out;\n}\n\n/** 给一批 finding 出处方（按严重度顺序，最多 limit 条） */\nexport function prescribe(findings, opts = {}) {\n  const ctx = opts.ctx ?? {};\n  if (!ctx.config) {\n    // 未显式传入时自行读一次（CLI / 单元测试路径）\n    try {\n      ctx.config = readEffectiveConfig();\n    } catch {\n      ctx.config = null;\n    }\n  }\n  return matchPrescriptions(findings, { ...opts, ctx });\n}\n\n// ---------------------------------------------------------------------------\n// 省 token 开关清单\n// ---------------------------------------------------------------------------\n\n/** 成本类指标 */\nconst COST_IDS = ['C1', 'C2', 'C3'];\n\n/**\n * 「省 token 开关清单」——**不是问题清单**。\n *\n * 当本次体检没有触发成本类指标（例如 C2 没命中）时，用户仍然会问\n * \"我能调哪些开关省 token\"。这份清单直接列出本机真实存在的旋钮、\n * 当前值与建议值，并明确标注「本次未触发对应指标，仅供参考」——\n * 它是工具陈列，不是诊断结论，因此不违反\"禁止硬编问题\"。\n *\n * @param {Object} opts { ctx, excludeIds=[] }\n * @returns {Array<Object>}\n */\nexport function tokenInventory(opts = {}) {\n  const ctx = opts.ctx ?? {};\n  const snap = ctx.config ?? null;\n  const exclude = new Set(opts.excludeIds ?? []);\n\n  const rows = [];\n  for (const remedy of REMEDIES) {\n    if (!remedy.targets.some((t) => COST_IDS.includes(t))) continue;\n    if (remedy.kind === REMEDY_KIND.BEHAVIOR) continue; // 清单只列\"开关\"，不列行为\n    if (exclude.has(remedy.id)) continue;\n\n    const skip =\n      snap && typeof remedy.skipIf === 'function' ? remedy.skipIf(snap, { id: remedy.targets[0], summary: '' }) : null;\n    // 已经被判定为\"当前值已足够\"的开关，不进清单 —— 列出来只会说一句正确的废话\n    if (skip) continue;\n\n    if (remedy.kind === REMEDY_KIND.CONFIG && remedy.row) {\n      const row = snap?.rows?.[remedy.row.id] ?? null;\n      const action = {\n        type: 'config',\n        file: snap?.patchPath ?? '~/.dsh/profiles/<profile>/cordis.patch.yml',\n        rowId: remedy.row.id,\n      };\n      rows.push({\n        id: remedy.id,\n        kind: remedy.kind,\n        kindLabel: KIND_LABEL[remedy.kind],\n        title: remedy.title,\n        solves: remedy.solves,\n        steps: buildSteps(remedy, { id: remedy.targets[0], summary: '' }, ctx, action),\n        rowId: remedy.row.id,\n        packageName: remedy.row.name,\n        fileName: action.file,\n        current: remedy.suggest\n          ? Object.keys(remedy.suggest).map((k) => `${k}=${fmt(row?.config?.[k])}`).join(' · ')\n          : null,\n        suggested: remedy.suggest\n          ? Object.keys(remedy.suggest).map((k) => `${k}=${fmt(remedy.suggest[k])}`).join(' · ')\n          : null,\n        snippet: remedy.suggest ? toPatchSnippet(remedy.row.id, remedy.suggest, remedy.row.name) : null,\n        status: skip ? 'normal' : 'adjustable',\n        note: skip ?? null,\n        source: remedy.source ? `${remedy.source.package} · 核实于 ${remedy.source.verifiedAt}` : null,\n        risk: remedy.risk ?? null,\n      });\n      continue;\n    }\n\n    if (remedy.kind === REMEDY_KIND.PLUGIN) {\n      rows.push({\n        id: remedy.id,\n        kind: remedy.kind,\n        kindLabel: KIND_LABEL[remedy.kind],\n        title: remedy.title,\n        solves: remedy.solves,\n        steps: buildSteps(\n          remedy,\n          { id: remedy.targets[0], summary: '' },\n          ctx,\n          { type: 'plugin', packageName: remedy.source?.package },\n        ),\n        packageName: remedy.source?.package ?? null,        repo: remedy.source?.repo ?? null,\n        install: remedy.install ?? null,\n        current: '未安装',\n        suggested: '按需安装',\n        status: 'optional',\n        note: null,\n        source: remedy.source ? `${remedy.source.package} · 核实于 ${remedy.source.verifiedAt}` : null,\n        risk: remedy.risk ?? null,\n      });\n    }\n  }\n\n  // 插件目录里与「省 token / 省成本」相关的条目也进清单（含 npm / GitHub 同步进来的），\n  // 这样即使用户这次没有命中 C1/C2/C3，也能看到\"有哪些插件能省 token\"。\n  // 已安装的不列（用户要求：装过的不再显示推荐）。\n  const installedList = ctx.installedPlugins ?? [];\n  const catalogEntries = ctx.catalogEntries ?? activeCatalog().entries;\n  for (const entry of catalogEntries) {\n    const caps = entry.capabilities ?? [];\n    if (!caps.includes('token-saving') && !caps.includes('cost')) continue;\n    if (exclude.has('catalog-' + entry.id)) continue;\n    const installed = installedList.some(\n      (n) => n === entry.package || n === entry.package.replace(/^@[^/]+\\//, ''),\n    );\n    if (installed) continue;\n    const pseudo = {\n      id: 'catalog-' + entry.id,\n      kind: REMEDY_KIND.PLUGIN,\n      targets: [entry.targets?.[0] ?? 'C2'],\n      source: { package: entry.package, type: 'third-party' },\n      install: entry.install,\n    };\n    rows.push({\n      id: 'catalog-' + entry.id,\n      kind: REMEDY_KIND.PLUGIN,\n      kindLabel: KIND_LABEL[REMEDY_KIND.PLUGIN],\n      title: `装 ${entry.displayName}`,\n      solves: entry.summary,\n      steps: buildSteps(pseudo, { id: 'C2', summary: '' }, ctx, { type: 'plugin', packageName: entry.package }),\n      packageName: entry.package,\n      repo: entry.repo ?? null,\n      install: entry.install ?? null,\n      current: '未安装',\n      suggested: '按需安装',\n      status: 'optional',\n      note: null,\n      capabilityTags: caps,\n      origin: entry.origin ?? 'curated',\n      source: `${entry.package} · 核实于 ${entry.source?.verifiedAt ?? entry.source?.via ?? '—'}`,\n      risk: entry.risk ?? null,\n    });\n  }\n\n  return rows;\n}\n\nexport { valueOf, readEffectiveConfig, toPatchSnippet };\n"
    },
    {
      "path": "src/config/index.mjs",
      "content": "/**\n * L4.5 配置层 —— 只读探测本机 DSH 的「真实生效配置」\n *\n * 为什么需要这一层（2026-10-15 修正）：\n *   旧处方层只会给\"行为建议\"，因为它不知道用户当前的门槛值是多少。\n *   结果就是\"定位到了问题，但没有可行方案\"——例如报出 C2 上下文膨胀，\n *   却只说\"把长驻内容写进文件\"，而用户真正能拧的旋钮（spill 预算、\n *   工具结果剪枝阈值、自动压缩触发比例）一个都没提。\n *\n * 本层只做一件事：把「随附默认值」和「用户 profile 覆盖」合成一份\n * 当前生效值快照，让处方能说出「当前 12500 → 建议 6000」。\n *\n * 硬性约束：\n *   - **只读**：绝不写入任何 DSH 文件\n *   - **零依赖**：不引入 YAML 库，只解析我们需要的那个 YAML 子集\n *   - **不假装**：解析不了的值标成 null 并在 warnings 里说明，绝不猜\n *\n * 关于\"随附默认值\"的来源：\n *   `@deepseek-ai/dsh-base` 的 cordis.patch.yml（随包补丁层）里有这些行。\n *   它在 app.asar 内，运行期不一定可读，因此这里内置一份**带出处**的\n *   默认值表；真正的用户覆盖一律从磁盘上的 profile patch 现读。\n */\n\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\n\n// ---------------------------------------------------------------------------\n// 随附默认值（出处：@deepseek-ai/dsh-base 的 cordis.patch.yml）\n// ---------------------------------------------------------------------------\n\n\n/**\n * 我们真正会给处方的行。\n *\n * 只收录**已逐字核对过随附 bundle**的行；没核对过的宁可不收录，\n * 也不给一个\"可能不生效\"的配置建议。\n */\nexport const SHIPPED_ROWS = [\n  {\n    id: 'spill-policy',\n    name: '@deepseek-ai/dsh-spill-policy',\n    config: { maxInlineTokens: 12500 },\n    note: '超过预算的工具结果落到磁盘，内联只留首尾与文件路径',\n  },\n  {\n    id: 'tool-result-pruner',\n    name: '@deepseek-ai/dsh-compaction-tool-result-pruner',\n    config: { thresholdChars: 8192, headChars: 4096, tailChars: 1024 },\n    note: '压缩前把超大工具结果剪成头 + 尾，中段丢弃',\n  },\n  {\n    id: 'compaction-basic',\n    name: '@deepseek-ai/dsh-compaction-basic',\n    config: {},\n    note: '自动压缩后端；随附层没写 config，全部走包内默认值',\n  },\n  {\n    id: 'repeat-tool-reminder',\n    name: '@deepseek-ai/dsh-repeat-tool-reminder',\n    config: { thresholds: [3, 5, 8], argumentsPreviewChars: 500 },\n    note: '同参数重复调用到阈值时提醒模型换策略',\n  },\n  {\n    id: 'agent-default-model',\n    name: '@deepseek-ai/dsh-agent-default-model',\n    config: { provider: 'deepseek-official', model: 'deepseek-flash' },\n    note: '新会话的默认模型路由',\n  },\n  {\n    id: 'subagent',\n    name: '@deepseek-ai/dsh-subagent',\n    config: {},\n    note: '子代理委派 seam；maxDepth / maxActiveSubagents 在 Host 设置里',\n  },\n  {\n    id: 'session-title-llm',\n    name: '@deepseek-ai/dsh-session-title-first-prompt-llm',\n    config: { targetWords: 5, targetCjkCharacters: 10, maxInputBytes: 4096, maxOutputTokens: 64, timeoutMs: 60000 },\n    note: '会话标题的辅助模型请求（每次新会话一次）',\n  },\n];\n\n/** 包内默认值（README 里写死、bundle 未覆盖的那些） */\nexport const PACKAGE_DEFAULTS = {\n  'spill-policy': { maxInlineTokens: null, _note: 'README：省略 maxInlineTokens 会禁用策略' },\n  'tool-result-pruner': { thresholdChars: 8192, headChars: 4096, tailChars: 1024 },\n  'compaction-basic': {\n    thresholdRatio: 0.8,\n    headroomTokens: 65536,\n    retainRatio: 0.16,\n    maxTokens: 65536,\n    compactionRetries: 1,\n    maxOverflowRetries: 1,\n    auto: true,\n  },\n  'repeat-tool-reminder': { thresholds: [3, 5, 8], argumentsPreviewChars: 500 },\n  subagent: { maxDepth: 1, maxActiveSubagents: 8 },\n};\n\n// ---------------------------------------------------------------------------\n// 路径解析\n// ---------------------------------------------------------------------------\n\n/** 按 DSH_HOME → ~/.dsh 回退解析数据根目录 */\nexport function resolveDshHome(env = process.env) {\n  const fromEnv = env.DSH_HOME && String(env.DSH_HOME).trim();\n  if (fromEnv) return fromEnv;\n  const home = env.HOME || env.USERPROFILE || os.homedir();\n  return home ? path.join(home, '.dsh') : null;\n}\n\n/** 解析当前 profile 目录：DSH_PROFILE_DIR → DSH_PROFILE → profiles/ 下第一个 */\nexport function resolveProfileDir(env = process.env) {\n  if (env.DSH_PROFILE_DIR && String(env.DSH_PROFILE_DIR).trim()) {\n    return String(env.DSH_PROFILE_DIR).trim();\n  }\n  const home = resolveDshHome(env);\n  if (!home) return null;\n  const profilesRoot = path.join(home, 'profiles');\n  if (env.DSH_PROFILE && String(env.DSH_PROFILE).trim()) {\n    return path.join(profilesRoot, String(env.DSH_PROFILE).trim());\n  }\n  try {\n    const entries = fs.readdirSync(profilesRoot, { withFileTypes: true });\n    const dir = entries.find((e) => e.isDirectory());\n    if (dir) return path.join(profilesRoot, dir.name);\n  } catch {\n    /* 目录不存在：返回 null，由调用方标注\"未找到 profile\" */\n  }\n  return null;\n}\n\n// ---------------------------------------------------------------------------\n// 极小 YAML 子集解析\n//\n// 只需要认这几种形状（真实 profile patch 实测就是这个形状）：\n//   - id: spill-policy\n//     name: '@deepseek-ai/dsh-spill-policy'\n//     config:\n//       maxInlineTokens: 6000\n// 以及 `- insert:` 容器、`disabled: !!js \"...\"`、列表值 [3, 5, 8]。\n// 更深的嵌套（如 modelPolicies 的列表元素）一律忽略，不做假设。\n// ---------------------------------------------------------------------------\n\nconst unquote = (s) => {\n  const t = String(s).trim();\n  if ((t.startsWith(\"'\") && t.endsWith(\"'\")) || (t.startsWith('\"') && t.endsWith('\"'))) {\n    return t.slice(1, -1);\n  }\n  // 去掉行尾注释（仅当 # 前面有空格，避免切掉 URL 里的 #）\n  const i = t.search(/\\s#/);\n  return (i < 0 ? t : t.slice(0, i)).trim();\n};\n\nfunction parseScalar(raw) {\n  const t = String(raw).trim();\n  if (t === '') return null;\n  if (t.startsWith('!!js')) return { __js: unquote(t.replace(/^!!js\\s*/, '')) };\n  if (t === 'true') return true;\n  if (t === 'false') return false;\n  if (t === 'null' || t === '~') return null;\n  if (/^\\[.*\\]$/.test(t)) {\n    return t\n      .slice(1, -1)\n      .split(',')\n      .map((x) => parseScalar(x))\n      .filter((x) => x !== null);\n  }\n  if (/^-?\\d+$/.test(t)) return Number(t);\n  if (/^-?\\d*\\.\\d+$/.test(t)) return Number(t);\n  return unquote(t);\n}\n\n/**\n * 解析 profile patch 文本，返回 id 定位的行。\n *\n * @returns {{rows:Array<{id:string,name:string|null,disabled:any,config:Object}>, warnings:string[]}}\n */\nexport function parsePatch(text) {\n  const rows = [];\n  const warnings = [];\n  let cur = null;\n  let inConfig = false;\n  let configChildIndent = null;\n\n  const lines = String(text ?? '').split(/\\r?\\n/);\n  for (let idx = 0; idx < lines.length; idx += 1) {\n    const raw = lines[idx];\n    if (!raw.trim() || raw.trim().startsWith('#')) continue;\n    const indent = raw.length - raw.trimStart().length;\n    const trimmed = raw.trim();\n\n    const item = /^-\\s*(.*)$/.exec(trimmed);\n    if (item) {\n      const rest = item[1];\n      const kv = /^([A-Za-z0-9_.-]+)\\s*:\\s*(.*)$/.exec(rest);\n      inConfig = false;\n      configChildIndent = null;\n      if (kv && kv[1] !== 'insert') {\n        const key = kv[1];\n        const val = kv[2];\n        if (key === 'id' && indent <= 6 && !val.startsWith('!')) {\n          // line：该行在 patch 文件里的 1-based 行号 —— 用来给\"配置类\"结论做证据定位\n          // （A1「MCP 闲置」的证据就是配置本身，不是某条会话事件）\n          cur = { id: unquote(val), name: null, disabled: null, config: {}, line: idx + 1 };\n          rows.push(cur);\n          continue;\n        }\n      }\n      // `- insert:` 容器或列表元素：不作为行处理\n      if (kv && kv[1] === 'insert') cur = null;\n      continue;\n    }\n\n    if (!cur) continue;\n    const kv = /^([A-Za-z0-9_.-]+)\\s*:\\s*(.*)$/.exec(trimmed);\n    if (!kv) continue;\n    const key = kv[1];\n    const val = kv[2];\n\n    if (key === 'id') {\n      cur.id = unquote(val);\n      inConfig = false;\n      continue;\n    }\n    if (key === 'name') {\n      cur.name = unquote(val);\n      inConfig = false;\n      continue;\n    }\n    if (key === 'disabled') {\n      cur.disabled = parseScalar(val);\n      inConfig = false;\n      continue;\n    }\n    if (key === 'config') {\n      if (val && val !== '{}') {\n        warnings.push(`行 ${cur.id} 的 config 不是映射，已忽略：${val}`);\n        inConfig = false;\n      } else {\n        inConfig = true;\n        configChildIndent = null;\n      }\n      continue;\n    }\n    if (inConfig) {\n      if (configChildIndent === null) configChildIndent = indent;\n      if (indent !== configChildIndent) continue; // 更深层（列表元素等）忽略\n      cur.config[key] = parseScalar(val);\n    }\n  }\n\n  return { rows, warnings };\n}\n\n// ---------------------------------------------------------------------------\n// 生效配置快照\n// ---------------------------------------------------------------------------\n\n/**\n * 读取用户 profile patch（只读；不存在不算错）。\n *\n * 路径可被 `AGENT_CLINIC_PROFILE_PATCH` 覆盖 —— 为了自检/CI 能在**确定性输入**上\n * 断言 A1（MCP 闲置）这类\"配置驱动\"的指标：干净 runner 上没有 profile 目录，\n * 真读宿主只会得到\"没配置\"，覆盖不足就会假红（与 `AGENT_CLINIC_SKILL_DIRS` 同一套路）。\n */\nexport function readProfilePatch(env = process.env) {\n  const dir = resolveProfileDir(env);\n  const override = env?.AGENT_CLINIC_PROFILE_PATCH ? String(env.AGENT_CLINIC_PROFILE_PATCH) : null;\n  const file = override ?? (dir ? path.join(dir, 'cordis.patch.yml') : null);\n  if (!file) {\n    return { path: null, exists: false, rows: [], warnings: ['未找到 profile 目录（DSH_HOME/profiles）'], profileDir: dir };\n  }\n  try {\n    const text = fs.readFileSync(file, 'utf8');\n    const { rows, warnings } = parsePatch(text);\n    return {\n      path: file,\n      exists: true,\n      rows,\n      warnings,\n      profileDir: dir,\n      overridden: Boolean(override),\n    };\n  } catch (e) {\n    return {\n      path: file,\n      exists: false,\n      rows: [],\n      warnings: [`读取失败：${e.message}`],\n      profileDir: dir,\n      overridden: Boolean(override),\n    };\n  }\n}\n\n/** 从 patch 行里挑出 MCP 服务器配置（A1 用） */\nexport function mcpServersFromRows(rows, { patchPath = null } = {}) {\n  const MC = {\n    '@deepseek-ai/dsh-mcp-client': 'client',\n    '@deepseek-ai/dsh-mcp-resources': 'resources',\n  };\n  return (rows ?? [])\n    .filter((r) => MC[r.name] && r.disabled !== true)\n    .map((r) => ({\n      rowId: r.id,\n      plugin: r.name,\n      kind: MC[r.name],\n      serverName: r.config?.serverName ?? null,\n      transport: r.config?.transport ?? null,\n      command: r.config?.command ?? null,\n      url: r.config?.url ?? null,\n      toolTimeoutMs: r.config?.toolCallTimeoutMs ?? null,\n      locator: patchPath && Number.isInteger(r.line) ? `${patchPath}#L${r.line}` : null,\n      line: r.line ?? null,\n    }));\n}\n\n/**\n * 合成「当前生效配置」快照。\n *\n * 语义（与随附 bundle 头部注释一致）：profile patch 按 id 定位，\n * **整体替换该行的 config**（不是逐键合并），最后写入者胜出。\n *\n * @returns {{patchPath:string|null, patchExists:boolean, warnings:string[], rows:Object}}\n */\nexport function readEffectiveConfig(env = process.env) {\n  const patch = readProfilePatch(env);\n  const patchRows = new Map();\n  for (const r of patch.rows) patchRows.set(r.id, r);\n\n  const rows = {};\n  for (const shipped of SHIPPED_ROWS) {\n    const override = patchRows.get(shipped.id);\n    const pkgDefaults = PACKAGE_DEFAULTS[shipped.id] ?? {};\n    // 生效值优先级：profile 覆盖 > 随附 bundle config > 包内默认值\n    const effective = {};\n    for (const [k, v] of Object.entries(pkgDefaults)) if (!k.startsWith('_')) effective[k] = v;\n    Object.assign(effective, shipped.config);\n    let source = 'bundle-default';\n    if (override) {\n      // 整体替换语义：覆盖行的 config 即最终 config（未写的键回落到包内默认）\n      const replaced = {};\n      for (const [k, v] of Object.entries(pkgDefaults)) if (!k.startsWith('_')) replaced[k] = v;\n      Object.assign(replaced, override.config);\n      for (const k of Object.keys(effective)) delete effective[k];\n      Object.assign(effective, replaced);\n      source = 'profile';\n    }\n    rows[shipped.id] = {\n      id: shipped.id,\n      name: shipped.name,\n      note: shipped.note,\n      config: effective,\n      bundleConfig: shipped.config,\n      profileConfig: override ? override.config : null,\n      source,\n      disabled: override?.disabled ?? null,\n    };\n  }\n\n  return {\n    patchPath: patch.path,\n    patchExists: patch.exists,\n    profileDir: patch.profileDir,\n    warnings: patch.warnings,\n    rows,\n  };\n}\n\n/** 取某行的某个键（找不到返回 undefined） */\nexport function valueOf(snapshot, rowId, key) {\n  return snapshot?.rows?.[rowId]?.config?.[key];\n}\n\n/** 生成一段可直接粘进 profile patch 的 YAML（含 id/name/config 三要素） */\nexport function toPatchSnippet(rowId, config, name) {\n  const lines = [`- id: ${rowId}`, `  name: '${name}'`, '  config:'];\n  for (const [k, v] of Object.entries(config ?? {})) {\n    lines.push(`    ${k}: ${formatScalar(v)}`);\n  }\n  return lines.join('\\n');\n}\n\n/** YAML 标量渲染（只处理我们目录里出现过的类型） */\nexport function formatScalar(v) {\n  if (Array.isArray(v)) return `[${v.map((x) => formatScalar(x)).join(', ')}]`;\n  if (typeof v === 'boolean' || typeof v === 'number') return String(v);\n  if (v === null || v === undefined) return 'null';\n  return `'${String(v)}'`;\n}\n"
