      "path": "src/privacy/fingerprints.mjs",
      "content": "/**\n * 用户文本指纹 —— K1（跨会话失忆）/ K2（已解决重新排查）的数据基础\n *\n * 2026-10-15 决策 D4：用户选了「指纹写入本地快照」这个较强的一档。\n *\n * 【隐私边界，必须逐条说清】\n *   1. 会话文件**只读**：本模块从不写 DSH 的会话数据。\n *   2. 正文**不落盘、不进报告、不进事件**：解析时当场规范化 → 加盐 sha256 →只留\n *      32 位十六进制指纹。任何地方都拿不回原文。\n *   3. 指纹仍带隐私含义：对**已知候选文本**（比如\"你是不是问过 '帮我看看构建失败'\"），\n *      持有快照文件的人可以逐条试算比对。加盐（每台机器一份随机盐）让**预先算好的**\n *      字典/彩虹表失效，也让不同机器的快照之间无法互相比对。\n *   4. 因此这是**本机、可清除**的能力：路径 `~/.agent-clinic/text-fingerprints.json`，\n *      `agent-clinic fingerprints` 可查看统计，`--clear` 可删除；\n *      环境变量 `AGENT_CLINIC_NO_FINGERPRINT_STORE=1` 可整体关闭（关闭后 K1/K2 会\n *      如实说明\"本次未采集指纹\"，而不是假装没问题）。\n *   5. 太短的文本（< MIN_CHARS）**不生成指纹**：既避免\"继续 / 好的\"这类噪音误报，\n *      也让指纹集合不含无意义条目。\n */\n\nimport crypto from 'node:crypto';\nimport fs from 'node:fs';\nimport os from 'node:os';\nimport path from 'node:path';\n\n/** 快照目录（与插件目录快照 catalog.snapshot.json 同目录） */\nexport const STORE_DIR = path.join(os.homedir(), '.agent-clinic');\nexport const STORE_PATH = path.join(STORE_DIR, 'text-fingerprints.json');\nexport const STORE_VERSION = 1;\n/** 短于这个字符数的用户文本不生成指纹（防噪音误报） */\nexport const MIN_CHARS = 12;\n/** 每个指纹最多保留多少条观测（跨会话长期比对够用，同时给文件设上界） */\nexport const MAX_OBS_PER_HASH = 20;\n/** 最多保留多少个不同指纹（超出按最近一次出现时间淘汰） */\nexport const MAX_HASHES = 5000;\n\n/** 关闭开关：设了就完全不采集、不读、不写 */\nexport function fingerprintsDisabled(env = process.env) {\n  return env.AGENT_CLINIC_NO_FINGERPRINT_STORE === '1';\n}\n\n// ---------------------------------------------------------------------------\n// 盐：进程级，扫面前设置一次（适配层要给事件算指纹）\n// ---------------------------------------------------------------------------\n\nlet activeSalt = null;\n\n/** @param {string|null} salt */\nexport function setActiveSalt(salt) {\n  activeSalt = typeof salt === 'string' && salt ? salt : null;\n}\n\nexport function getActiveSalt() {\n  return activeSalt;\n}\n\nexport function makeSalt() {\n  return crypto.randomBytes(16).toString('hex');\n}\n\n// ---------------------------------------------------------------------------\n// 规范化 + 指纹\n// ---------------------------------------------------------------------------\n\n/**\n * 规范化用户文本：去零宽字符、NFC、压缩空白、小写。\n * 目的：让\"同一个问题\"的排版差异（多打一个空格、换个大小写）不会变成两个指纹。\n */\nexport function normalizeText(text) {\n  return String(text ?? '')\n    .replace(/[\\u200B-\\u200D\\uFEFF]/g, '')\n    .normalize('NFC')\n    .trim()\n    .replace(/\\s+/g, ' ')\n    .toLowerCase();\n}\n\n/**\n * @param {string} salt\n * @param {string} text 用户文本\n * @returns {{hash:string, chars:number}|null} 文本太短或没有盐时返回 null（不假装有指纹）\n */\nexport function fingerprintOf(salt, text) {\n  const n = normalizeText(text);\n  if (!salt || n.length < MIN_CHARS) return null;\n  const hash = crypto\n    .createHash('sha256')\n    .update(`${salt}\\u0000${n}`)\n    .digest('hex')\n    .slice(0, 32);\n  return { hash, chars: n.length };\n}\n\n/** 从 content 块数组里拼出纯文本（只用于**当场**算指纹，不返回给上层） */\nexport function textOfContent(blocks, type = 'text') {\n  if (!Array.isArray(blocks)) return '';\n  const parts = [];\n  for (const b of blocks) {\n    if (b && b.type === type && typeof b.text === 'string') parts.push(b.text);\n  }\n  return parts.join('\\n');\n}\n\n// ---------------------------------------------------------------------------\n// 快照读写\n// ---------------------------------------------------------------------------\n\n/** @returns {{store:object|null, error:{code:string|null,message:string}|null, created:boolean}} */\nexport function loadStore({ path: file = STORE_PATH } = {}) {\n  let raw;\n  try {\n    raw = fs.readFileSync(file, 'utf8');\n  } catch (e) {\n    // 「还没有快照」的两种表现，都必须当成正常：\n    //   ENOENT  —— 文件不存在（Windows / 首次运行）\n    //   ENOTDIR —— 路径的某一级不是目录（Linux/macOS 上读 <文件>/sub/store.json 会这样报）\n    // ⚠️ 这是 CI 的跨平台 matrix 抓出来的真实差异：同一段\"故意写不进去\"的构造，\n    //    Windows 报 ENOENT 走到 save 阶段，Linux 报 ENOTDIR 被当成\"读不出来\"，\n    //    于是\"写盘失败 ≠ 没判定\"那条断言在 Linux 上假红。\n    if (e?.code === 'ENOENT' || e?.code === 'ENOTDIR') {\n      // 没同步过：正常，用新盐建一份空快照（**不落盘**，等真正有观测再写）\n      return {\n        store: { version: STORE_VERSION, salt: makeSalt(), createdAt: null, updatedAt: null, observations: {} },\n        error: null,\n        created: true,\n      };\n    }\n    return { store: null, error: { code: e?.code ?? null, message: e?.message ?? String(e) }, created: false };\n  }\n  try {\n    const parsed = JSON.parse(raw);\n    if (!parsed || typeof parsed !== 'object' || typeof parsed.salt !== 'string' || !parsed.salt) {\n      return {\n        store: null,\n        error: { code: null, message: '快照格式不认识（缺 salt）—— 可删除该文件后重跑' },\n        created: false,\n      };\n    }\n    if (!parsed.observations || typeof parsed.observations !== 'object') parsed.observations = {};\n    return { store: { ...parsed, version: parsed.version ?? STORE_VERSION }, error: null, created: false };\n  } catch (e) {\n    return { store: null, error: { code: null, message: `快照不是合法 JSON：${e.message}` }, created: false };\n  }\n}\n\n/** @returns {{ok:boolean, error:{code:string|null,message:string}|null}} */\nexport function saveStore(store, { path: file = STORE_PATH } = {}) {\n  try {\n    fs.mkdirSync(path.dirname(file), { recursive: true });\n    // 只写我们认识的字段，避免把调用方的临时对象整包落盘\n    const payload = {\n      version: STORE_VERSION,\n      salt: store.salt,\n      createdAt: store.createdAt ?? new Date().toISOString(),\n      updatedAt: new Date().toISOString(),\n      observations: store.observations ?? {},\n    };\n    fs.writeFileSync(file, `${JSON.stringify(payload, null, 2)}\\n`, 'utf8');\n    return { ok: true, error: null };\n  } catch (e) {\n    return { ok: false, error: { code: e?.code ?? null, message: e?.message ?? String(e) } };\n  }\n}\n\nexport function clearStore({ path: file = STORE_PATH } = {}) {\n  try {\n    fs.rmSync(file, { force: true });\n    return { ok: true, error: null };\n  } catch (e) {\n    return { ok: false, error: { code: e?.code ?? null, message: e?.message ?? String(e) } };\n  }\n}\n\n// ---------------------------------------------------------------------------\n// 观测：从 scan 收集，与快照合并\n// ---------------------------------------------------------------------------\n\n/**\n * 从扫描结果里收集用户文本指纹观测。\n *\n * 事件上的 `text_hash` 由适配层在解析时算好（正文不落盘）。\n * 没有 `text_hash`（未设置盐 / 文本过短 / 旧数据）的事件**不会被计入** ——\n * 上层据 `missing` 判断\"本次到底采到没有\"，并如实说明。\n *\n * @param {{sessions:Array}} scan\n * @returns {{observations:Array<{hash:string,session:string,ts:string|null,chars:number,locator:string}>, missing:number}}\n */\nexport function observationsFromScan(scan) {\n  const observations = [];\n  let missing = 0;\n  for (const s of scan?.sessions ?? []) {\n    for (const e of s.events ?? []) {\n      if (e.kind !== 'user_msg') continue;\n      if (!e.text_hash) {\n        missing += 1;\n        continue;\n      }\n      observations.push({\n        hash: e.text_hash,\n        session: e.session_id ?? s.sessionId,\n        ts: e.ts ?? null,\n        chars: e.text_len ?? 0,\n        locator: e.locator,\n      });\n    }\n  }\n  return { observations, missing };\n}\n\n/**\n * 把观测合并进快照（按 hash → 观测列表，去重 session+ts，设上界）。\n *\n * @returns {{store:object, added:number}}\n */\nexport function mergeObservations(store, observations) {\n  const obs = store.observations ?? (store.observations = {});\n  let added = 0;\n  for (const o of observations) {\n    const list = obs[o.hash] ?? (obs[o.hash] = []);\n    const dup = list.some((x) => x.session === o.session && x.ts === o.ts);\n    if (dup) continue;\n    list.push({ session: o.session, ts: o.ts, chars: o.chars, locator: o.locator });\n    added += 1;\n    // 同一指纹只留最近 MAX_OBS_PER_HASH 条（按时间排序后裁掉最旧的）\n    if (list.length > MAX_OBS_PER_HASH) {\n      list.sort((a, b) => String(a.ts ?? '').localeCompare(String(b.ts ?? '')));\n      list.splice(0, list.length - MAX_OBS_PER_HASH);\n    }\n  }\n  // 整体上界：超出就淘汰\"最近一次出现最早\"的指纹\n  const hashes = Object.keys(obs);\n  if (hashes.length > MAX_HASHES) {\n    const lastSeen = (h) => {\n      const list = obs[h] ?? [];\n      return list.reduce((m, x) => (String(x.ts ?? '') > m ? String(x.ts ?? '') : m), '');\n    };\n    hashes\n      .sort((a, b) => lastSeen(a).localeCompare(lastSeen(b)))\n      .slice(0, hashes.length - MAX_HASHES)\n      .forEach((h) => delete obs[h]);\n  }\n  return { store, added };\n}\n\n/** 把快照里的观测摊平成与 observationsFromScan 相同的形状（供 K1/K2 统一处理） */\nexport function observationsFromStore(store) {\n  const out = [];\n  for (const [hash, list] of Object.entries(store?.observations ?? {})) {\n    for (const o of list ?? []) {\n      out.push({ hash, session: o.session, ts: o.ts ?? null, chars: o.chars ?? 0, locator: o.locator ?? null });\n    }\n  }\n  return out;\n}\n\nexport function storeStats(store) {\n  const obs = store?.observations ?? {};\n  const hashes = Object.keys(obs);\n  const observations = hashes.reduce((n, h) => n + (obs[h]?.length ?? 0), 0);\n  return { hashes: hashes.length, observations, updatedAt: store?.updatedAt ?? null };\n}\n\n// ---------------------------------------------------------------------------\n// 一次运行的完整生命周期（调用方只需要这三个动作）\n// ---------------------------------------------------------------------------\n\n/**\n * 开始一次\"带指纹\"的运行。\n *\n * ⚠️ 顺序很重要：**必须在 scanSessions() 之前**调用 —— 适配层是在**解析时**\n * 就把用户文本算成指纹的（正文不落盘），没有先设好盐，这次扫描就不会带指纹。\n *\n * 用法：\n *   const fp = beginFingerprintRun();\n *   const scan = scanSessions({});\n *   const d = analyze({ scan, summary }, { ...opts, ...fp.diagnosticOpts(scan) });\n *   const outcome = fp.finish(scan);   // 合并 + 落盘；返回如实的结果给用户看\n *\n * @param {{path?:string, env?:NodeJS.ProcessEnv}} [opts]\n */\nexport function beginFingerprintRun(opts = {}) {\n  const env = opts.env ?? process.env;\n  const file = opts.path ?? STORE_PATH;\n\n  if (fingerprintsDisabled(env)) {\n    const skipped = '已按 AGENT_CLINIC_NO_FINGERPRINT_STORE=1 关闭指纹采集（K1/K2 本次不判定）';\n    return {\n      enabled: false,\n      store: null,\n      error: null,\n      skipped,\n      diagnosticOpts: (scan) => ({\n        fingerprintObservations: [],\n        fingerprintMissing: observationsFromScan(scan).missing,\n        fingerprintUnavailable: skipped,\n      }),\n      finish: () => ({ saved: false, added: 0, skipped, error: null }),\n    };\n  }\n\n  const { store, error, created } = loadStore({ path: file });\n  if (!store) {\n    // 读不出来就**如实报错**，不静默降级成\"没问题\"（本项目的硬规矩）\n    const note = `指纹快照读不出来：${error?.message ?? '未知原因'}（K1/K2 本次未判定；可删除 ${file} 后重跑）`;\n    return {\n      enabled: false,\n      store: null,\n      error,\n      skipped: null,\n      diagnosticOpts: (scan) => ({\n        fingerprintObservations: [],\n        fingerprintMissing: observationsFromScan(scan).missing,\n        fingerprintUnavailable: note,\n      }),\n      // phase='load'：连盐都没有，K1/K2 确实**没判**——措辞必须说\"未判定\"\n      finish: () => ({ saved: false, added: 0, skipped: null, error, phase: 'load', judged: false }),\n      note,\n    };\n  }\n\n  setActiveSalt(store.salt);\n  let finished = false;\n\n  return {\n    enabled: true,\n    store,\n    error: null,\n    skipped: null,\n    path: file,\n    created,\n    /**\n     * 给 runDiagnostics/analyze 的选项：把**本次扫描**的观测与**快照里**的历史观测\n     * 合在一起交给 K1/K2（这样上一次体检里出现过、本次已不在窗口内的会话也能被算进去）。\n     */\n    diagnosticOpts(scan) {\n      const { observations, missing } = observationsFromScan(scan);\n      return {\n        fingerprintObservations: [...observations, ...observationsFromStore(store)],\n        fingerprintStore: store,\n        fingerprintMissing: missing,\n      };\n    },\n    /** 合并 + 落盘。没有新观测时不写盘（避免每次空跑都改文件时间） */\n    finish(scan) {\n      if (finished) return { saved: false, added: 0, skipped: '本次运行已结束', error: null };\n      finished = true;\n      setActiveSalt(null);\n      const { observations, missing } = observationsFromScan(scan);\n      const { added } = mergeObservations(store, observations);\n      const stats = storeStats(store);\n      if (added === 0) {\n        return { saved: false, added: 0, missing, stats, path: file, error: null, phase: null, judged: true };\n      }\n      const res = saveStore(store, { path: file });\n      // ⚠️ 关键区分（这是我自己写错过的）：**写盘失败 ≠ 没判定**。\n      // 盐在本进程内存里是有的，本次扫描的指纹已经算出来了，K1/K2 照样判定了；\n      // 写失败的后果是\"跨会话历史不会累积\"，不是\"这次没查\"。说成\"未判定\"就成了假话。\n      return {\n        saved: res.ok,\n        added,\n        missing,\n        stats,\n        path: file,\n        error: res.error,\n        phase: res.ok ? null : 'save',\n        judged: true,\n      };\n    },\n  };\n}\n"
    },
    {
      "path": "src/catalog/live.mjs",
      "content": "/**\n * 体检时**联网现搜**插件 —— 「发现问题就去网上找方案」。\n *\n * 为什么要有它（用户原话）：\n *   「我想要的结果是发现问题后联网搜索得到解决方案」\n *   在它之前，体检只读一份可能过期的快照：新出的插件要手动跑 `catalog-sync` 才看得见。\n *   现在 `report --live` 会在诊断出问题的当下，按**问题的能力需求**去 npm 与 GitHub 现搜。\n *\n * 三条硬约束（都是刻意的）：\n *   1. **只发问题类型，不发你的会话内容。**\n *      检索词来自 `CAPABILITY_TERMS`（如 `context compression`），\n *      绝不包含会话 id、消息文本、工具输出、文件路径。返回结果里 `sent` 字段\n *      原样列出**实际发出的每一条检索词**，可自行核对。\n *   2. **不能拖死体检。** 总预算 `budgetMs`（默认 12s），超时即停，\n *      带着已拿到的部分返回，并标记 `degraded`；网络全断也只是\"本次没搜到\"，\n *      而不是报告失败。\n *   3. **不编造。** 拿不到的字段一律 `null` / 缺失，热度只在真取到时才展示。\n *\n * 用法（在 `src/report.mjs` 的 `analyze({ live: true })` 里调用）：\n *   const live = await searchPluginsLive(findings, { budgetMs: 12000 });\n *   // live.entries 与快照条目同构，可直接喂给 searchCatalog({ catalog: entries })\n */\n\nimport { fetchJson, mapLimit, UA_LIVE } from './http.mjs';\nimport {\n  CAPABILITY_TERMS,\n  deriveCapabilities,\n  installOf,\n  textOf,\n} from './capabilities.mjs';\nimport { CAPABILITY_BY_METRIC } from './index.mjs';\n\n// 供测试与文档引用「联网时到底可能发出哪些词」的完整词表\nexport { CAPABILITY_TERMS };\n\nexport const LIVE_DEFAULTS = {\n  budgetMs: 12000, // 总预算：到点就收手，不阻塞体检\n  perRequestMs: 6000, // 单次 HTTP 上限\n  npmSize: 60, // 每条 npm 检索式取多少条\n  npmQueryCap: 4, // 最多几条检索式（含固定的那条）\n  detailLimit: 30, // 最多抓多少个包的 packument\n  githubQueryCap: 3,\n  githubLimit: 12, // 每条 GitHub 检索式取多少仓库\n  concurrency: 6,\n  // api.github.com 被 hosts 拦死时改走公共中继（实测 gh-proxy.com 可原样中继 API）\n  ghRelays: ['', 'https://gh-proxy.com/'],\n};\n\n/** 官方内置包（已随 dsh-base 分发，不该再推荐安装） */\nconst isOfficialBundle = (name) => /^@deepseek-ai\\/dsh($|-)/.test(String(name));\n\n/** 看起来像 DSH 插件吗（npm 全文检索会带回一堆无关包，必须过滤） */\nexport function looksDsh(pkg) {\n  const name = String(pkg?.name ?? '');\n  const kw = (pkg?.keywords ?? []).join(' ').toLowerCase();\n  const desc = String(pkg?.description ?? '').toLowerCase();\n  return (\n    /\\bdsh\\b/i.test(name) ||\n    /^dsh-|[-/]dsh-/.test(name) ||\n    kw.includes('dsh') ||\n    /dsh[- ]?(plugin|hub)|deepseek harness/i.test(`${name} ${desc}`)\n  );\n}\n\n/** 本轮问题需要哪些能力（去重，并记下是哪个指标提的） */\nexport function capabilitiesForFindings(findings = []) {\n  const byCap = new Map();\n  for (const f of findings) {\n    for (const cap of CAPABILITY_BY_METRIC[f?.id] ?? []) {\n      if (!CAPABILITY_TERMS[cap]) continue; // 没有检索词的能力（内部标签）跳过\n      if (!byCap.has(cap)) byCap.set(cap, []);\n      byCap.get(cap).push(f.id);\n    }\n  }\n  return [...byCap.entries()].map(([cap, metrics]) => ({ cap, metrics, terms: CAPABILITY_TERMS[cap] }));\n}\n\n/**\n * 构造检索式。**这是唯一决定\"什么飞出本机\"的地方** ——\n * 返回的 `sent` 会被原样写进报告，供核对。\n */\nexport function buildLiveQueries(findings = [], opts = {}) {\n  const o = { ...LIVE_DEFAULTS, ...opts };\n  const caps = capabilitiesForFindings(findings);\n\n  // npm：先一条广谱的（抓最新上架的 dsh 插件），再按能力补\n  const npm = [`keywords:dsh-plugin`];\n  for (const { terms } of caps) {\n    for (const t of terms) {\n      if (npm.length >= o.npmQueryCap) break;\n      if (!npm.includes(t)) npm.push(t);\n    }\n    if (npm.length >= o.npmQueryCap) break;\n  }\n\n  // GitHub：广谱按最近更新 + 按能力关键词\n  const github = ['topic:dsh-plugin'];\n  for (const { terms } of caps) {\n    if (github.length >= o.githubQueryCap) break;\n    const t = terms[0];\n    if (!github.includes(t)) github.push(`${t} dsh`);\n  }\n\n  return { caps, npm, github, sent: [...npm.map((q) => `npm: ${q}`), ...github.map((q) => `github: ${q}`)] };\n}\n\n// ---------------------------------------------------------------------------\n// HTTP（带总预算）\n// ---------------------------------------------------------------------------\n\nfunction makeBudget(totalMs) {\n  const startedAt = Date.now();\n  return {\n    startedAt,\n    /** 还剩多少预算；<=0 表示该收手了 */\n    left: () => totalMs - (Date.now() - startedAt),\n    expired: () => Date.now() - startedAt >= totalMs,\n  };\n}\n\n/** GitHub API 中继：直连优先，失败逐个试公共镜像，并记住能用的那个 */\nfunction makeGhClient(relays, perRequestMs) {\n  let good = null;\n  return {\n    get workingRelay() {\n      return good;\n    },\n    async json(pathWithQuery) {\n      const order = good !== null ? [good, ...relays.filter((r) => r !== good)] : relays;\n      let lastErr = null;\n      for (const relay of order) {\n        try {\n          const doc = await fetchJson(`${relay}https://api.github.com${pathWithQuery}`, {\n            timeoutMs: perRequestMs,\n            userAgent: UA_LIVE,\n          });\n          good = relay;\n          return doc;\n        } catch (e) {\n          lastErr = e;\n        }\n      }\n      throw lastErr ?? new Error('无可用 GitHub 通道');\n    },\n  };\n}\n\n// ---------------------------------------------------------------------------\n// 条目构造（与 catalog-sync 的 npm 条目同构：报告/面板可直接复用渲染）\n// ---------------------------------------------------------------------------\n\nfunction npmEntry({ pkg, doc }) {\n  const latest = doc?.['dist-tags']?.latest ?? pkg.version;\n  const ver = doc?.versions?.[latest] ?? {};\n  const hub = ver.dshhub ?? ver.dsh?.hub ?? null;\n  const caps = deriveCapabilities(textOf(pkg, hub));\n  return {\n    id: `npm:${pkg.name}`,\n    package: pkg.name,\n    displayName: hub?.displayName || pkg.name,\n    summary: hub?.summary || pkg.description || '(npm 未提供描述)',\n    summaryLang: 'en', // 中文覆盖层由目录层统一套用；未覆盖的如实标英文原文\n    version: latest ?? null,\n    repo:\n      (ver.repository && (ver.repository.url || ver.repository)) ||\n      pkg.links?.repository ||\n      pkg.links?.npm ||\n      null,\n    keywords: pkg.keywords ?? [],\n    capabilities: [...new Set(caps.map((c) => c.cap))],\n    capabilityEvidence: caps,\n    hasDshBundlePatch: Boolean(ver.dsh?.bundle?.patch),\n    dshCompatibility: ver.dsh?.compatibility?.dsh ?? hub?.compatibility?.dsh ?? null,\n    license: ver.license ?? doc?.license ?? null,\n    publishedAt: doc?.time?.[latest] ?? null,\n    heat: {\n      weeklyDownloads: pkg.weeklyDownloads ?? null,\n      monthlyDownloads: pkg.monthlyDownloads ?? null,\n      dependents: pkg.dependents ?? null,\n      updatedAt: pkg.date ?? doc?.time?.[latest] ?? null,\n      source: 'npm 搜索的下载量统计',\n    },\n    install: installOf(pkg.name),\n    origin: 'npm-live',\n    kind: isOfficialBundle(pkg.name) ? 'bundled' : 'community',\n    live: true,\n    source: {\n      type: 'third-party',\n      package: pkg.name,\n      doc: `npm registry packument（实时抓取；dshhub=${hub ? '有' : '无'}）`,\n      via: `本次体检联网现搜（匹配式：${pkg.__query ?? 'n/a'}）`,\n      verifiedAt: new Date().toISOString().slice(0, 10),\n    },\n    risk:\n      `本次联网现搜到的社区插件（未逐行审阅源码）。` +\n      `安装前请自行看仓库：${(ver.repository && (ver.repository.url || ver.repository)) || pkg.links?.repository || '(未提供)'}`,\n    verify: `装完重启，确认「${hub?.displayName || pkg.name}」在插件页处于已启用状态`,\n    targets: [],\n  };\n}\n\nfunction githubEntry(repo, query) {\n  const caps = deriveCapabilities(\n    [repo.name, repo.full_name, repo.description, (repo.topics ?? []).join(' ')].filter(Boolean).join(' \\n '),\n  );\n  const slug = repo.full_name;\n  return {\n    id: `github:${slug}`,\n    package: slug,\n    displayName: slug,\n    summary: repo.description || '(仓库未提供描述)',\n    summaryLang: 'en',\n    keywords: repo.topics ?? [],\n    capabilities: [...new Set(caps.map((c) => c.cap))],\n    capabilityEvidence: caps,\n    repo: `https://github.com/${slug}`,\n    install: {\n      gui: `按仓库 README 安装（本工具不代装）—— https://github.com/${slug}`,\n      cli: `git clone https://github.com/${slug}.git   # 再按仓库说明挂载`,\n    },\n    heat: {\n      stars: repo.stargazers_count ?? null,\n      forks: repo.forks_count ?? null,\n      updatedAt: repo.pushed_at ?? repo.updated_at ?? null,\n      source: 'GitHub API（实时）',\n    },\n    origin: 'github-live',\n    kind: 'community',\n    live: true,\n    source: {\n      type: 'third-party',\n      package: slug,\n      doc: 'GitHub 仓库（实时检索；只核实仓库存在与元数据，未审阅源码）',\n      via: `本次体检联网现搜（匹配式：${query}）`,\n      verifiedAt: new Date().toISOString().slice(0, 10),\n    },\n    risk: `来自 GitHub（未发 npm；只核实了仓库存在与元数据，未审阅源码）。安装需按仓库 README 自行操作：https://github.com/${slug}`,\n    verify: '按仓库 README 挂载后重启，确认出现在插件页',\n    targets: [],\n  };\n}\n\n// ---------------------------------------------------------------------------\n// 两个来源\n// ---------------------------------------------------------------------------\n\nasync function liveNpm(queries, o, budget, errors, sink) {\n  const hits = new Map(); // name → pkg（带 __query 记录命中来源）\n  for (const q of queries) {\n    if (budget.expired()) break;\n    sink.searched = (sink.searched ?? 0) + 1;\n    const url = `https://registry.npmjs.org/-/v1/search?text=${encodeURIComponent(q)}&size=${o.npmSize}`;\n    let doc;\n    try {\n      doc = await fetchJson(url, {\n        timeoutMs: Math.min(o.perRequestMs, Math.max(1000, budget.left())),\n        userAgent: UA_LIVE,\n      });\n    } catch (e) {\n      errors.push(`npm 检索「${q}」失败：${e.message}`);\n      continue;\n    }\n    for (const obj of doc.objects ?? []) {\n      const pkg = obj.package ?? {};\n      // 全文检索会带回大量无关包：必须是 DSH 插件，且不是已内置的官方包\n      if (!looksDsh(pkg)) continue;\n      if (isOfficialBundle(pkg.name)) continue;\n      const prev = hits.get(pkg.name);\n      if (prev) {\n        prev.__query = `${prev.__query} + ${q}`;\n        continue;\n      }\n      hits.set(pkg.name, { ...pkg, weeklyDownloads: obj.downloads?.weekly ?? null, monthlyDownloads: obj.downloads?.monthly ?? null, dependents: obj.dependents ?? null, __query: q });\n    }\n  }\n\n  // 按真实周下载量排序后取前 N 抓 packument（拿 dshhub 元数据与能力标签）\n  const candidates = [...hits.values()].sort(\n    (a, b) => (b.weeklyDownloads ?? -1) - (a.weeklyDownloads ?? -1),\n  );\n  const detail = candidates.slice(0, o.detailLimit);\n  sink.candidates = candidates.length;\n\n  // 边抓边写进 sink：预算耗尽被强停时，已拿到的条目**不能丢**\n  // （踩过的坑：超时后整条 npm 通道被丢弃，一次丢掉 26 条）\n  const entries = [];\n  sink.entries = entries;\n\n  await mapLimit(detail, o.concurrency, async (p) => {\n    if (budget.expired()) return { error: '预算用尽' };\n    let doc;\n    try {\n      doc = await fetchJson(\n        `https://registry.npmjs.org/${encodeURIComponent(p.name).replace('%40', '@')}`,\n        {\n          timeoutMs: Math.min(o.perRequestMs, Math.max(1000, budget.left())),\n          userAgent: UA_LIVE,\n        },\n      );\n    } catch (e) {\n      // aborted = 预算到点被掐断，不算异常；真实 HTTP 错误才记录\n      if (!/abort/i.test(e.message)) errors.push(`npm packument「${p.name}」失败：${e.message}`);\n      return { error: e.message };\n    }\n    try {\n      entries.push(npmEntry({ pkg: p, doc }));\n    } catch (e) {\n      errors.push(`npm 条目「${p.name}」解析失败：${e.message}`);\n    }\n    return { ok: true };\n  });\n\n  return { entries, candidates: candidates.length, searched: sink.searched ?? 0 };\n}\n\nasync function liveGithub(queries, o, budget, errors, sink) {\n  const gh = makeGhClient(o.ghRelays, o.perRequestMs);\n  const seen = new Map();\n  for (const q of queries) {\n    if (budget.expired()) break;\n    sink.searched = (sink.searched ?? 0) + 1;\n    const path =\n      `/search/repositories?q=${encodeURIComponent(q)}` +\n      `&sort=${q.includes('topic:') ? 'updated' : 'stars'}&per_page=${o.githubLimit}`;\n    let doc;\n    try {\n      doc = await gh.json(path);\n    } catch (e) {\n      errors.push(`GitHub 检索「${q}」失败：${e.message}`);\n      continue;\n    }\n    for (const repo of doc.items ?? []) {\n      const slug = repo.full_name;\n      if (!slug || seen.has(slug)) continue;\n      // 相关性：DSH 主题标签、或名称/描述里真的提到 dsh / deepseek harness\n      const text = `${repo.name} ${slug} ${repo.description ?? ''} ${(repo.topics ?? []).join(' ')}`;\n      if (!/dsh|deepseek[- ]?harness/i.test(text)) continue;\n      seen.set(slug, { ...repo, __query: q });\n    }\n    // 每检索完一式就刷新 sink：被预算强停时保留已完成的部分\n    sink.entries = [...seen.values()].map((r) => githubEntry(r, r.__query));\n    sink.candidates = seen.size;\n    sink.relay = gh.workingRelay;\n  }\n  const entries = sink.entries ?? [];\n  return { entries, candidates: seen.size, relay: gh.workingRelay, searched: sink.searched ?? 0 };\n}\n\n/**\n * 联网现搜主入口。\n *\n * 永不抛：任何一条通道失败都只记录到 `errors` 并降级，体检继续。\n *\n * @returns {Promise<{\n *   entries:Array, caps:Array, queries:{npm:Array, github:Array}, sent:Array,\n *   stats:Object, errors:Array, degraded:boolean, elapsedMs:number, fetchedAt:string\n * }>}\n */\nexport async function searchPluginsLive(findings = [], opts = {}) {\n  const o = { ...LIVE_DEFAULTS, ...opts };\n  o.ghRelays = opts.ghRelays ?? LIVE_DEFAULTS.ghRelays;\n  const budget = makeBudget(o.budgetMs);\n  const errors = [];\n  const { caps, npm, github, sent } = buildLiveQueries(findings, o);\n\n  let npmRes = { entries: [], candidates: 0, searched: 0 };\n  let ghRes = { entries: [], candidates: 0, relay: null, searched: 0 };\n\n  if (opts.network === false) {\n    errors.push('已禁用联网（--no-network）');\n  } else if (findings.length === 0) {\n    errors.push('本次没有发现问题，未发起联网检索');\n  } else {\n    // 两条通道并行，各自独立降级。\n    // ⚠️ 必须有**硬截止**：单看每请求超时是不够的（实测 12s 预算跑了 14.7s，\n    //    因为并发里的在途请求会拖过预算）。到点就带着已拿到的部分返回。\n    let timedOut = false;\n    // sink 是**可增量读取的共享状态**：通道每拿到一点就写进来，\n    // 所以即使被强停，已抓到的条目也不会丢。\n    const sink = {\n      npm: { entries: [], candidates: 0, searched: 0, relay: null },\n      gh: { entries: [], candidates: 0, searched: 0, relay: null },\n    };\n    const work = Promise.all([\n      liveNpm(npm, o, budget, errors, sink.npm)\n        .then((r) => {\n          sink.npm = r;\n        })\n        .catch((e) => {\n          errors.push(`npm 通道异常：${e.message}`);\n        }),\n      liveGithub(github, o, budget, errors, sink.gh)\n        .then((r) => {\n          sink.gh = r;\n        })\n        .catch((e) => {\n          errors.push(`GitHub 通道异常：${e.message}`);\n        }),\n    ]);\n    const timer = new Promise((resolve) => setTimeout(resolve, o.budgetMs + 250));\n    await Promise.race([work, timer]).then(() => {\n      timedOut = budget.expired();\n    });\n    npmRes = {\n      entries: sink.npm.entries ?? [],\n      candidates: sink.npm.